"use client";

import { ReactFlowProvider, type Connection } from "@xyflow/react";
import clsx from "clsx";
import { AlertTriangle, Info, X, XCircle } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { ArchitectureCanvas, type CenterRequest } from "@/components/ArchitectureCanvas";
import type { NodeActions } from "@/components/CustomNode";
import { ImportDialog } from "@/components/ImportDialog";
import { InspectorPanel } from "@/components/InspectorPanel";
import { GuidedTour } from "@/components/GuidedTour";
import { CUSTOM_UPLOAD_OPTION, TopNav } from "@/components/TopNav";
import { useAutosave } from "@/hooks/useAutosave";
import { useExport } from "@/hooks/useExport";
import { useGuidedTour } from "@/hooks/useGuidedTour";
import { usePreload } from "@/hooks/usePreload";
import { useShortcuts } from "@/hooks/useShortcuts";
import { useWorkspace, type Notice } from "@/hooks/useWorkspace";
import { fetchEngine, requestImpact, requestRepoFromFiles, requestRepoFromGithub, requestScaffold, requestStory } from "@/lib/apiClient";
import { analyzeHealth } from "@/lib/engines/health";
import { traceProvenance } from "@/lib/engines/provenance";
import { evaluateRules } from "@/lib/engines/rules";
import { commitsFromGitLog } from "@/lib/engines/story";
import { kebabCase } from "@/lib/engines/localScaffold";
import { findSample, SAMPLE_PROMPTS, SAMPLE_REPOSITORIES } from "@/lib/mockData";
import type { SavedWorkspace } from "@/lib/persistence";
import { readUpload } from "@/lib/portability";
import type { ArchitectureGraph, ArchNode, EngineInfo, NodeKind } from "@/lib/types";
import { buildRenderGraph } from "@/lib/viewModel";

const STORY_STEP_MS = 2600;
const DRAFT_VERTICAL_GAP_PX = 200;

const NOTICE_STYLE: Record<Notice["tone"], { box: string; icon: typeof Info }> = {
  info: { box: "border-sky-500/30 bg-sky-950/80 text-sky-100", icon: Info },
  warning: { box: "border-amber-500/30 bg-amber-950/80 text-amber-100", icon: AlertTriangle },
  error: { box: "border-red-500/30 bg-red-950/80 text-red-100", icon: XCircle },
};

const errorMessage = (error: unknown) => (error instanceof Error ? error.message : String(error));

export default function Page() {
  const [state, dispatch] = useWorkspace();
  const { graph } = state;
  const [engine, setEngine] = useState<EngineInfo | null>(null);
  const [importedGraph, setImportedGraph] = useState<ArchitectureGraph | null>(null);
  const [importState, setImportState] = useState<{ open: boolean; busy: boolean; error: string | null }>({ open: false, busy: false, error: null });
  const [centerRequest, setCenterRequest] = useState<CenterRequest | null>(null);
  const centerNonce = useRef(0);

  // Async results are discarded if the user switched repositories while waiting.
  const graphIdRef = useRef(graph.id);
  graphIdRef.current = graph.id;
  const graphRef = useRef(graph);
  graphRef.current = graph;

  const notify = useCallback((notice: Notice | null) => dispatch({ type: "notify", notice }), [dispatch]);

  useEffect(() => {
    void fetchEngine().then((info) => {
      setEngine(info);
      if (info.error) notify({ tone: "warning", message: `AI provider misconfigured — using the local engine. ${info.error}` });
    });
  }, [notify]);

  /* ---------- Story playback ---------- */
  const { isPlaying, index: storyIndex } = state.story;
  useEffect(() => {
    if (!isPlaying) return;
    if (storyIndex >= graph.commits.length - 1) {
      dispatch({ type: "setStoryPlaying", isPlaying: false });
      return;
    }
    const timer = setTimeout(() => dispatch({ type: "setStoryIndex", index: storyIndex + 1 }), STORY_STEP_MS);
    return () => clearTimeout(timer);
  }, [isPlaying, storyIndex, graph.commits.length, dispatch]);

  /* ---------- Derived canvas model ---------- */
  const healthReport = useMemo(() => analyzeHealth(graph), [graph]);
  const violations = useMemo(() => evaluateRules(graph), [graph]);
  const trace = useMemo(() => (state.trace ? traceProvenance(graph, state.trace) : null), [graph, state.trace]);
  const isHealthView = state.activeTab === "health";
  const focusNodeId = state.focusEnabled ? state.selectedNodeId : null;
  const { nodes, edges } = useMemo(
    () => buildRenderGraph({ graph, impact: state.impact.result, story: state.story, health: isHealthView ? healthReport : null, focusNodeId, selectedNodeId: state.selectedNodeId, violations: isHealthView ? violations : [], trace }),
    [graph, state.impact.result, state.story, isHealthView, healthReport, focusNodeId, state.selectedNodeId, violations, trace],
  );
  const reportOptions = useMemo(() => ({ impact: state.impact.result, trace }), [state.impact.result, trace]);
  const exporter = useExport({ graph, nodes, edges, report: reportOptions, notify });

  /** Select a component and pan/zoom the canvas to it. */
  const selectAndCenter = useCallback(
    (nodeId: string) => {
      dispatch({ type: "selectNode", nodeId });
      setCenterRequest({ nodeId, nonce: ++centerNonce.current });
    },
    [dispatch],
  );

  const tour = useGuidedTour(dispatch);
  useShortcuts({ dispatch, tourOpen: tour.open, hasTrace: state.trace !== null, openTour: () => tour.setOpen(true) });

  /* ---------- Handlers ---------- */
  const loadGraph = useCallback((next: ArchitectureGraph) => dispatch({ type: "loadGraph", graph: next }), [dispatch]);
  const restoreSaved = useCallback(
    (saved: SavedWorkspace) => {
      if (saved.original) setImportedGraph(saved.original);
      loadGraph(saved.graph);
    },
    [loadGraph],
  );
  // A folder passed to `codearchitect view` wins over whatever was saved last time, in either order of arrival.
  const preloadedRef = useRef(false);
  const autosave = useAutosave({ graph, importedGraph, onRestore: (saved) => !preloadedRef.current && restoreSaved(saved), onReset: loadGraph });

  const selectRepository = (id: string) => {
    if (id === CUSTOM_UPLOAD_OPTION) {
      setImportState({ open: true, busy: false, error: null });
      return;
    }
    const next = id === importedGraph?.id ? importedGraph : findSample(id);
    if (!next) return;
    // Prefer the user's saved edits over the pristine copy.
    void autosave.loadSaved(id).then((saved) => (saved ? restoreSaved(saved) : loadGraph(next)));
  };

  const runImpact = useCallback(async () => {
    const snapshot = graphRef.current;
    const prompt = state.impactPrompt.trim();
    if (!prompt) {
      dispatch({ type: "setTab", tab: "blast" });
      return;
    }
    dispatch({ type: "setTab", tab: "blast" });
    dispatch({ type: "impactStarted" });
    try {
      const { data, warning } = await requestImpact(snapshot, prompt, state.selectedNodeId);
      if (graphIdRef.current !== snapshot.id) return;
      dispatch({ type: "impactSucceeded", result: data });
      if (warning) notify({ tone: "warning", message: warning });
    } catch (error) {
      if (graphIdRef.current === snapshot.id) dispatch({ type: "impactFailed", error: errorMessage(error) });
    }
  }, [state.impactPrompt, state.selectedNodeId, dispatch, notify]);

  const simulateFrom = useCallback(
    (nodeId: string, symbol?: string) => {
      dispatch({ type: "selectNode", nodeId });
      if (symbol) dispatch({ type: "setImpactPrompt", prompt: `Change ${symbol}` });
      dispatch({ type: "setTab", tab: "blast" });
    },
    [dispatch],
  );

  const nodeActions = useMemo<NodeActions>(
    () => ({
      inspect: (nodeId) => {
        dispatch({ type: "selectNode", nodeId });
        dispatch({ type: "setTab", tab: "inspector" });
      },
      simulateFrom,
      copyPath: (filePath) => {
        navigator.clipboard.writeText(filePath).then(
          () => notify({ tone: "info", message: `Copied ${filePath}` }),
          () => notify({ tone: "error", message: "Clipboard access was denied." }),
        );
      },
    }),
    [dispatch, notify, simulateFrom],
  );

  const narrate = async () => {
    const snapshot = graphRef.current;
    dispatch({ type: "storyNarrationStarted" });
    try {
      const { data, warning } = await requestStory(snapshot);
      if (graphIdRef.current !== snapshot.id) return;
      dispatch({ type: "storyNarrated", narrative: data });
      if (warning) notify({ tone: "warning", message: warning });
      else if (data.engine === "local") notify({ tone: "info", message: "No AI model is configured — showing commit-derived narratives." });
    } catch (error) {
      dispatch({ type: "storyNarrationFailed" });
      notify({ tone: "error", message: errorMessage(error) });
    }
  };

  const importGitLog = (text: string) => {
    try {
      const commits = commitsFromGitLog(text, graph.nodes);
      dispatch({ type: "setCommits", commits });
      const mapped = commits.filter((c) => c.addedNodeIds.length + c.modifiedNodeIds.length > 0).length;
      notify({ tone: "info", message: `Imported ${commits.length} commits; ${mapped} touch components on this map.` });
    } catch (error) {
      notify({ tone: "error", message: errorMessage(error) });
    }
  };

  const addComponent = ({ label, kind, filePath, description }: { label: string; kind: NodeKind; filePath: string; description: string }) => {
    const base = `draft-${kebabCase(label) || "component"}`;
    let id = base;
    for (let n = 2; graph.nodes.some((node) => node.id === id); n++) id = `${base}-${n}`;
    const anchor = graph.nodes.find((node) => node.id === state.selectedNodeId);
    const lowest = Math.max(0, ...graph.nodes.map((node) => node.position.y));
    const node: ArchNode = {
      id,
      type: "component",
      position: anchor ? { x: anchor.position.x + 260, y: anchor.position.y + 40 } : { x: 260, y: lowest + DRAFT_VERTICAL_GAP_PX },
      data: { label, kind, filePath, description, language: filePath.split(".").pop() ?? "ts", code: `// ${label} — not generated yet`, exports: [], imports: [], params: [], keywords: kebabCase(label).split("-"), isDraft: true },
    };
    dispatch({ type: "addDraftNode", node });
  };

  const connect = (connection: Connection) => {
    if (!connection.source || !connection.target) return;
    dispatch({
      type: "addDraftEdge",
      edge: { id: `draft-e-${connection.source}--${connection.target}`, source: connection.source, target: connection.target, relation: "calls", isDraft: true },
    });
  };

  const generateScaffold = async () => {
    const snapshot = graphRef.current;
    dispatch({ type: "scaffoldStarted" });
    try {
      const { data, warning } = await requestScaffold(snapshot);
      if (graphIdRef.current !== snapshot.id) return;
      dispatch({ type: "scaffoldSucceeded", result: data });
      if (warning) notify({ tone: "warning", message: warning });
    } catch (error) {
      dispatch({ type: "scaffoldFailed", error: errorMessage(error) });
    }
  };

  const finishImport = (next: ArchitectureGraph, warning?: string) => {
    setImportedGraph(next);
    loadGraph(next);
    setImportState({ open: false, busy: false, error: null });
    const notes = [warning, ...(next.warnings ?? [])].filter(Boolean).join(" ");
    if (notes) notify({ tone: "warning", message: notes });
  };

  usePreload(
    ({ graph: preloaded }) => {
      preloadedRef.current = true;
      finishImport(preloaded);
    },
    (message) => notify({ tone: "error", message }),
  );

  const uploadFile = async (file: File) => {
    setImportState((s) => ({ ...s, busy: true, error: null }));
    try {
      const upload = await readUpload(file);
      if (upload.kind === "graph") return finishImport(upload.graph);
      if (upload.files.length === 0) throw new Error("No supported source files found in the archive.");
      const { data, warning } = await requestRepoFromFiles(upload.name, upload.files);
      finishImport(data, [warning, upload.skipped ? `${upload.skipped} oversized file(s) skipped.` : ""].filter(Boolean).join(" ") || undefined);
    } catch (error) {
      setImportState((s) => ({ ...s, busy: false, error: errorMessage(error) }));
    }
  };

  const analyzeGithub = async (url: string) => {
    setImportState((s) => ({ ...s, busy: true, error: null }));
    try {
      const { data, warning } = await requestRepoFromGithub(url);
      finishImport(data, warning);
    } catch (error) {
      setImportState((s) => ({ ...s, busy: false, error: errorMessage(error) }));
    }
  };

  const notice = state.notice;
  const NoticeIcon = notice ? NOTICE_STYLE[notice.tone].icon : Info;

  return (
    <div className="flex h-dvh flex-col bg-[radial-gradient(ellipse_at_top_left,_rgba(139,92,246,0.10),_transparent_50%),radial-gradient(ellipse_at_bottom_right,_rgba(14,165,233,0.08),_transparent_50%)] bg-zinc-950">
      <TopNav
        graph={graph}
        samples={SAMPLE_REPOSITORIES}
        importedGraph={importedGraph}
        engine={engine}
        isStoryOn={state.story.enabled}
        isImpactActive={state.impact.result !== null || state.impact.status === "running"}
        exporting={exporter.busy}
        saveStatus={autosave.status}
        isEdited={autosave.dirty}
        onReset={autosave.reset}
        onSelectRepository={selectRepository}
        onSimulate={() => void runImpact()}
        onToggleStory={() => dispatch({ type: "toggleStory" })}
        onExport={(kind) => void exporter.run(kind)}
        onHelp={() => tour.setOpen(true)}
      />

      <main className="flex min-h-0 flex-1 flex-col lg:flex-row">
        <section data-tour="canvas" className="relative h-[45vh] min-h-0 sm:h-[55vh] lg:h-auto lg:basis-[65%]" aria-label="Architecture graph">
          <ReactFlowProvider>
            <ArchitectureCanvas
              graphKey={graph.id}
              kindLabels={graph.kindLabels}
              centerRequest={centerRequest}
              searchNodes={graph.nodes}
              onSearchSelect={selectAndCenter}
              focusEnabled={state.focusEnabled}
              hasSelection={state.selectedNodeId !== null}
              onToggleFocus={() => dispatch({ type: "toggleFocus" })}
              banner={
                trace && (
                  <div className="flex items-center gap-2 self-start rounded-full border border-cyan-500/50 bg-cyan-950/85 py-1 pl-3 pr-1.5 text-xs text-cyan-100 shadow-lg backdrop-blur">
                    <span>
                      {trace.mode === "upstream" ? "Where" : "What"} <b>{graph.nodes.find((n) => n.id === trace.nodeId)?.data.label}</b> {trace.mode === "upstream" ? "comes from" : "affects"} ·{" "}
                      {trace.nodeIds.length - 1} other{trace.nodeIds.length === 2 ? "" : "s"}
                    </span>
                    <button type="button" onClick={() => dispatch({ type: "setTrace", trace: null })} className="rounded-full bg-cyan-500/20 px-2 py-0.5 font-medium hover:bg-cyan-500/35">
                      Clear (Esc)
                    </button>
                  </div>
                )
              }
              nodes={nodes}
              edges={edges}
              actions={nodeActions}
              onNodesChange={(changes) => dispatch({ type: "nodesChanged", changes })}
              onSelectNode={(nodeId) => dispatch({ type: "selectNode", nodeId })}
              onConnect={connect}
              onRemoveDraftEdge={(edgeId) => dispatch({ type: "removeDraftEdge", edgeId })}
            />
          </ReactFlowProvider>

          {!trace && state.story.enabled && graph.commits[state.story.index] && (
            <div className="pointer-events-none absolute inset-x-0 top-14 flex justify-center">
              <div className="rounded-full border border-violet-500/40 bg-violet-950/80 px-3 py-1 text-xs text-violet-100 backdrop-blur">
                <span className="font-mono text-violet-300">{graph.commits[state.story.index]!.hash}</span> · {graph.commits[state.story.index]!.phase}
              </div>
            </div>
          )}

          {notice && (
            <div role="status" className={clsx("absolute bottom-4 left-16 right-48 z-10 flex max-w-xl items-start gap-2 rounded-lg border px-3 py-2 text-xs shadow-xl backdrop-blur", NOTICE_STYLE[notice.tone].box)}>
              <NoticeIcon className="mt-0.5 h-3.5 w-3.5 shrink-0" />
              <span className="flex-1 leading-relaxed">{notice.message}</span>
              <button type="button" aria-label="Dismiss" onClick={() => notify(null)} className="opacity-70 hover:opacity-100">
                <X className="h-3.5 w-3.5" />
              </button>
            </div>
          )}
        </section>

        <div className="min-h-0 flex-1 lg:basis-[35%] lg:min-w-[380px]">
          <InspectorPanel
            state={state}
            dispatch={dispatch}
            samplePrompts={SAMPLE_PROMPTS[graph.id] ?? []}
            healthReport={healthReport}
            violations={violations}
            trace={trace}
            onTrace={(request) => dispatch({ type: "setTrace", trace: request })}
            onSelectAndCenter={selectAndCenter}
            onRunImpact={() => void runImpact()}
            onSimulate={simulateFrom}
            onNarrate={() => void narrate()}
            onImportGitLog={importGitLog}
            onAddComponent={addComponent}
            onGenerateScaffold={() => void generateScaffold()}
          />
        </div>
      </main>

      <GuidedTour open={tour.open} onClose={tour.close} onEnterStep={tour.enterStep} />

      <ImportDialog
        open={importState.open}
        isBusy={importState.busy}
        error={importState.error}
        onClose={() => setImportState({ open: false, busy: false, error: null })}
        onUploadFile={(file) => void uploadFile(file)}
        onGithubUrl={(url) => void analyzeGithub(url)}
      />
    </div>
  );
}

"use client";

import clsx from "clsx";
import { Bot, ChevronDown, Cpu, FolderGit2, HelpCircle, History, Network, Radar, RotateCcw } from "lucide-react";
import { ExportMenu } from "@/components/ExportMenu";
import type { SaveStatus } from "@/hooks/useAutosave";
import type { ExportKind } from "@/hooks/useExport";
import type { ArchitectureGraph, EngineInfo } from "@/lib/types";

export const CUSTOM_UPLOAD_OPTION = "__custom_upload__";

type Props = {
  graph: ArchitectureGraph;
  samples: readonly ArchitectureGraph[];
  importedGraph: ArchitectureGraph | null;
  engine: EngineInfo | null;
  isStoryOn: boolean;
  isImpactActive: boolean;
  exporting: ExportKind | null;
  saveStatus: SaveStatus;
  /** True when the graph differs from its original (so Reset has something to undo). */
  isEdited: boolean;
  onReset: () => void;
  onSelectRepository: (id: string) => void;
  onSimulate: () => void;
  onToggleStory: () => void;
  onExport: (kind: ExportKind) => void;
  onHelp: () => void;
};

function NavButton({ onClick, active, disabled, children, tone, tour, title }: { onClick: () => void; active?: boolean; disabled?: boolean; children: React.ReactNode; tone: "red" | "violet" | "zinc"; tour?: string; title?: string }) {
  const tones = {
    red: active ? "border-red-500/60 bg-red-500/15 text-red-200" : "border-zinc-700 text-zinc-300 hover:border-red-500/50 hover:text-red-200",
    violet: active ? "border-violet-500/60 bg-violet-500/15 text-violet-200" : "border-zinc-700 text-zinc-300 hover:border-violet-500/50 hover:text-violet-200",
    zinc: "border-zinc-700 text-zinc-300 hover:border-zinc-500 hover:text-white",
  };
  return (
    <button
      type="button"
      onClick={onClick}
      disabled={disabled}
      aria-pressed={active}
      data-tour={tour}
      title={title}
      className={clsx("flex items-center gap-1.5 whitespace-nowrap rounded-lg border px-2.5 py-1.5 text-xs font-medium transition disabled:opacity-50", tones[tone])}
    >
      {children}
    </button>
  );
}

export function TopNav(props: Props) {
  const { graph, samples, importedGraph, engine } = props;

  return (
    <header className="flex shrink-0 flex-wrap items-center gap-2 border-b border-zinc-800/80 bg-zinc-950/80 px-3 py-2 backdrop-blur-xl sm:gap-3 sm:px-4 sm:py-2.5">
      <div className="flex items-center gap-2.5">
        <div className="rounded-lg bg-gradient-to-br from-violet-500 to-sky-500 p-1.5 shadow-lg shadow-violet-900/40">
          <Network className="h-4 w-4 text-white" />
        </div>
        <div className="leading-tight">
          <h1 className="text-sm font-semibold tracking-tight text-zinc-50">CodeArchitect AI</h1>
          <p className="hidden text-[10px] text-zinc-500 sm:block">Dependency maps · blast radius · time machine</p>
        </div>
      </div>

      <div className="mx-1 hidden h-6 w-px bg-zinc-800 sm:block" />

      <label className="relative flex items-center gap-2 rounded-lg border border-zinc-700 bg-zinc-900/70 py-1 pl-2.5 pr-1 text-xs text-zinc-300">
        <FolderGit2 className="h-3.5 w-3.5 text-zinc-500" />
        <span className="sr-only">Active repository</span>
        <select
          value={graph.id}
          onChange={(e) => props.onSelectRepository(e.target.value)}
          className="max-w-[220px] cursor-pointer appearance-none bg-transparent pr-6 font-medium text-zinc-100 focus:outline-none"
        >
          {samples.map((s) => (
            <option key={s.id} value={s.id} className="bg-zinc-900">
              {s.name}
            </option>
          ))}
          {importedGraph && (
            <option value={importedGraph.id} className="bg-zinc-900">
              {importedGraph.name}
            </option>
          )}
          <option value={CUSTOM_UPLOAD_OPTION} className="bg-zinc-900">
            Custom Upload…
          </option>
        </select>
        <ChevronDown className="pointer-events-none absolute right-2 h-3.5 w-3.5 text-zinc-500" />
      </label>

      <span
        className={clsx(
          "flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-medium ring-1 ring-inset",
          engine?.engine === "ai" ? "bg-violet-500/10 text-violet-300 ring-violet-500/30" : "bg-zinc-800 text-zinc-400 ring-zinc-700",
        )}
        title={
          engine?.engine === "ai"
            ? `AI analysis by ${engine.label}`
            : engine?.error
              ? `AI provider misconfigured: ${engine.error}`
              : "Deterministic local engine — set AI_PROVIDER (e.g. ollama) or a provider API key to enable AI"
        }
      >
        {engine?.engine === "ai" ? <Bot className="h-3 w-3" /> : <Cpu className="h-3 w-3" />}
        <span className="max-w-[180px] truncate">{engine ? (engine.engine === "ai" ? engine.label : "Local engine") : "…"}</span>
      </span>

      <div className="flex items-center gap-2 text-[11px] text-zinc-500" aria-live="polite">
        {props.saveStatus === "saving" && <span className="hidden sm:inline">Saving…</span>}
        {props.saveStatus === "saved" && <span className="hidden sm:inline" title="Your edits are stored in this browser only">Saved in this browser</span>}
        {props.saveStatus === "unavailable" && <span className="text-amber-400/80" title="Browser storage is unavailable, so edits will not survive a reload">Not saving</span>}
        {props.isEdited && (
          <button type="button" onClick={props.onReset} title="Discard your edits and return to the original" className="flex items-center gap-1 rounded-md border border-zinc-700 px-1.5 py-0.5 text-zinc-300 hover:border-zinc-500 hover:text-white">
            <RotateCcw className="h-3 w-3" /> Reset
          </button>
        )}
      </div>

      <div className="ml-auto flex flex-wrap items-center gap-2">
        <NavButton tone="red" tour="simulate" title="Describe a change and see what it would break" active={props.isImpactActive} onClick={props.onSimulate}>
          <Radar className="h-3.5 w-3.5" /> <span className="sm:hidden">Simulate</span>
          <span className="hidden sm:inline">Simulate Blast Radius</span>
        </NavButton>
        <NavButton tone="violet" tour="story" title="Replay how the architecture evolved, commit by commit" active={props.isStoryOn} onClick={props.onToggleStory}>
          <History className="h-3.5 w-3.5" /> <span className="sm:hidden">Story</span>
          <span className="hidden sm:inline">Toggle Time-Machine Story</span>
        </NavButton>
        <ExportMenu busy={props.exporting} onExport={props.onExport} />
        <NavButton tone="zinc" tour="help" title="Show the guided tour (?)" onClick={props.onHelp}>
          <HelpCircle className="h-3.5 w-3.5" />
          <span className="sr-only">Show the guided tour</span>
        </NavButton>
      </div>
    </header>
  );
}

"use client";

import {
  Background,
  BackgroundVariant,
  Controls,
  MiniMap,
  Panel,
  ReactFlow,
  useReactFlow,
  type Connection,
  type EdgeChange,
  type NodeChange,
  type NodeTypes,
} from "@xyflow/react";
import { useCallback, useEffect, useMemo, type ReactNode } from "react";
import { CustomNode, NodeActionsContext, type NodeActions } from "@/components/CustomNode";
import { SearchBox } from "@/components/SearchBox";
import type { ArchitectureGraph, ArchNode, RenderEdge, RenderNode } from "@/lib/types";
import { HEALTH_META, KIND_META, STATUS_META } from "@/lib/ui";

const NODE_TYPES: NodeTypes = { component: CustomNode };

const MINIMAP_STATUS_COLORS: Partial<Record<RenderNode["data"]["status"], string>> = {
  broken: "#ef4444",
  impacted: "#f59e0b",
  modified: "#38bdf8",
  added: "#34d399",
  proposed: "#d946ef",
};

const CENTER_PADDING = 0.8;
const CENTER_MAX_ZOOM = 1.1;
const CENTER_DURATION_MS = 450;

export type CenterRequest = { nodeId: string; nonce: number };

/** Pans and zooms to a component whenever a new request (new nonce) arrives. */
function CenterController({ request }: { request: CenterRequest | null }) {
  const { fitView } = useReactFlow();
  useEffect(() => {
    if (!request) return;
    void fitView({ nodes: [{ id: request.nodeId }], padding: CENTER_PADDING, maxZoom: CENTER_MAX_ZOOM, duration: CENTER_DURATION_MS });
  }, [request, fitView]);
  return null;
}

type Props = {
  graphKey: string;
  kindLabels?: ArchitectureGraph["kindLabels"];
  centerRequest: CenterRequest | null;
  /** Source components the search box looks through. */
  searchNodes: ArchNode[];
  onSearchSelect: (nodeId: string) => void;
  focusEnabled: boolean;
  hasSelection: boolean;
  onToggleFocus: () => void;
  /** Shown under the legends in the top-left column (e.g. the active trace). */
  banner?: ReactNode;
  nodes: RenderNode[];
  edges: RenderEdge[];
  actions: NodeActions;
  onNodesChange: (changes: NodeChange<ArchNode>[]) => void;
  onSelectNode: (nodeId: string | null) => void;
  onConnect: (connection: Connection) => void;
  onRemoveDraftEdge: (edgeId: string) => void;
};

export function ArchitectureCanvas({ graphKey, kindLabels, centerRequest, searchNodes, onSearchSelect, focusEnabled, hasSelection, onToggleFocus, banner, nodes, edges, actions, onNodesChange, onSelectNode, onConnect, onRemoveDraftEdge }: Props) {
  const handleEdgesChange = useCallback(
    (changes: EdgeChange<RenderEdge>[]) => {
      for (const change of changes) if (change.type === "remove") onRemoveDraftEdge(change.id);
    },
    [onRemoveDraftEdge],
  );

  const isValidConnection = useCallback((c: Connection | RenderEdge) => c.source !== c.target, []);

  const legend = useMemo(
    () =>
      (Object.keys(KIND_META) as Array<keyof typeof KIND_META>).map((kind) => (
        <span key={kind} className="flex items-center gap-1.5">
          <span className="h-2 w-2 rounded-sm" style={{ background: KIND_META[kind].hex }} />
          {kindLabels?.[kind] ?? KIND_META[kind].label}
        </span>
      )),
    [kindLabels],
  );

  return (
    <NodeActionsContext.Provider value={actions}>
      <ReactFlow<RenderNode, RenderEdge>
        key={graphKey}
        nodes={nodes}
        edges={edges}
        nodeTypes={NODE_TYPES}
        // RenderNode is ArchNode plus derived fields; position/dimension changes apply to the source nodes.
        onNodesChange={onNodesChange as unknown as (changes: NodeChange<RenderNode>[]) => void}
        onEdgesChange={handleEdgesChange}
        onNodeClick={(_, node) => onSelectNode(node.id)}
        onPaneClick={() => onSelectNode(null)}
        onConnect={onConnect}
        isValidConnection={isValidConnection}
        fitView
        fitViewOptions={{ padding: 0.2 }}
        minZoom={0.2}
        maxZoom={2}
        proOptions={{ hideAttribution: true }}
        colorMode="dark"
      >
        <Background variant={BackgroundVariant.Dots} gap={22} size={1.2} color="#3f3f46" />
        <Controls position="bottom-left" showInteractive={false} />
        <MiniMap
          position="bottom-right"
          pannable
          zoomable
          nodeBorderRadius={6}
          nodeColor={(n) => {
            const data = (n as RenderNode).data;
            return (data.heat ? HEALTH_META[data.heat.level].hex : undefined) ?? MINIMAP_STATUS_COLORS[data.status] ?? KIND_META[data.kind].hex;
          }}
          className="!hidden !rounded-lg !border !border-zinc-800 sm:!block"
        />
        <CenterController request={centerRequest} />
        <Panel position="top-left">
          <div className="flex max-w-[min(100%,38rem)] flex-col gap-1.5">
            <SearchBox nodes={searchNodes} onSelect={onSearchSelect} focusEnabled={focusEnabled} hasSelection={hasSelection} onToggleFocus={onToggleFocus} />
          </div>
          <div data-tour="legend" className="mt-1.5 flex max-w-[min(100%,38rem)] flex-col gap-1.5">
            <div className="flex max-w-full gap-x-3 gap-y-1 overflow-x-auto whitespace-nowrap rounded-lg border border-zinc-800 bg-zinc-950/80 px-3 py-1.5 text-[11px] text-zinc-400 backdrop-blur sm:flex-wrap sm:overflow-visible sm:whitespace-normal" title="Colour = what the component is for">
              {legend}
            </div>
            <div className="hidden flex-wrap gap-x-3 gap-y-1 rounded-lg border border-zinc-800 bg-zinc-950/80 px-3 py-1.5 text-[11px] text-zinc-400 backdrop-blur sm:flex" title="Glow = what a simulated change does to it">
              {(["broken", "impacted", "modified", "proposed"] as const).map((s) => (
                <span key={s} className="flex items-center gap-1.5">
                  <span className={`h-2 w-2 rounded-full ${STATUS_META[s].dot}`} />
                  {STATUS_META[s].label}
                </span>
              ))}
            </div>
            {banner}
          </div>
        </Panel>
      </ReactFlow>
    </NodeActionsContext.Provider>
  );
}

"use client";

import { Handle, Position, type NodeProps } from "@xyflow/react";
import clsx from "clsx";
import { Copy, Database, Eye, Layers, Monitor, Network, Zap } from "lucide-react";
import { createContext, memo, useContext, type ComponentType } from "react";
import type { NodeKind, RenderNode } from "@/lib/types";
import { HEALTH_META, KIND_META, STATUS_META } from "@/lib/ui";

export type NodeActions = {
  inspect: (nodeId: string) => void;
  simulateFrom: (nodeId: string) => void;
  copyPath: (filePath: string) => void;
};

/** Quick actions are injected via context so node data stays serializable. */
export const NodeActionsContext = createContext<NodeActions | null>(null);

const STATUS_HELP: Record<RenderNode["data"]["status"], string> = {
  normal: "No change is being simulated for this component.",
  modified: "This is where the change starts.",
  added: "Introduced by the commit you are viewing.",
  impacted: "Depends on the changed component; review it, it may need a smaller edit.",
  broken: "Will fail or misbehave unless it is edited for this change.",
  proposed: "A draft component from the Builder; it does not exist in the code yet.",
};

const KIND_ICON: Record<NodeKind, ComponentType<{ className?: string }>> = {
  frontend: Monitor,
  api: Network,
  logic: Layers,
  data: Database,
};

function QuickAction({ label, onClick, icon: Icon }: { label: string; onClick: () => void; icon: ComponentType<{ className?: string }> }) {
  return (
    <button
      type="button"
      title={label}
      aria-label={label}
      onClick={(event) => {
        event.stopPropagation();
        onClick();
      }}
      className="nodrag rounded-md p-1 text-zinc-400 transition hover:bg-zinc-700/70 hover:text-zinc-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-violet-400"
    >
      <Icon className="h-3.5 w-3.5" />
    </button>
  );
}

function CustomNodeComponent({ id, data, selected }: NodeProps<RenderNode>) {
  const actions = useContext(NodeActionsContext);
  const kind = KIND_META[data.kind];
  const status = STATUS_META[data.status];
  const Icon = KIND_ICON[data.kind];
  const heat = data.heat ? HEALTH_META[data.heat.level] : null;

  return (
    <div
      className={clsx(
        "group w-[220px] rounded-xl border-2 bg-zinc-900/80 shadow-lg shadow-black/40 backdrop-blur-md transition-[transform,border-color,opacity] duration-150 hover:-translate-y-0.5",
        kind.border,
        status.glow,
        data.status === "proposed" && "border-dashed",
        heat && !selected && heat.ring,
        data.traced && !selected && "ring-2 ring-cyan-400/80",
        data.dimmed && "opacity-25 saturate-50",
        selected && "ring-2 ring-white/70 ring-offset-2 ring-offset-zinc-950",
      )}
    >
      <Handle type="target" position={Position.Top} />

      {data.traceStep ? (
        <span
          className="absolute -left-2 -top-2 z-10 flex h-5 min-w-5 items-center justify-center rounded-full bg-cyan-500 px-1 text-[10px] font-bold text-zinc-950 shadow"
          title={`Step ${data.traceStep} of the trace`}
        >
          {data.traceStep}
        </span>
      ) : null}

      {data.violations ? (
        <span
          className="absolute -right-2 -top-2 z-10 rounded-full bg-orange-600 px-1.5 py-0.5 text-[10px] font-bold text-white shadow"
          title={`${data.violations} architecture rule violation${data.violations === 1 ? "" : "s"} involve this component`}
        >
          ✕ {data.violations}
        </span>
      ) : null}

      <div className="flex items-start gap-2 px-3 pt-2.5">
        <div className={clsx("mt-0.5 rounded-md bg-zinc-800/80 p-1.5", kind.text)}>
          <Icon className="h-4 w-4" />
        </div>
        <div className="min-w-0 flex-1">
          <div className="truncate text-[13px] font-semibold leading-tight text-zinc-50" title={data.label}>
            {data.label}
          </div>
          <div className="truncate font-mono text-[10px] text-zinc-500" title={data.filePath}>
            {data.filePath}
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between gap-2 px-3 pb-2 pt-2">
        <span className={clsx("truncate rounded px-1.5 py-0.5 text-[10px] font-medium ring-1 ring-inset", kind.chip)} title={kind.label}>
          {data.kindLabel}
        </span>
        {heat && data.heat ? (
          <span
            className={clsx("shrink-0 rounded px-1.5 py-0.5 text-[10px] font-semibold ring-1 ring-inset", heat.chip)}
            title={`Change-risk ${data.heat.score}/100 (${heat.label}). Higher means more things depend on it or it is structurally tangled.`}
          >
            Risk {data.heat.score}
          </span>
        ) : (
          <span className={clsx("flex shrink-0 items-center gap-1 text-[10px] font-medium", status.text)} title={STATUS_HELP[data.status]}>
            <span className={clsx("h-1.5 w-1.5 rounded-full", status.dot, data.status !== "normal" && "animate-pulse")} />
            {status.label}
            {data.impactDepth !== undefined && data.impactDepth > 0 && <span className="text-zinc-500">· {data.impactDepth} hop</span>}
          </span>
        )}
      </div>

      {actions && (
        <div className="flex items-center justify-end gap-0.5 border-t border-zinc-800/80 px-2 py-1 opacity-60 transition group-hover:opacity-100">
          <QuickAction label="Inspect code" icon={Eye} onClick={() => actions.inspect(id)} />
          <QuickAction label="Simulate change from here" icon={Zap} onClick={() => actions.simulateFrom(id)} />
          <QuickAction label="Copy file path" icon={Copy} onClick={() => actions.copyPath(data.filePath)} />
        </div>
      )}

      <Handle type="source" position={Position.Bottom} />
    </div>
  );
}

export const CustomNode = memo(CustomNodeComponent);

"use client";

import clsx from "clsx";
import { Activity, Compass, FileSearch, History, Radar, Wand2, type LucideIcon } from "lucide-react";
import type { Dispatch } from "react";
import { BlastRadiusPanel } from "@/components/inspector/BlastRadiusPanel";
import { BuilderPanel } from "@/components/inspector/BuilderPanel";
import { GuidePanel } from "@/components/inspector/GuidePanel";
import { HealthPanel } from "@/components/inspector/HealthPanel";
import { NodeInspector } from "@/components/inspector/NodeInspector";
import { StoryPanel } from "@/components/inspector/StoryPanel";
import type { InspectorTab, WorkspaceAction, WorkspaceState } from "@/hooks/useWorkspace";
import type { HealthReport } from "@/lib/engines/health";
import type { Trace, TraceRequest } from "@/lib/engines/provenance";
import type { NodeKind, RuleViolation } from "@/lib/types";

const TABS: Array<{ id: InspectorTab; label: string; hint: string; icon: LucideIcon }> = [
  { id: "guide", label: "Guide", hint: "New here? A reading order for this codebase", icon: Compass },
  { id: "inspector", label: "Inspector", hint: "Code and details of the selected component", icon: FileSearch },
  { id: "blast", label: "Blast Radius", hint: "Simulate a change and see what it breaks", icon: Radar },
  { id: "health", label: "Health", hint: "Find fragile, tangled or oversized parts", icon: Activity },
  { id: "story", label: "Story", hint: "Replay how the architecture evolved", icon: History },
  { id: "builder", label: "Builder", hint: "Draw new components and generate the code", icon: Wand2 },
];

type Props = {
  state: WorkspaceState;
  dispatch: Dispatch<WorkspaceAction>;
  samplePrompts: string[];
  healthReport: HealthReport;
  violations: RuleViolation[];
  trace: Trace | null;
  onTrace: (request: TraceRequest | null) => void;
  /** Select a component and pan/zoom the canvas to it. */
  onSelectAndCenter: (nodeId: string) => void;
  onRunImpact: () => void;
  onSimulate: (nodeId: string, symbol?: string) => void;
  onNarrate: () => void;
  onImportGitLog: (text: string) => void;
  onAddComponent: (input: { label: string; kind: NodeKind; filePath: string; description: string }) => void;
  onGenerateScaffold: () => void;
};

export function InspectorPanel({ state, dispatch, samplePrompts, healthReport, violations, trace, onTrace, onSelectAndCenter, ...handlers }: Props) {
  const { graph, activeTab, selectedNodeId } = state;
  const selectedNode = graph.nodes.find((n) => n.id === selectedNodeId);

  return (
    <aside data-tour="inspector" className="flex h-full min-h-0 flex-col border-l border-zinc-800/80 bg-zinc-950/60 backdrop-blur-xl">
      {/* Container query: on a narrow drawer only the active tab shows its name; the rest keep their icon + tooltip. */}
      <div role="tablist" aria-label="Inspector modes" className="@container flex shrink-0 gap-1 border-b border-zinc-800/80 p-1.5">
        {TABS.map(({ id, label, hint, icon: Icon }) => (
          <button
            key={id}
            role="tab"
            type="button"
            id={`tab-${id}`}
            data-tour={`tab-${id}`}
            title={`${label}: ${hint}`}
            aria-label={label}
            aria-selected={activeTab === id}
            aria-controls={`panel-${id}`}
            onClick={() => dispatch({ type: "setTab", tab: id })}
            className={clsx(
              "flex items-center justify-center gap-1.5 rounded-md px-2 py-1.5 text-xs font-medium transition",
              activeTab === id ? "flex-[2] bg-zinc-800 text-zinc-50 shadow-inner" : "flex-1 text-zinc-500 hover:bg-zinc-900 hover:text-zinc-200",
            )}
          >
            <Icon className="h-3.5 w-3.5 shrink-0" />
            <span className={clsx("truncate", activeTab === id ? "inline" : "hidden @[34rem]:inline")}>{label}</span>
            {id === "blast" && state.impact.result && <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-red-500" />}
            {id === "health" && violations.some((v) => v.severity === "error") && <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-orange-500" />}
            {id === "builder" && graph.nodes.some((n) => n.data.isDraft) && <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-fuchsia-500" />}
          </button>
        ))}
      </div>

      <div role="tabpanel" id={`panel-${activeTab}`} aria-labelledby={`tab-${activeTab}`} className="scrollbar-thin min-h-0 flex-1 overflow-y-auto p-4">
        {activeTab === "guide" && <GuidePanel graph={graph} selectedNodeId={selectedNodeId} onSelectAndCenter={onSelectAndCenter} />}
        {activeTab === "inspector" && (
          <NodeInspector
            graph={graph}
            node={selectedNode}
            health={selectedNode ? healthReport.nodes[selectedNode.id] : undefined}
            trace={trace}
            onTrace={(mode) => onTrace(mode && selectedNode ? { nodeId: selectedNode.id, mode } : null)}
            onSelectNode={onSelectAndCenter}
            onSimulate={handlers.onSimulate}
          />
        )}
        {activeTab === "blast" && (
          <BlastRadiusPanel
            graph={graph}
            selectedNodeId={selectedNodeId}
            prompt={state.impactPrompt}
            samplePrompts={samplePrompts}
            status={state.impact.status}
            error={state.impact.error}
            result={state.impact.result}
            onPromptChange={(prompt) => dispatch({ type: "setImpactPrompt", prompt })}
            onRun={handlers.onRunImpact}
            onClear={() => dispatch({ type: "clearImpact" })}
            onApply={() => dispatch({ type: "applyImpact" })}
            onSelectNode={onSelectAndCenter}
          />
        )}
        {activeTab === "health" && (
          <HealthPanel
            graph={graph}
            report={healthReport}
            selectedNodeId={selectedNodeId}
            onSelectNode={onSelectAndCenter}
            rules={graph.rules}
            violations={violations}
            onSetRules={(rules) => dispatch({ type: "setRules", rules })}
          />
        )}
        {activeTab === "story" && (
          <StoryPanel
            graph={graph}
            enabled={state.story.enabled}
            index={state.story.index}
            isPlaying={state.story.isPlaying}
            narrative={state.story.narrative}
            narrationStatus={state.story.status}
            onToggle={() => dispatch({ type: "toggleStory" })}
            onIndexChange={(index) => dispatch({ type: "setStoryIndex", index })}
            onPlayingChange={(isPlaying) => dispatch({ type: "setStoryPlaying", isPlaying })}
            onNarrate={handlers.onNarrate}
            onImportGitLog={handlers.onImportGitLog}
          />
        )}
        {activeTab === "builder" && (
          <BuilderPanel
            graph={graph}
            status={state.scaffold.status}
            error={state.scaffold.error}
            result={state.scaffold.result}
            onAddComponent={handlers.onAddComponent}
            onRemoveDraft={(nodeId) => dispatch({ type: "removeDraftNode", nodeId })}
            onRemoveEdge={(edgeId) => dispatch({ type: "removeDraftEdge", edgeId })}
            onGenerate={handlers.onGenerateScaffold}
            onApply={() => dispatch({ type: "applyScaffold" })}
          />
        )}
      </div>
    </aside>
  );
}

"use client";

import clsx from "clsx";
import { ArrowDownRight, ArrowUpRight, MousePointerClick, Zap } from "lucide-react";
import { Glossary } from "@/components/Glossary";
import { CodeBlock } from "@/components/inspector/CodeBlock";
import { ExportList } from "@/components/inspector/ExportList";
import { describeTrace, type Trace, type TraceMode, type TraceRole } from "@/lib/engines/provenance";
import { explainNode } from "@/lib/explain";
import type { NodeHealth } from "@/lib/engines/health";
import type { ArchitectureGraph, ArchNode } from "@/lib/types";
import { HEALTH_META, KIND_META, kindLabelFor } from "@/lib/ui";

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section className="space-y-1.5">
      <h3 className="text-[11px] font-semibold uppercase tracking-wider text-zinc-500">{title}</h3>
      {children}
    </section>
  );
}

function Chips({ items, empty }: { items: string[]; empty: string }) {
  if (items.length === 0) return <p className="text-xs text-zinc-600">{empty}</p>;
  return (
    <div className="flex flex-wrap gap-1.5">
      {items.map((item) => (
        <code key={item} className="rounded bg-zinc-800/80 px-1.5 py-0.5 font-mono text-[11px] text-zinc-300">
          {item}
        </code>
      ))}
    </div>
  );
}

const ROLE_LABEL: Record<TraceRole, string> = { input: "input file", produced: "intermediate", code: "code", target: "this component" };

/** Follow data flow: where this comes from, or what it affects, highlighted on the map. */
function TraceSection({ graph, nodeLabel, nodeId, trace, onTrace, onSelectNode }: { graph: ArchitectureGraph; nodeLabel: string; nodeId: string; trace: Trace | null; onTrace: (mode: TraceMode | null) => void; onSelectNode: (id: string) => void }) {
  const here = trace && trace.nodeId === nodeId ? trace : null;
  const elsewhere = trace && trace.nodeId !== nodeId ? trace : null;
  const description = here ? describeTrace(graph, here) : null;
  const label = (id: string) => graph.nodes.find((n) => n.id === id)?.data.label ?? id;

  const button = (mode: TraceMode, text: string, hint: string) => (
    <button
      type="button"
      aria-pressed={here?.mode === mode}
      title={hint}
      onClick={() => onTrace(here?.mode === mode ? null : mode)}
      className={clsx(
        "flex-1 rounded-md border px-2 py-1.5 text-xs font-medium transition",
        here?.mode === mode ? "border-cyan-400/70 bg-cyan-500/20 text-cyan-100" : "border-zinc-700 text-zinc-300 hover:border-cyan-500/50 hover:text-cyan-100",
      )}
    >
      {text}
    </button>
  );

  return (
    <section aria-label="Trace" className="space-y-2 rounded-lg border border-cyan-500/20 bg-cyan-500/5 p-3">
      <h3 className="text-[11px] font-semibold uppercase tracking-wider text-cyan-300">Trace the data flow</h3>
      <div className="flex gap-2">
        {button("upstream", "Where it comes from", "Highlight the code and input files that produced this")}
        {button("downstream", "What it affects", "Highlight everything that uses this, and the results that would be out of date")}
      </div>

      {elsewhere && (
        <p className="text-[11px] text-zinc-400">
          The map is tracing <b className="text-zinc-200">{label(elsewhere.nodeId)}</b>.{" "}
          <button type="button" onClick={() => onTrace(null)} className="text-cyan-300 underline-offset-2 hover:underline">
            Clear trace (Esc)
          </button>
        </p>
      )}

      {here && description && (
        <div className="space-y-2">
          <p className="text-sm font-medium text-zinc-100">{description.headline}</p>
          <ul className="list-disc space-y-1 pl-4 text-xs leading-relaxed text-zinc-300">
            {description.lines.map((line) => (
              <li key={line}>{line}</li>
            ))}
          </ul>
          <ol className="divide-y divide-zinc-800/80 rounded-lg border border-zinc-800">
            {here.steps.map((step, i) => (
              <li key={step.nodeId}>
                <button type="button" onClick={() => onSelectNode(step.nodeId)} className="flex w-full items-center gap-2 px-2.5 py-1.5 text-left transition hover:bg-zinc-800/40">
                  <span className="flex h-4 w-4 shrink-0 items-center justify-center rounded-full bg-cyan-500 text-[10px] font-bold text-zinc-950">{i + 1}</span>
                  <span className="min-w-0 flex-1 truncate text-xs text-zinc-200">{label(step.nodeId)}</span>
                  <span className="shrink-0 rounded bg-zinc-800 px-1.5 py-0.5 text-[10px] text-zinc-400">{ROLE_LABEL[step.role]}</span>
                </button>
              </li>
            ))}
          </ol>
          <button type="button" onClick={() => onTrace(null)} className="text-[11px] text-cyan-300 underline-offset-2 hover:underline">
            Clear trace (Esc)
          </button>
        </div>
      )}
      {!here && !elsewhere && <p className="text-[11px] leading-relaxed text-zinc-500">Pick a direction to highlight how {nodeLabel} fits into the pipeline, step by step.</p>}
    </section>
  );
}

type Props = {
  graph: ArchitectureGraph;
  node: ArchNode | undefined;
  health?: NodeHealth;
  /** The active provenance trace (for any component), and a way to start or clear one for this component. */
  trace: Trace | null;
  onTrace: (mode: TraceMode | null) => void;
  onSelectNode: (id: string) => void;
  onSimulate: (id: string, symbol?: string) => void;
};

export function NodeInspector({ graph, node, health, trace, onTrace, onSelectNode, onSimulate }: Props) {
  if (!node) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-3 px-6 text-center text-zinc-500">
        <MousePointerClick className="h-8 w-8 text-zinc-600" />
        <p className="text-sm">Select a component on the canvas to inspect its code, exports and dependencies.</p>
        <p className="text-xs text-zinc-600">Tip: drag from a node's bottom handle to another node to draft a new dependency.</p>
        <Glossary className="mt-3 w-full text-left" />
      </div>
    );
  }

  const { data } = node;
  const plain = explainNode(graph, node.id);
  // Per-export usage needs at least one importer whose symbols were read (TypeScript/JavaScript).
  const hasSymbolData = graph.edges.some((e) => e.target === node.id && e.symbols !== undefined);
  const label = (id: string) => graph.nodes.find((n) => n.id === id)?.data.label ?? id;
  const dependsOn = graph.edges.filter((e) => e.source === node.id);
  const usedBy = graph.edges.filter((e) => e.target === node.id);

  return (
    <div className="space-y-5">
      <header className="space-y-2">
        <div className="flex items-start justify-between gap-3">
          <div className="min-w-0">
            <h2 className="truncate text-base font-semibold text-zinc-50">{data.label}</h2>
            <p className="truncate font-mono text-[11px] text-zinc-500">{data.filePath}</p>
          </div>
          <span className={clsx("shrink-0 rounded px-1.5 py-0.5 text-[10px] font-medium ring-1 ring-inset", KIND_META[data.kind].chip)}>
            {kindLabelFor(graph, data.kind)}
          </span>
        </div>
        <p className="text-sm leading-relaxed text-zinc-400">{data.description}</p>
        {health && (
          <p className="flex flex-wrap items-center gap-x-2 gap-y-1 text-xs text-zinc-400">
            <span className={clsx("rounded px-1.5 py-0.5 text-[10px] font-semibold ring-1 ring-inset", HEALTH_META[health.level].chip)} title="How costly and fragile this is to change (0-100). See the Health tab.">
              Change-risk {health.score}
            </span>
            {health.reasons.length > 0 ? health.reasons.join(" · ") : "Few connections, low risk."}
          </p>
        )}
        <button
          type="button"
          onClick={() => onSimulate(node.id)}
          className="flex items-center gap-1.5 rounded-md border border-red-500/30 bg-red-500/10 px-2.5 py-1 text-xs font-medium text-red-300 transition hover:bg-red-500/20"
        >
          <Zap className="h-3.5 w-3.5" /> Simulate a change here
        </button>
      </header>

      {plain && (
        <section aria-label="In plain words" className="space-y-1.5 rounded-lg border border-sky-500/20 bg-sky-500/5 p-3">
          <h3 className="text-[11px] font-semibold uppercase tracking-wider text-sky-300">In plain words</h3>
          <p className="text-sm font-medium text-zinc-100">{plain.headline}</p>
          <ul className="list-disc space-y-1 pl-4 text-xs leading-relaxed text-zinc-300">
            {plain.bullets.map((b) => (
              <li key={b}>{b}</li>
            ))}
          </ul>
        </section>
      )}

      <TraceSection graph={graph} nodeLabel={data.label} nodeId={node.id} trace={trace} onTrace={onTrace} onSelectNode={onSelectNode} />

      <Section title="Source">
        <CodeBlock code={data.code} title={`${data.filePath} · ${data.language}`} />
      </Section>

      <Section title="Exports">
        {data.exports.length > 0 && hasSymbolData ? (
          <ExportList graph={graph} nodeId={node.id} onSelectNode={onSelectNode} onSimulateSymbol={(symbol) => onSimulate(node.id, symbol)} />
        ) : (
          <Chips items={data.exports} empty="None detected" />
        )}
      </Section>
      <Section title="Imports">
        <Chips items={data.imports} empty="None detected" />
      </Section>

      <Section title="Parameters">
        {data.params.length === 0 ? (
          <p className="text-xs text-zinc-600">None</p>
        ) : (
          <table className="w-full text-left text-xs">
            <tbody>
              {data.params.map((p) => (
                <tr key={p.name} className="border-b border-zinc-800/70 last:border-0">
                  <td className="py-1 pr-2 font-mono text-zinc-200">{p.name}</td>
                  <td className="py-1 pr-2 font-mono text-violet-300">{p.type}</td>
                  <td className="py-1 text-zinc-500">{p.description}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </Section>

      <Section title="Dependencies">
        <ul className="space-y-1 text-xs">
          {dependsOn.map((e) => (
            <li key={e.id}>
              <button type="button" onClick={() => onSelectNode(e.target)} className="flex items-center gap-1.5 text-zinc-300 hover:text-white">
                <ArrowDownRight className="h-3.5 w-3.5 text-zinc-500" />
                {e.relation} <span className="font-medium">{label(e.target)}</span>
                {e.label && <span className="font-mono text-zinc-500">· {e.label}</span>}
              </button>
            </li>
          ))}
          {usedBy.map((e) => (
            <li key={e.id}>
              <button type="button" onClick={() => onSelectNode(e.source)} className="flex items-center gap-1.5 text-zinc-300 hover:text-white">
                <ArrowUpRight className="h-3.5 w-3.5 text-zinc-500" />
                used by <span className="font-medium">{label(e.source)}</span>
              </button>
            </li>
          ))}
          {dependsOn.length + usedBy.length === 0 && <li className="text-zinc-600">Isolated component</li>}
        </ul>
      </Section>
    </div>
  );
}

"use client";

import clsx from "clsx";
import { Bot, CheckCheck, Cpu, Loader2, Radar, X } from "lucide-react";
import { Glossary } from "@/components/Glossary";
