  onApply: () => void;
};

const KINDS = Object.keys(KIND_META) as NodeKind[];

export function BuilderPanel({ graph, status, error, result, ...actions }: Props) {
  const [label, setLabel] = useState("");
  const [kind, setKind] = useState<NodeKind>("frontend");
  const [description, setDescription] = useState("");
  const [customPath, setCustomPath] = useState<string | null>(null);

  const filePath = customPath ?? (label.trim() ? suggestFilePath(label, kind) : "");
  const drafts = graph.nodes.filter((n) => n.data.isDraft);
  const draftEdges = graph.edges.filter((e) => e.isDraft);
  const name = (id: string) => graph.nodes.find((n) => n.id === id)?.data.label ?? id;
  const hasWork = drafts.length > 0 || draftEdges.length > 0;

  return (
    <div className="space-y-5">
      <form
        className="space-y-2 rounded-lg border border-zinc-800 bg-zinc-900/50 p-3"
        onSubmit={(e) => {
          e.preventDefault();
          if (!label.trim()) return;
          actions.onAddComponent({ label: label.trim(), kind, filePath, description: description.trim() || `New ${KIND_META[kind].label.toLowerCase()} component.` });
          setLabel("");
          setDescription("");
          setCustomPath(null);
        }}
      >
        <h3 className="text-[11px] font-semibold uppercase tracking-wider text-zinc-500">Add component</h3>
        <div className="grid grid-cols-4 gap-1">
          {KINDS.map((k) => (
            <button
              key={k}
              type="button"
              onClick={() => setKind(k)}
              aria-pressed={kind === k}
              className={clsx("rounded-md border px-1.5 py-1 text-[10px] font-medium transition", kind === k ? `${KIND_META[k].border} ${KIND_META[k].text} bg-zinc-800` : "border-zinc-800 text-zinc-500 hover:text-zinc-300")}
            >
              {KIND_META[k].label}
            </button>
          ))}
        </div>
        <input
          value={label}
          onChange={(e) => setLabel(e.target.value)}
          placeholder='Name, e.g. "Export PDF Button"'
          maxLength={80}
          className="w-full rounded-md border border-zinc-700 bg-zinc-950 px-2.5 py-1.5 text-sm text-zinc-100 placeholder:text-zinc-600 focus:border-violet-500 focus:outline-none"
        />
        <input
          value={filePath}
          onChange={(e) => setCustomPath(e.target.value)}
          placeholder="File path"
          className="w-full rounded-md border border-zinc-800 bg-zinc-950 px-2.5 py-1 font-mono text-[11px] text-zinc-400 placeholder:text-zinc-700 focus:border-violet-500 focus:outline-none"
        />
        <input
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          placeholder="What should it do? (helps the AI model)"
          maxLength={300}
          className="w-full rounded-md border border-zinc-800 bg-zinc-950 px-2.5 py-1 text-xs text-zinc-300 placeholder:text-zinc-700 focus:border-violet-500 focus:outline-none"
        />
        <button type="submit" disabled={!label.trim()} className="flex items-center gap-1.5 rounded-md bg-zinc-100 px-2.5 py-1 text-xs font-medium text-zinc-900 hover:bg-white disabled:opacity-40">
          <Plus className="h-3.5 w-3.5" /> Add to canvas
        </button>
        <p className="text-[11px] text-zinc-500">Then drag from a node&apos;s bottom handle to another node&apos;s top handle: the source will depend on the target.</p>
      </form>

      <section className="space-y-1.5">
        <h3 className="text-[11px] font-semibold uppercase tracking-wider text-zinc-500">Draft changes</h3>
        {!hasWork && <p className="text-xs text-zinc-600">Nothing drafted yet.</p>}
        <ul className="space-y-1">
          {drafts.map((n) => (
            <li key={n.id} className="flex items-center justify-between rounded-md border border-dashed border-fuchsia-500/40 bg-fuchsia-500/5 px-2.5 py-1.5 text-xs">
              <span className="flex items-center gap-1.5 text-fuchsia-200">
                <FilePlus2 className="h-3.5 w-3.5" /> {n.data.label}
                <span className="font-mono text-[10px] text-zinc-500">{n.data.filePath}</span>
              </span>
              <button type="button" aria-label={`Remove ${n.data.label}`} onClick={() => actions.onRemoveDraft(n.id)} className="text-zinc-500 hover:text-red-400">
                <Trash2 className="h-3.5 w-3.5" />
              </button>
            </li>
          ))}
          {draftEdges.map((e) => (
            <li key={e.id} className="flex items-center justify-between rounded-md border border-zinc-800 px-2.5 py-1.5 text-xs text-zinc-300">
              <span>
                {name(e.source)} <span className="text-fuchsia-400">→</span> {name(e.target)}
              </span>
              <button type="button" aria-label="Remove connection" onClick={() => actions.onRemoveEdge(e.id)} className="text-zinc-500 hover:text-red-400">
                <Trash2 className="h-3.5 w-3.5" />
              </button>
            </li>
          ))}
        </ul>
        <button
          type="button"
          onClick={actions.onGenerate}
          disabled={!hasWork || status === "running"}
          className="mt-2 flex w-full items-center justify-center gap-1.5 rounded-lg bg-fuchsia-600 px-3 py-1.5 text-sm font-medium text-white shadow-lg shadow-fuchsia-900/30 hover:bg-fuchsia-500 disabled:opacity-40"
        >
          {status === "running" ? <Loader2 className="h-4 w-4 animate-spin" /> : <Wand2 className="h-4 w-4" />}
          {status === "running" ? "Generating…" : "Generate glue code"}
        </button>
        {status === "error" && error && <p className="text-xs text-red-300">{error}</p>}
      </section>

      {result && (
        <section className="space-y-3">
          <div className="flex items-center justify-between">
            <p className="text-xs text-zinc-400">
              {result.summary} <span className="text-zinc-600">({result.engine === "ai" ? result.engineLabel ?? "AI" : "templates"})</span>
            </p>
            <button type="button" onClick={actions.onApply} className="flex shrink-0 items-center gap-1 rounded-md bg-emerald-600/90 px-2 py-1 text-[11px] font-medium text-white hover:bg-emerald-500">
              <CheckCheck className="h-3.5 w-3.5" /> Apply
            </button>
          </div>
          {result.files.map((f) => (
            <CodeBlock key={f.path} code={f.content} title={`new · ${f.path}`} />
          ))}
          {result.diffs.length > 0 && <DiffViewer items={result.diffs} />}
        </section>
      )}
    </div>
  );
}

"use client";

import clsx from "clsx";
import { ChevronDown, FileCode2 } from "lucide-react";
import { Fragment, useMemo, useState } from "react";
import { highlightLine, CopyButton } from "@/components/inspector/CodeBlock";
import { diffLines, type DiffLine, type DiffRow } from "@/lib/diff";
import type { DiffItem } from "@/lib/types";

const CELL_TONE: Record<DiffRow["type"], { left: string; right: string }> = {
  same: { left: "", right: "" },
  removed: { left: "bg-red-500/15", right: "bg-zinc-900/60" },
  added: { left: "bg-zinc-900/60", right: "bg-emerald-500/15" },
  changed: { left: "bg-red-500/15", right: "bg-emerald-500/15" },
};

function Cell({ line, tone, sign }: { line?: DiffLine; tone: string; sign: string }) {
  return (
    <div className={clsx("grid h-full grid-cols-[2rem_0.75rem_minmax(0,1fr)]", tone)}>
      <span className="select-none pr-1 text-right text-zinc-600">{line?.lineNo ?? ""}</span>
      <span className="select-none text-zinc-500">{line && tone ? sign : ""}</span>
      <span className="min-w-0 whitespace-pre-wrap break-all pr-2 text-zinc-200">{line ? highlightLine(line.text) : ""}</span>
    </div>
  );
}

function DiffCard({ item, defaultOpen }: { item: DiffItem; defaultOpen: boolean }) {
  const [open, setOpen] = useState(defaultOpen);
  const { rows, stats } = useMemo(() => diffLines(item.before, item.after), [item.before, item.after]);

  return (
    <div className="overflow-hidden rounded-lg border border-zinc-800 bg-zinc-950/70">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
        className="flex w-full items-center gap-2 bg-zinc-900/70 px-3 py-2 text-left transition hover:bg-zinc-800/70"
      >
        <ChevronDown className={clsx("h-3.5 w-3.5 shrink-0 text-zinc-500 transition", !open && "-rotate-90")} />
        <FileCode2 className="h-3.5 w-3.5 shrink-0 text-zinc-400" />
        <span className="min-w-0 flex-1 truncate font-mono text-[11px] text-zinc-200">{item.filePath}</span>
        <span className="font-mono text-[11px] text-emerald-400">+{stats.added}</span>
        <span className="font-mono text-[11px] text-red-400">−{stats.removed}</span>
      </button>
      {open && (
        <>
          <div className="flex items-start justify-between gap-2 border-y border-zinc-800 px-3 py-1.5 text-[11px] text-zinc-400">
            <span>{item.rationale}</span>
            <CopyButton text={item.after} label="Copy new" />
          </div>
          <div className="grid grid-cols-2 border-b border-zinc-800 bg-zinc-900/40 text-[10px] uppercase tracking-wider text-zinc-500">
            <span className="px-3 py-1">Before</span>
            <span className="border-l border-zinc-800 px-3 py-1">After</span>
          </div>
          {/* One grid for all rows: equal halves, long lines wrap so Before and After stay visible and row-aligned. */}
          <div className="scrollbar-thin max-h-[360px] overflow-auto font-mono text-[11px] leading-5">
            <div className="grid grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
              {rows.map((row, i) => (
                <Fragment key={i}>
                  <Cell line={row.left} tone={CELL_TONE[row.type].left} sign="−" />
                  <div className="border-l border-zinc-800">
                    <Cell line={row.right} tone={CELL_TONE[row.type].right} sign="+" />
                  </div>
                </Fragment>
              ))}
            </div>
          </div>
        </>
      )}
    </div>
  );
}

export function DiffViewer({ items }: { items: DiffItem[] }) {
  if (items.length === 0) return <p className="text-xs text-zinc-500">No file changes proposed.</p>;
  return (
    <div className="space-y-2">
      {items.map((item, i) => (
        <DiffCard key={`${item.nodeId}-${item.filePath}`} item={item} defaultOpen={i === 0} />
      ))}
    </div>
  );
}

"use client";

import { Check, Copy } from "lucide-react";
import { Fragment, useState, type ReactNode } from "react";

const TOKEN =
  /(\/\/.*$|#.*$)|("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|`(?:[^`\\]|\\.)*`)|\b(import|from|export|default|const|let|var|async|await|function|return|if|else|type|new|throw|for|of|in|class|interface|extends|try|catch|finally|def|self|None|True|False|null|undefined|true|false)\b|\b(\d+(?:\.\d+)?)\b/g;

/** Lightweight lexical highlighting: comments, strings, keywords, numbers. Rendered as React nodes (no innerHTML). */
export function highlightLine(line: string): ReactNode[] {
  const out: ReactNode[] = [];
  let last = 0;
  for (const match of line.matchAll(TOKEN)) {
    const index = match.index ?? 0;
    if (index > last) out.push(line.slice(last, index));
    const [text, comment, string, keyword] = match;
    const className = comment ? "text-zinc-500 italic" : string ? "text-emerald-300" : keyword ? "text-violet-300" : "text-amber-300";
    out.push(
      <span key={index} className={className}>
        {text}
      </span>,
    );
    last = index + text.length;
  }
  if (last < line.length) out.push(line.slice(last));
  return out;
}

export function CopyButton({ text, label = "Copy" }: { text: string; label?: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      type="button"
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(text);
          setCopied(true);
          setTimeout(() => setCopied(false), 1500);
        } catch {
          setCopied(false);
        }
      }}
      className="flex items-center gap-1 rounded-md px-2 py-1 text-[11px] text-zinc-400 transition hover:bg-zinc-800 hover:text-zinc-100"
    >
      {copied ? <Check className="h-3 w-3 text-emerald-400" /> : <Copy className="h-3 w-3" />}
      {copied ? "Copied" : label}
    </button>
  );
}

export function CodeBlock({ code, title }: { code: string; title?: string }) {
  const lines = code.split("\n");
  return (
    <div className="overflow-hidden rounded-lg border border-zinc-800 bg-zinc-950/80">
      <div className="flex items-center justify-between border-b border-zinc-800 bg-zinc-900/60 px-3 py-1.5">
        <span className="truncate font-mono text-[11px] text-zinc-400">{title}</span>
        <CopyButton text={code} />
      </div>
      <pre className="scrollbar-thin max-h-[420px] overflow-auto py-2 font-mono text-[12px] leading-5">
        <code className="grid grid-cols-[auto_1fr]">
          {lines.map((line, i) => (
            <Fragment key={i}>
              <span className="select-none pl-3 pr-3 text-right text-zinc-600">{i + 1}</span>
              <span className="whitespace-pre pr-4 text-zinc-200">{highlightLine(line)}</span>
            </Fragment>
          ))}
        </code>
      </pre>
    </div>
  );
}

"use client";

import clsx from "clsx";
import { FileArchive, GitBranch, Loader2, X } from "lucide-react";
import { useEffect, useRef, useState } from "react";

type Props = {
  open: boolean;
  isBusy: boolean;
  error: string | null;
  onClose: () => void;
  onUploadFile: (file: File) => void;
  onGithubUrl: (url: string) => void;
};

export function ImportDialog({ open, isBusy, error, onClose, onUploadFile, onGithubUrl }: Props) {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const [url, setUrl] = useState("");
  const [isDragging, setIsDragging] = useState(false);

  useEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog) return;
    if (open && !dialog.open) dialog.showModal();
    if (!open && dialog.open) dialog.close();
  }, [open]);

  return (
    <dialog
      ref={dialogRef}
      onCancel={(e) => {
        e.preventDefault();
        if (!isBusy) onClose();
      }}
      className="m-auto w-[min(520px,calc(100vw-2rem))] rounded-2xl border border-zinc-800 bg-zinc-950/95 p-0 text-zinc-100 shadow-2xl shadow-black/60 backdrop:bg-black/60 backdrop:backdrop-blur-sm"
    >
      <div className="flex items-center justify-between border-b border-zinc-800 px-5 py-3">
        <h2 className="text-sm font-semibold">Map a codebase</h2>
        <button type="button" aria-label="Close" disabled={isBusy} onClick={onClose} className="rounded-md p-1 text-zinc-500 hover:bg-zinc-800 hover:text-zinc-100">
          <X className="h-4 w-4" />
        </button>
      </div>

      <div className="space-y-4 p-5">
        <label
          onDragOver={(e) => {
            e.preventDefault();
            setIsDragging(true);
          }}
          onDragLeave={() => setIsDragging(false)}
          onDrop={(e) => {
            e.preventDefault();
            setIsDragging(false);
            const file = e.dataTransfer.files[0];
            if (file && !isBusy) onUploadFile(file);
          }}
          className={clsx(
            "flex cursor-pointer flex-col items-center gap-2 rounded-xl border-2 border-dashed px-4 py-8 text-center transition",
            isDragging ? "border-violet-500 bg-violet-500/10" : "border-zinc-700 hover:border-zinc-500",
            isBusy && "pointer-events-none opacity-50",
          )}
        >
          <FileArchive className="h-8 w-8 text-zinc-500" />
          <span className="text-sm text-zinc-300">Drop a repository .zip or a CodeArchitect .json export</span>
          <span className="text-[11px] text-zinc-500">Parsed in your browser · up to 50 MB · node_modules/build output ignored</span>
          <input
            type="file"
            accept=".zip,.json"
            className="sr-only"
            disabled={isBusy}
            onChange={(e) => {
              const file = e.target.files?.[0];
              if (file) onUploadFile(file);
              e.target.value = "";
            }}
          />
        </label>

        <div className="flex items-center gap-3 text-[11px] uppercase tracking-wider text-zinc-600">
          <span className="h-px flex-1 bg-zinc-800" /> or <span className="h-px flex-1 bg-zinc-800" />
        </div>

        <form
          className="flex gap-2"
          onSubmit={(e) => {
            e.preventDefault();
            if (url.trim() && !isBusy) onGithubUrl(url.trim());
          }}
        >
          <div className="flex flex-1 items-center gap-2 rounded-lg border border-zinc-700 bg-zinc-900 px-2.5 focus-within:border-violet-500">
            <GitBranch className="h-4 w-4 shrink-0 text-zinc-500" />
            <input
              type="url"
              value={url}
              onChange={(e) => setUrl(e.target.value)}
              placeholder="https://github.com/owner/repo"
              disabled={isBusy}
              className="w-full bg-transparent py-1.5 text-sm text-zinc-100 placeholder:text-zinc-600 focus:outline-none"
            />
          </div>
          <button type="submit" disabled={isBusy || !url.trim()} className="rounded-lg bg-violet-600 px-3 text-sm font-medium text-white hover:bg-violet-500 disabled:opacity-50">
            Analyze
          </button>
        </form>

        {isBusy && (
          <p className="flex items-center gap-2 text-xs text-zinc-400">
            <Loader2 className="h-3.5 w-3.5 animate-spin" /> Mapping components and dependencies…
          </p>
        )}
        {error && <p className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-300">{error}</p>}
      </div>
    </dialog>
  );
}

"use client";

import clsx from "clsx";
import { Focus, Search, X } from "lucide-react";
import { useEffect, useId, useMemo, useRef, useState } from "react";
import { searchNodes, type SearchField } from "@/lib/search";
import type { ArchNode } from "@/lib/types";
import { FOCUS_SEARCH_EVENT, KIND_META } from "@/lib/ui";

const MATCH_LABEL: Record<SearchField, string> = { name: "name", path: "path", export: "export", keyword: "keyword", description: "description" };

type Props = {
  nodes: ArchNode[];
  onSelect: (nodeId: string) => void;
  focusEnabled: boolean;
  hasSelection: boolean;
  onToggleFocus: () => void;
};

export function SearchBox({ nodes, onSelect, focusEnabled, hasSelection, onToggleFocus }: Props) {
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const listId = useId();
  const labelOf = useMemo(() => new Map(nodes.map((n) => [n.id, n])), [nodes]);
  const hits = useMemo(() => searchNodes(nodes, query), [nodes, query]);

  useEffect(() => {
    const focusInput = () => {
      inputRef.current?.focus();
      inputRef.current?.select();
      setOpen(true);
    };
    window.addEventListener(FOCUS_SEARCH_EVENT, focusInput);
    return () => window.removeEventListener(FOCUS_SEARCH_EVENT, focusInput);
  }, []);

  const choose = (nodeId: string) => {
    onSelect(nodeId);
    setOpen(false);
    inputRef.current?.blur();
  };

  const showList = open && query.trim().length > 0;
  const activeId = hits[active] ? `${listId}-opt-${hits[active]!.nodeId}` : undefined;

  return (
    <div data-tour="search" className="flex w-[min(22rem,100%)] items-start gap-1.5">
      <div className="relative min-w-0 flex-1">
        <div className="flex items-center gap-2 rounded-lg border border-zinc-700 bg-zinc-950/90 px-2.5 backdrop-blur focus-within:border-violet-500 focus-within:ring-2 focus-within:ring-violet-500/30">
          <Search className="h-3.5 w-3.5 shrink-0 text-zinc-500" />
          <input
            ref={inputRef}
            value={query}
            onChange={(e) => {
              setQuery(e.target.value);
              setActive(0);
              setOpen(true);
            }}
            onFocus={() => setOpen(true)}
            onBlur={() => setTimeout(() => setOpen(false), 120)}
            onKeyDown={(e) => {
              if (e.key === "ArrowDown") {
                e.preventDefault();
                setActive((i) => Math.min(i + 1, Math.max(0, hits.length - 1)));
              } else if (e.key === "ArrowUp") {
                e.preventDefault();
                setActive((i) => Math.max(i - 1, 0));
              } else if (e.key === "Enter" && hits[active]) {
                e.preventDefault();
                choose(hits[active]!.nodeId);
              } else if (e.key === "Escape") {
                if (query) setQuery("");
                else inputRef.current?.blur();
                setOpen(false);
              }
            }}
            placeholder="Search components…"
            aria-label="Search components"
            role="combobox"
            aria-expanded={showList}
            aria-controls={listId}
            aria-autocomplete="list"
            aria-activedescendant={showList ? activeId : undefined}
            spellCheck={false}
            className="min-w-0 flex-1 bg-transparent py-1.5 text-xs text-zinc-100 placeholder:text-zinc-600 focus:outline-none"
          />
          {query ? (
            <button type="button" aria-label="Clear search" onClick={() => { setQuery(""); inputRef.current?.focus(); }} className="rounded p-0.5 text-zinc-500 hover:text-zinc-200">
              <X className="h-3.5 w-3.5" />
            </button>
          ) : (
            <kbd className="hidden rounded border border-zinc-700 px-1 font-mono text-[10px] text-zinc-500 sm:block" title="Press / or Ctrl+K to search">/</kbd>
          )}
        </div>

        {showList && (
          <ul id={listId} role="listbox" aria-label="Matching components" className="absolute left-0 right-0 top-full z-20 mt-1 max-h-72 overflow-y-auto rounded-lg border border-zinc-700 bg-zinc-950/95 py-1 shadow-xl backdrop-blur">
            {hits.length === 0 ? (
              <li role="presentation" className="px-3 py-2 text-xs text-zinc-500">
                No component matches “{query.trim()}”. Try part of a file name or a word from its description.
              </li>
            ) : (
              hits.map((hit, i) => {
                const node = labelOf.get(hit.nodeId)!;
                return (
                  <li
                    key={hit.nodeId}
                    id={`${listId}-opt-${hit.nodeId}`}
                    role="option"
                    aria-selected={i === active}
                    onMouseDown={(e) => e.preventDefault()}
                    onClick={() => choose(hit.nodeId)}
                    onMouseEnter={() => setActive(i)}
                    className={clsx("flex cursor-pointer items-center gap-2 px-3 py-1.5", i === active && "bg-zinc-800/80")}
                  >
                    <span className="h-2 w-2 shrink-0 rounded-sm" style={{ background: KIND_META[node.data.kind].hex }} />
                    <span className="min-w-0 flex-1">
                      <span className="block truncate text-xs font-medium text-zinc-100">{node.data.label}</span>
                      <span className="block truncate font-mono text-[10px] text-zinc-500">{node.data.filePath}</span>
                    </span>
                    <span className="shrink-0 rounded bg-zinc-800 px-1.5 py-0.5 text-[10px] text-zinc-400">{MATCH_LABEL[hit.matchedOn]}</span>
                  </li>
                );
              })
            )}
          </ul>
        )}
      </div>

      <button
        type="button"
        onClick={onToggleFocus}
        aria-pressed={focusEnabled}
        title="Focus mode (F): dim everything except the selected component and what it directly connects to"
        className={clsx(
          "flex shrink-0 items-center gap-1 rounded-lg border px-2 py-1.5 text-xs font-medium backdrop-blur transition",
          focusEnabled ? "border-violet-500/60 bg-violet-500/20 text-violet-100" : "border-zinc-700 bg-zinc-950/90 text-zinc-300 hover:border-zinc-500",
        )}
      >
        <Focus className="h-3.5 w-3.5" /> Focus
      </button>
      {focusEnabled && !hasSelection && <span className="self-center text-[11px] text-violet-300">Click a component</span>}
    </div>
  );
}

"use client";

import { ChevronLeft, ChevronRight, X } from "lucide-react";
import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import { TOUR_STEPS, type TourStep } from "@/lib/tour";

const SPOTLIGHT_PADDING_PX = 6;
const CARD_MAX_WIDTH_PX = 352;
const CARD_ESTIMATED_HEIGHT_PX = 210;
const VIEWPORT_MARGIN_PX = 12;
/** A target taller than this share of the viewport (the canvas) gets the card inside it instead of beside it. */
const LARGE_TARGET_SHARE = 0.6;
/** Re-measure shortly after a step changes: the drawer may still be switching tabs. */
const REMEASURE_DELAY_MS = 150;

type Rect = { top: number; left: number; width: number; height: number };

function measure(step: TourStep): Rect | null {
  const el = document.querySelector<HTMLElement>(`[data-tour="${step.target}"]`);
  if (!el) return null;
  const r = el.getBoundingClientRect();
  if (r.width === 0 && r.height === 0) return null;
  return { top: r.top, left: r.left, width: r.width, height: r.height };
}

function placeCard(rect: Rect | null, vw: number, vh: number): { top: number; left: number } {
  const width = Math.min(CARD_MAX_WIDTH_PX, vw - 2 * VIEWPORT_MARGIN_PX);
  const clampLeft = (left: number) => Math.max(VIEWPORT_MARGIN_PX, Math.min(left, vw - width - VIEWPORT_MARGIN_PX));
  if (!rect) return { top: Math.max(VIEWPORT_MARGIN_PX, (vh - CARD_ESTIMATED_HEIGHT_PX) / 2), left: clampLeft((vw - width) / 2) };

  const centerX = rect.left + rect.width / 2;
  if (rect.height > vh * LARGE_TARGET_SHARE) {
    return { top: vh - CARD_ESTIMATED_HEIGHT_PX - 2 * VIEWPORT_MARGIN_PX, left: clampLeft(centerX - width / 2) };
  }
  const below = rect.top + rect.height + SPOTLIGHT_PADDING_PX + VIEWPORT_MARGIN_PX;
  if (below + CARD_ESTIMATED_HEIGHT_PX < vh) return { top: below, left: clampLeft(centerX - width / 2) };
  const above = rect.top - SPOTLIGHT_PADDING_PX - VIEWPORT_MARGIN_PX - CARD_ESTIMATED_HEIGHT_PX;
  if (above > 0) return { top: above, left: clampLeft(centerX - width / 2) };
  return { top: vh - CARD_ESTIMATED_HEIGHT_PX - 2 * VIEWPORT_MARGIN_PX, left: clampLeft(centerX - width / 2) };
}

type Props = {
  open: boolean;
  onClose: () => void;
  /** Called when a step needs a particular drawer tab open. */
  onEnterStep: (step: TourStep) => void;
};

export function GuidedTour({ open, onClose, onEnterStep }: Props) {
  const [index, setIndex] = useState(0);
  const [rect, setRect] = useState<Rect | null>(null);
  const [viewport, setViewport] = useState({ width: 0, height: 0 });
  const nextRef = useRef<HTMLButtonElement>(null);
  const returnFocusTo = useRef<Element | null>(null);
  const step = TOUR_STEPS[index]!;
  const isLast = index === TOUR_STEPS.length - 1;

  const update = useCallback(() => {
    setRect(measure(step));
    setViewport({ width: window.innerWidth, height: window.innerHeight });
  }, [step]);

  // Opening always starts from the first step and remembers where focus was.
  useEffect(() => {
    if (!open) return;
    setIndex(0);
    returnFocusTo.current = document.activeElement;
  }, [open]);

  useLayoutEffect(() => {
    if (!open) return;
    onEnterStep(step);
    update();
    const timer = setTimeout(update, REMEASURE_DELAY_MS);
    window.addEventListener("resize", update);
    window.addEventListener("scroll", update, true);
    return () => {
      clearTimeout(timer);
      window.removeEventListener("resize", update);
      window.removeEventListener("scroll", update, true);
    };
    // `onEnterStep` is intentionally not a dependency: it only switches tabs and must run once per step.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, step, update]);

  useEffect(() => {
    if (open) nextRef.current?.focus();
  }, [open, index]);

  const close = useCallback(() => {
    onClose();
    if (returnFocusTo.current instanceof HTMLElement) returnFocusTo.current.focus();
  }, [onClose]);

  const go = useCallback(
    (delta: number) => {
      const next = index + delta;
      if (next < 0) return;
      if (next >= TOUR_STEPS.length) close();
      else setIndex(next);
    },
    [index, close],
  );

  useEffect(() => {
    if (!open) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") close();
      else if (event.key === "ArrowRight") go(1);
      else if (event.key === "ArrowLeft") go(-1);
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [open, close, go]);

  if (!open) return null;

  const card = placeCard(rect, viewport.width || window.innerWidth, viewport.height || window.innerHeight);
  const cardWidth = Math.min(CARD_MAX_WIDTH_PX, (viewport.width || window.innerWidth) - 2 * VIEWPORT_MARGIN_PX);

  return (
    <div className="pointer-events-none fixed inset-0 z-50">
      {rect ? (
        <div
          aria-hidden="true"
          className="absolute rounded-xl ring-2 ring-violet-400 transition-all duration-200 motion-reduce:transition-none"
          style={{
            top: rect.top - SPOTLIGHT_PADDING_PX,
            left: rect.left - SPOTLIGHT_PADDING_PX,
            width: rect.width + 2 * SPOTLIGHT_PADDING_PX,
            height: rect.height + 2 * SPOTLIGHT_PADDING_PX,
            boxShadow: "0 0 0 9999px rgba(9, 9, 11, 0.62)",
          }}
        />
      ) : (
        <div aria-hidden="true" className="absolute inset-0 bg-zinc-950/60" />
      )}

      <div
        role="dialog"
        aria-modal="false"
        aria-labelledby="tour-title"
        aria-describedby="tour-body"
        className="pointer-events-auto absolute rounded-xl border border-zinc-700 bg-zinc-900/95 p-4 text-zinc-100 shadow-2xl shadow-black/60 backdrop-blur"
        style={{ top: card.top, left: card.left, width: cardWidth }}
      >
        <div className="mb-1 flex items-center justify-between gap-2">
          <span className="text-[11px] font-medium uppercase tracking-wider text-violet-300" aria-live="polite">
            Step {index + 1} of {TOUR_STEPS.length}
          </span>
          <button type="button" onClick={close} aria-label="Close the tour" className="rounded p-1 text-zinc-400 hover:bg-zinc-800 hover:text-zinc-100">
            <X className="h-4 w-4" />
          </button>
        </div>
        <h2 id="tour-title" className="text-sm font-semibold">
          {step.title}
        </h2>
        <p id="tour-body" className="mt-1 text-xs leading-relaxed text-zinc-300">
          {step.body}
        </p>
        <div className="mt-3 flex items-center justify-between gap-2">
          <button type="button" onClick={close} className="text-xs text-zinc-400 underline-offset-2 hover:text-zinc-200 hover:underline">
            {isLast ? "Close" : "Skip tour"}
          </button>
          <div className="flex items-center gap-1.5">
            <button
              type="button"
              onClick={() => go(-1)}
              disabled={index === 0}
              className="flex items-center gap-0.5 rounded-md border border-zinc-700 px-2 py-1 text-xs text-zinc-300 hover:bg-zinc-800 disabled:opacity-40"
            >
              <ChevronLeft className="h-3.5 w-3.5" /> Back
            </button>
            <button ref={nextRef} type="button" onClick={() => go(1)} className="flex items-center gap-0.5 rounded-md bg-violet-600 px-3 py-1 text-xs font-medium text-white hover:bg-violet-500">
              {isLast ? "Done" : "Next"} {!isLast && <ChevronRight className="h-3.5 w-3.5" />}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import clsx from "clsx";
import { AlertTriangle, CircleCheck, Info, ShieldAlert } from "lucide-react";
import { useState } from "react";
import { Glossary } from "@/components/Glossary";
import { riskiestNodes, type HealthIssue, type HealthReport, type HealthSeverity } from "@/lib/engines/health";
import { EXAMPLE_RULES_JSON, parseRulesJson } from "@/lib/rulesSchema";
import type { ArchRule, ArchitectureGraph, RuleViolation } from "@/lib/types";
import { HEALTH_META } from "@/lib/ui";

const SEVERITY_CHIP: Record<HealthSeverity, string> = {
  high: "bg-red-500/15 text-red-300 ring-red-500/40",
  medium: "bg-amber-500/15 text-amber-300 ring-amber-500/40",
  low: "bg-zinc-700/40 text-zinc-300 ring-zinc-600/60",
};

const GRADE_TONE: Record<HealthReport["grade"], string> = {
  A: "text-emerald-300 ring-emerald-500/50",
  B: "text-emerald-300 ring-emerald-500/40",
  C: "text-amber-300 ring-amber-500/50",
  D: "text-orange-300 ring-orange-500/50",
  F: "text-red-300 ring-red-500/60",
};

type Props = {
  graph: ArchitectureGraph;
  report: HealthReport;
  selectedNodeId: string | null;
  onSelectNode: (nodeId: string) => void;
  rules: ArchRule[] | undefined;
  violations: RuleViolation[];
  onSetRules: (rules: ArchRule[]) => void;
};

/** Rules editor: what this architecture must never do, checked live against the map. */
function RulesSection({ graph, rules, violations, onSelectNode, onSetRules }: Pick<Props, "graph" | "rules" | "violations" | "onSelectNode" | "onSetRules">) {
  const [text, setText] = useState(() => (rules && rules.length ? JSON.stringify(rules, null, 2) : ""));
  const [error, setError] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const errors = violations.filter((v) => v.severity === "error").length;

  const apply = () => {
    const parsed = text.trim() === "" ? { ok: true as const, rules: [] as ArchRule[] } : parseRulesJson(text);
    if (!parsed.ok) {
      setError(parsed.error);
      setSaved(false);
      return;
    }
    setError(null);
    setSaved(true);
    onSetRules(parsed.rules);
  };

  return (
    <section className="space-y-1.5" aria-label="Architecture rules">
      <h3 className="flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wider text-zinc-500">
        <ShieldAlert className="h-3.5 w-3.5" /> Rules {rules?.length ? `(${rules.length})` : ""}
        {errors > 0 && <span className="rounded bg-orange-500/20 px-1.5 text-[10px] font-semibold normal-case text-orange-300">{errors} broken</span>}
      </h3>

      {rules?.length ? (
        violations.length === 0 ? (
          <p className="flex items-center gap-2 rounded-lg border border-emerald-500/20 bg-emerald-500/5 px-3 py-2 text-xs text-emerald-300">
            <CircleCheck className="h-4 w-4" /> All {rules.length} rule{rules.length === 1 ? "" : "s"} satisfied.
          </p>
        ) : (
          <ul className="divide-y divide-zinc-800/80 rounded-lg border border-orange-500/30">
            {violations.map((v, i) => (
              <li key={`${v.ruleId}-${i}`}>
                <button type="button" onClick={() => v.nodeIds[0] && onSelectNode(v.nodeIds[0])} className="flex w-full items-start gap-2 px-3 py-2 text-left transition hover:bg-zinc-800/40">
                  <span className={clsx("mt-0.5 shrink-0 rounded px-1.5 py-0.5 text-[10px] font-semibold uppercase ring-1 ring-inset", v.severity === "error" ? "bg-orange-500/15 text-orange-300 ring-orange-500/40" : "bg-zinc-700/40 text-zinc-300 ring-zinc-600/60")}>
                    {v.severity}
                  </span>
                  <span className="min-w-0">
                    <span className="block text-xs font-medium text-zinc-200">{v.message}</span>
                    <span className="block font-mono text-[10px] text-zinc-500">rule: {v.ruleId}</span>
                  </span>
                </button>
              </li>
            ))}
          </ul>
        )
      ) : (
        <p className="rounded-lg border border-zinc-800 bg-zinc-900/40 px-3 py-2 text-xs leading-relaxed text-zinc-400">
          Rules state what this architecture must <b className="text-zinc-200">never</b> do, for example “the UI must not touch the database directly”. Broken rules are
          highlighted on the map and listed here. Add some below.
        </p>
      )}

      <details className="rounded-lg border border-zinc-800 bg-zinc-900/30 text-xs text-zinc-400" open={!rules?.length}>
        <summary className="cursor-pointer px-3 py-2 text-zinc-300">Edit rules</summary>
        <div className="space-y-2 border-t border-zinc-800 p-3">
          <textarea
            value={text}
            onChange={(e) => {
              setText(e.target.value);
              setSaved(false);
            }}
            rows={9}
            spellCheck={false}
            aria-label="Rules as JSON"
            placeholder={EXAMPLE_RULES_JSON}
            className="w-full rounded-md border border-zinc-700 bg-zinc-950 px-2 py-1.5 font-mono text-[11px] text-zinc-200 placeholder:text-zinc-700 focus:border-violet-500 focus:outline-none"
          />
          {error && <p role="alert" className="rounded border border-red-500/30 bg-red-500/10 px-2 py-1 text-red-300">{error}</p>}
          <div className="flex flex-wrap items-center gap-2">
            <button type="button" onClick={apply} className="rounded-md bg-violet-600 px-2.5 py-1 text-xs font-medium text-white hover:bg-violet-500">
              Apply rules
            </button>
            <button type="button" onClick={() => { setText(EXAMPLE_RULES_JSON); setError(null); setSaved(false); }} className="rounded-md border border-zinc-700 px-2.5 py-1 text-xs text-zinc-300 hover:bg-zinc-800">
              Insert example
            </button>
            {saved && <span className="text-emerald-300">Applied</span>}
          </div>
          <p className="leading-relaxed">
            Types: <code className="text-zinc-300">forbid</code> (from → to), <code className="text-zinc-300">no-cycles</code>, <code className="text-zinc-300">max-dependents</code>,{" "}
            <code className="text-zinc-300">max-lines</code>. Selectors: <code className="text-zinc-300">kind:frontend</code>, <code className="text-zinc-300">path:src/ui/**</code>,{" "}
            <code className="text-zinc-300">label:Users*</code>, <code className="text-zinc-300">id:…</code>, <code className="text-zinc-300">*</code>; join alternatives with{" "}
            <code className="text-zinc-300">|</code>. Add <code className="text-zinc-300">&quot;severity&quot;: &quot;warn&quot;</code> for advice instead of an error. The same rules can live in a{" "}
            <code className="text-zinc-300">.codearchitect.json</code> file for the command-line check.
          </p>
          <p className="text-zinc-600">Graph: {graph.name}</p>
        </div>
      </details>
    </section>
  );
}

function summarize(report: HealthReport): string {
  const { cycles, hubs, layering, large, orphans } = report.counts;
  const parts = [
    cycles && `${cycles} circular ${cycles === 1 ? "dependency" : "dependencies"}`,
    layering && `${layering} crossed ${layering === 1 ? "layer" : "layers"}`,
    hubs && `${hubs} ${hubs === 1 ? "hub" : "hubs"}`,
    large && `${large} large ${large === 1 ? "file" : "files"}`,
    orphans && `${orphans} unconnected ${orphans === 1 ? "component" : "components"}`,
  ].filter(Boolean);
  return parts.length ? `Found ${parts.join(", ")}.` : "No structural problems found.";
}

function IssueRow({ issue, onSelectNode }: { issue: HealthIssue; onSelectNode: (id: string) => void }) {
  return (
    <li>
      <button
        type="button"
        onClick={() => issue.nodeIds[0] && onSelectNode(issue.nodeIds[0])}
        className="flex w-full items-start gap-2 px-3 py-2 text-left transition hover:bg-zinc-800/40"
      >
        <span className={clsx("mt-0.5 shrink-0 rounded px-1.5 py-0.5 text-[10px] font-semibold uppercase ring-1 ring-inset", SEVERITY_CHIP[issue.severity])}>{issue.severity}</span>
        <span className="min-w-0">
          <span className="block text-sm font-medium text-zinc-200">{issue.title}</span>
          <span className="block text-xs leading-relaxed text-zinc-500">{issue.detail}</span>
        </span>
      </button>
    </li>
  );
}

export function HealthPanel({ graph, report, selectedNodeId, onSelectNode, rules, violations, onSetRules }: Props) {
  const label = (id: string) => graph.nodes.find((n) => n.id === id)?.data.label ?? id;
  const risky = riskiestNodes(report, 5);

  return (
    <div className="space-y-5">
      <div className="flex items-center gap-4 rounded-lg border border-zinc-800 bg-zinc-900/50 p-3">
        <div
          className={clsx("flex h-16 w-16 shrink-0 flex-col items-center justify-center rounded-full bg-zinc-950 ring-4", GRADE_TONE[report.grade])}
          role="img"
          aria-label={`Architecture health grade ${report.grade}, ${report.overall} out of 100`}
        >
          <span className="text-2xl font-bold leading-none">{report.grade}</span>
          <span className="text-[10px] text-zinc-500">{report.overall}/100</span>
        </div>
        <div className="min-w-0 space-y-1">
          <h2 className="text-sm font-semibold text-zinc-100">Architecture health</h2>
          <p className="text-xs leading-relaxed text-zinc-400">{summarize(report)}</p>
        </div>
      </div>

      <p className="flex items-start gap-2 rounded-lg border border-zinc-800 bg-zinc-900/30 px-3 py-2 text-[11px] leading-relaxed text-zinc-500">
        <Info className="mt-0.5 h-3.5 w-3.5 shrink-0" />
        <span>
          The canvas now shows each component&apos;s <b className="text-zinc-300">change-risk</b>: how costly and fragile it is to change, judged only from structure
          (who depends on whom, file size). It does not judge code quality.
        </span>
      </p>

      <div className="flex flex-wrap gap-3 text-[11px] text-zinc-400">
        {(Object.keys(HEALTH_META) as Array<keyof typeof HEALTH_META>).map((level) => (
          <span key={level} className="flex items-center gap-1.5">
            <span className="h-2.5 w-2.5 rounded-full" style={{ background: HEALTH_META[level].hex }} />
            {HEALTH_META[level].label}
          </span>
        ))}
        <span className="flex items-center gap-1.5">
          <span className="h-0.5 w-4 bg-rose-500" /> Circular dependency
        </span>
      </div>

      <section className="space-y-1.5">
        <h3 className="text-[11px] font-semibold uppercase tracking-wider text-zinc-500">Riskiest components</h3>
        {risky.length === 0 ? (
          <p className="text-xs text-zinc-600">Nothing stands out.</p>
        ) : (
          <ul className="divide-y divide-zinc-800/80 rounded-lg border border-zinc-800">
            {risky.map((n) => (
              <li key={n.nodeId}>
                <button
                  type="button"
                  onClick={() => onSelectNode(n.nodeId)}
                  aria-current={selectedNodeId === n.nodeId}
                  className={clsx("flex w-full items-start gap-2 px-3 py-2 text-left transition hover:bg-zinc-800/40", selectedNodeId === n.nodeId && "bg-zinc-800/50")}
                >
                  <span className={clsx("mt-0.5 shrink-0 rounded px-1.5 py-0.5 text-[10px] font-semibold ring-1 ring-inset", HEALTH_META[n.level].chip)}>{n.score}</span>
                  <span className="min-w-0">
                    <span className="block text-sm font-medium text-zinc-200">{label(n.nodeId)}</span>
                    <span className="block text-xs text-zinc-500">{n.reasons.join(" · ") || "Connected to a few components"}</span>
                  </span>
                </button>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section className="space-y-1.5">
        <h3 className="flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wider text-zinc-500">
          Things to look at ({report.issues.length})
        </h3>
        {report.issues.length === 0 ? (
          <p className="flex items-center gap-2 rounded-lg border border-emerald-500/20 bg-emerald-500/5 px-3 py-2 text-xs text-emerald-300">
            <CircleCheck className="h-4 w-4" /> No circular dependencies, crossed layers, hubs or oversized files.
          </p>
        ) : (
          <ul className="divide-y divide-zinc-800/80 rounded-lg border border-zinc-800">
            {report.issues.map((issue) => (
              <IssueRow key={issue.id} issue={issue} onSelectNode={onSelectNode} />
            ))}
          </ul>
        )}
      </section>

      <RulesSection key={graph.id} graph={graph} rules={rules} violations={violations} onSelectNode={onSelectNode} onSetRules={onSetRules} />

      <details className="rounded-lg border border-zinc-800 bg-zinc-900/30 text-xs text-zinc-400">
        <summary className="flex cursor-pointer items-center gap-1.5 px-3 py-2 text-zinc-300">
          <AlertTriangle className="h-3.5 w-3.5" /> How are these numbers calculated?
        </summary>
        <div className="space-y-2 border-t border-zinc-800 px-3 py-2 leading-relaxed">
          <p>
            <b className="text-zinc-300">Risk (0–100)</b> per component = 8 per component that depends on it (up to 40) + 3 per thing it depends on (up to 15) + 1 per 20 lines
            (up to 20) + 30 if it is in a circular dependency + 15 if it crosses layers. Under 35 is healthy, 35–64 watch, 65+ risky.
          </p>
          <p>
            <b className="text-zinc-300">Overall</b> starts at 100 and loses 12 per cycle, 8 per crossed layer, 5 per hub, 4 per large file and 2 per unconnected component.
            A ≥ 85, B ≥ 70, C ≥ 55, D ≥ 40, otherwise F.
          </p>
          <p>These are heuristics for finding where to look first, not a verdict.</p>
        </div>
      </details>

      <Glossary />
    </div>
  );
}

