const SOURCE_EXTENSIONS = /\.(tsx?|jsx?|mjs|cjs|py|go|rs|java|kt|rb|cs|php|vue|svelte|m)$/i;
const IGNORED_PATHS =
  /(^|\/)(node_modules|dist|build|out|\.next|\.git|vendor|testdata|venv|\.venv|__pycache__|coverage|target)(\/|$)|\.d\.ts$|(\.|_)(test|spec|stories)\.|(^|\/)(__tests__|tests?)\//i;
/** Maven site resources (generated diagrams, vendored scripts) and minified bundles are not source. */
const NON_SOURCE_ASSETS = /(^|\/)src\/site\/|\.min\.(js|mjs)$/i;
/** Java test classes (`FooTest.java`, `FooIT.java`). Case-sensitive on purpose: `Audit.java` is not a test. */
const JAVA_TESTS = /[a-z0-9](Test|Tests|IT)\.java$/;
/** Java files that declare no types: documentation and module descriptors. */
const JAVA_NON_CODE = /(^|\/)(package|module)-info\.java$/;
/** C# build output, generated code, assembly info and test projects. Case-sensitive on purpose. */
const CS_NON_SOURCE = /(^|\/)(obj|bin\/(Debug|Release))\/|\.(Designer|g|g\.i|generated)\.cs$|(^|\/)[^/]*AssemblyInfo[^/]*\.cs$|\.Tests?(\.\w+)*\/|[a-z0-9](Test|Tests)\.cs$/;
/** Kotlin test sources and build scripts. Case-sensitive on purpose. */
const KT_NON_SOURCE = /(^|\/)src\/(test|androidTest|jvmTest|commonTest|integrationTest)[^/]*\/|[a-z0-9](Test|Tests|IT)\.kt$|\.kts$/;
/** Ruby specs and cucumber features. */
const RB_NON_SOURCE = /(^|\/)(spec|features)\//;
const CONFIG_FILES = /(^|\/)[^/]*(config|rc)\.(c|m)?(js|ts)$/i;

export const MAX_GRAPH_FILES = 60;
const MAX_NODE_CODE_LINES = 120;

const KIND_RULES: Array<{ kind: NodeKind; pattern: RegExp }> = [
  { kind: "data", pattern: /(Repository|Dao|Entity|DbContext)\.(java|cs)$|(^|\/)Migrations\/|(^|\/)(db|database|models?|schemas?|prisma|repositor(y|ies)|migrations?|cache|redis|entities|dal|store)(\/|\.|_|$)/i },
  { kind: "api", pattern: /(Controller|Resource|Endpoint|Hub)\.(java|cs)$|_controller\.rb$|(^|\/)(api|routes?|routers?|endpoints?|handlers?|urls\.py|views\.py)(\/|\.|$)|route\.(t|j)s$/i },
  { kind: "frontend", pattern: /\.(tsx|jsx|vue|svelte)$|(^|\/)(components|pages|screens|ui|views|app\/.*page)(\/|\.|$)/i },
];

export function classifyPath(path: string): NodeKind {
  return KIND_RULES.find((rule) => rule.pattern.test(path))?.kind ?? "logic";
}

export function isAnalyzableSource(path: string): boolean {
  return SOURCE_EXTENSIONS.test(path) && !IGNORED_PATHS.test(path) && !CONFIG_FILES.test(path) && !JAVA_TESTS.test(path) && !JAVA_NON_CODE.test(path) && !NON_SOURCE_ASSETS.test(path) && !CS_NON_SOURCE.test(path) && !KT_NON_SOURCE.test(path) && !RB_NON_SOURCE.test(path);
}

const JS_IMPORT = /(?:import\s[^'"]*?from\s*|import\s*\(\s*|require\s*\(\s*|export\s[^'"]*?from\s*)['"]([^'"]+)['"]/g;
const JS_EXPORT = /export\s+(default\s+)?(?:async\s+)?(?:function\*?|const|let|class|type|interface|enum)\s+([A-Za-z_$][\w$]*)/g;
const FIRST_SIGNATURE = /(?:function\s+\w+|func\s+\w+|fn\s+\w+|def\s+\w+|\w+\s*=\s*(?:async\s*)?)\s*\(([^)]*)\)/;

/**
 * Specifiers imported only through `import type` / `export type` (and never by value) in a file.
 * Type-only imports are erased at runtime, so they are not architectural coupling.
 */
export function typeOnlyImports(file: SourceFile): Set<string> {
  if (/\.(py|m|go|java|rs|cs|kt|rb)$/.test(file.path)) return new Set();
  const typeSpecs = new Set<string>();
  const valueSpecs = new Set<string>();
  for (const match of file.content.matchAll(JS_IMPORT)) {
    const spec = match[1];
    if (!spec) continue;
    (/^(import|export)\s+type\b/.test(match[0]) ? typeSpecs : valueSpecs).add(spec);
  }
  return new Set([...typeSpecs].filter((s) => !valueSpecs.has(s)));
}

export function extractImports(file: SourceFile): string[] {
  if (file.path.endsWith(".go")) return [...new Set(goImports(file.content).map((i) => i.path))];
  if (file.path.endsWith(".cs")) return [...new Set(csUsings(file.content).map((u) => (u.isStatic ? "static " : "") + u.namespace))];
  if (file.path.endsWith(".rb")) return [...new Set(rubyRequires(file.content).map((q) => (q.kind === "relative" ? "./" : "") + q.target))];
  if (file.path.endsWith(".kt")) return [...new Set(ktImports(file.content).map((i) => i.name + (i.wildcard ? ".*" : "")))];
  if (file.path.endsWith(".rs")) return [...new Set(rustUses(file.content).map((u) => u.segments.join("::")))];
  if (file.path.endsWith(".java")) return [...new Set(javaImports(file.content).map((i) => i.name + (i.wildcard ? ".*" : "")))];
  if (file.path.endsWith(".py")) return [...new Set(parsePythonImports(file.content).map((i) => "." .repeat(i.level) + i.module).filter(Boolean))];
  const specs = new Set<string>();
  const pattern = JS_IMPORT;
  for (const match of file.content.matchAll(pattern)) {
    const spec = match[1];
    if (spec) specs.add(spec);
  }
  return [...specs];
}

/** Names in `export { a, b as c }` lists, with or without `from`: how modules re-export things declared elsewhere. */
const LISTED_EXPORT = /export\s+(?:type\s+)?\{([^}]*)\}/g;

function listedExports(content: string): string[] {
  const names: string[] = [];
  // Doc comments often show `export { a, b }` as an example; only real code counts.
  const code = content.replace(/\/\*[\s\S]*?\*\//g, " ").replace(/^\s*\/\/.*$/gm, " ");
  for (const m of code.matchAll(LISTED_EXPORT)) {
    for (const part of m[1]!.split(",")) {
      const cleaned = part.trim().replace(/^type\s+/, "");
      const exported = cleaned.split(/\s+as\s+/).pop()?.trim();
      if (exported && /^[A-Za-z_$][\w$]*$/.test(exported)) names.push(exported === "default" ? "default" : exported);
    }
  }
  return names.filter((n) => n !== "default");
}

export function extractExports(file: SourceFile): string[] {
  if (file.path.endsWith(".m")) return matlabFunctions(file.content);
  if (file.path.endsWith(".go")) return goExports(file.content);
  if (file.path.endsWith(".java")) return javaExports(file.content);
  if (file.path.endsWith(".rs")) return rustExports(file.content);
  if (file.path.endsWith(".cs")) return csExports(file.content);
  if (file.path.endsWith(".kt")) return ktExports(file.content);
  if (file.path.endsWith(".rb")) return rubyExports(file.content);
  if (file.path.endsWith(".py")) return pythonExports(file.content);
  return [...new Set([...[...file.content.matchAll(JS_EXPORT)].map((m) => (m[1] ? `default ${m[2]}` : m[2]!)), ...listedExports(file.content)])];
}

function extractParams(file: SourceFile): CodeParam[] {
  const signature = FIRST_SIGNATURE.exec(file.content)?.[1];
  if (!signature) return [];
  return signature
    .split(",")
    .map((p) => p.trim())
    .filter((p) => p && p !== "self")
    .map((p) => {
      const [name, type] = p.split(/:(.*)/s).map((s) => s?.trim());
      return { name: (name ?? p).replace(/[{}?]/g, "").trim(), type: type || "unknown" };
    });
}

/** Files whose imports are analysed by their own language module instead of the JS/TS symbol scanner. */
const hasOwnImportAnalysis = (path: string) => /\.(py|m|go|java|rs|cs|kt|rb)$/i.test(path);

function stripExtension(path: string): string {
  return path.replace(/\.(tsx?|jsx?|mjs|cjs|py|go|rs|java|cs|kt|rb|vue|svelte|m)$/i, "").replace(/\/index$/, "");
}

function joinPath(base: string, relative: string): string {
  const parts = base.split("/").slice(0, -1);
  for (const segment of relative.split("/")) {
    if (segment === "..") parts.pop();
    else if (segment !== ".") parts.push(segment);
  }
  return parts.join("/");
}

/** Resolve an import specifier to a file in the set; supports `./`, `../`, `@/` and `~/` aliases and Python modules. */
export function resolveImport(fromPath: string, spec: string, index: ReadonlyMap<string, string>): string | undefined {
  let candidate: string | undefined;
  if (spec.startsWith(".") && !fromPath.endsWith(".py")) candidate = joinPath(fromPath, spec);
  else if (/^[@~]\//.test(spec)) candidate = spec.slice(2);
  else if (fromPath.endsWith(".py")) candidate = spec.replace(/^\.+/, "").replace(/\./g, "/");
  if (!candidate) return undefined;

  const key = stripExtension(candidate);
  return index.get(key) ?? index.get(`src/${key}`) ?? [...index.entries()].find(([k]) => k.endsWith(`/${key}`))?.[1];
}

function slugify(path: string): string {
  return stripExtension(path).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

function labelFor(path: string): string {
  const parts = stripExtension(path).split("/");
  const base = parts.pop() ?? path;
  // Next.js-style `page`/`route` files are named after their folder.
  // Rust `mod.rs` is the module named by its folder.
  const name = base === "mod" && parts.length > 0 ? parts.pop()! : ["page", "route", "index", "layout"].includes(base) ? `${parts.pop() ?? base}/${base}` : base;
  return name.replace(/[-_]/g, " ").replace(/([a-z])([A-Z])/g, "$1 $2").replace(/\b\w/g, (c) => c.toUpperCase());
}

function languageFor(path: string): string {
  if (/\.m$/i.test(path)) return "matlab";
  return path.split(".").pop()?.toLowerCase() ?? "text";
}

/** Prefer files that are more likely to be architectural seams: routes, services, schemas over leaf UI. */
function relevance(file: SourceFile): number {
  const kind = classifyPath(file.path);
  const kindWeight = { api: 4, data: 4, logic: 3, frontend: 2 }[kind];
  const depthPenalty = file.path.split("/").length * 0.1;
  return kindWeight - depthPenalty + Math.min(file.content.length / 20_000, 1);
}

export function selectGraphFiles(files: readonly SourceFile[], maxFiles: number = MAX_GRAPH_FILES): { selected: SourceFile[]; warnings: string[] } {
  const analyzable = files.filter((f) => isAnalyzableSource(f.path));
  // `#[cfg(test)] mod x;` files are not part of the built crate.
  const testOnly = rustTestOnlyPaths(analyzable);
  const candidates = testOnly.size ? analyzable.filter((f) => !testOnly.has(f.path)) : analyzable;
  const warnings: string[] = [];
  if (candidates.length === 0) warnings.push("No supported source files found (ts, js, py, go, java, rb, cs, php, vue, svelte).");
  if (candidates.length > maxFiles) {
    warnings.push(`Showing the ${maxFiles} most architecturally relevant of ${candidates.length} source files.`);
  }
  const selected = [...candidates].sort((a, b) => relevance(b) - relevance(a)).slice(0, maxFiles);
  return { selected, warnings };
}

export function truncateCode(content: string): string {
  const lines = content.split("\n");
  if (lines.length <= MAX_NODE_CODE_LINES) return content;
  return [...lines.slice(0, MAX_NODE_CODE_LINES), `// … ${lines.length - MAX_NODE_CODE_LINES} more lines`].join("\n");
}

/**
 * Deterministic file-level dependency graph: one node per relevant source file,
 * one edge per resolvable internal import.
 */
export function buildHeuristicGraph(name: string, files: readonly SourceFile[], options: { maxFiles?: number } = {}): ArchitectureGraph {
  const { selected, warnings } = selectGraphFiles(files, options.maxFiles);
  const index = new Map(selected.map((f) => [stripExtension(f.path), f.path]));
  const idForPath = new Map(selected.map((f) => [f.path, slugify(f.path)]));

  const nodes: ArchNode[] = selected.map((file) => ({
    id: idForPath.get(file.path)!,
    type: "component",
    position: { x: 0, y: 0 },
    data: {
      label: labelFor(file.path),
      kind: classifyPath(file.path),
      filePath: file.path,
      description: `${file.content.split("\n").length} lines · detected by path heuristics`,
      language: languageFor(file.path),
      code: truncateCode(file.content),
      exports: extractExports(file),
      imports: extractImports(file),
      params: extractParams(file),
      keywords: slugify(file.path).split("-").filter((s) => s.length >= 3),
      lineCount: file.content.split("\n").length,
    },
  }));

  const edges: DependencyEdge[] = [];
  const seen = new Set<string>();
  for (const file of selected) {
    const typeOnly = typeOnlyImports(file);
    if (hasOwnImportAnalysis(file.path)) continue;
    const symbolsBySpec = importedSymbols(file.content);
    const edgeByTarget = new Map<string, DependencyEdge>();
    for (const spec of extractImports(file)) {
      const targetPath = resolveImport(file.path, spec, index);
      if (!targetPath || targetPath === file.path) continue;
      const source = idForPath.get(file.path)!;
      const target = idForPath.get(targetPath)!;
      const id = `e-${source}--${target}`;
      const symbols = symbolsBySpec?.get(spec);
      const existing = edgeByTarget.get(id);
      if (existing) {
        // Another specifier for the same file: merge what it uses; one unknown makes the whole edge unknown.
        if (!symbols || !existing.symbols) delete existing.symbols;
        else existing.symbols = [...new Set([...existing.symbols, ...symbols])].sort();
        continue;
      }
      if (seen.has(id)) continue;
      seen.add(id);
      const edge: DependencyEdge = { id, source, target, relation: "imports", ...(typeOnly.has(spec) ? { typeOnly: true } : {}), ...(symbols ? { symbols } : {}) };
      edgeByTarget.set(id, edge);
      edges.push(edge);
    }
  }

  // Go: importer → the files that define the exported names it uses.
  for (const edge of goEdges(selected, idForPath, name)) {
    if (seen.has(edge.id)) continue;
    seen.add(edge.id);
    edges.push(edge);
  }

  // C#: namespaces and the types mentioned from them.
  for (const edge of csharpEdges(selected, idForPath)) {
    if (seen.has(edge.id)) continue;
    seen.add(edge.id);
    edges.push(edge);
  }

  // Kotlin: imports by qualified name or top-level declaration, plus same-package use.
  for (const edge of kotlinEdges(selected, idForPath)) {
    if (seen.has(edge.id)) continue;
    seen.add(edge.id);
    edges.push(edge);
  }

  // Ruby: require / require_relative / autoload, plus constants mentioned.
  for (const edge of rubyEdges(selected, idForPath)) {
    if (seen.has(edge.id)) continue;
    seen.add(edge.id);
    edges.push(edge);
  }

  // Python: imports by name (`from a import B` links to the file defining B).
  for (const edge of pythonEdges(selected, idForPath)) {
    if (seen.has(edge.id)) continue;
    seen.add(edge.id);
    edges.push(edge);
  }

  // Rust: `use` paths resolved through the module tree.
  for (const edge of rustEdges(selected, idForPath, name)) {
    if (seen.has(edge.id)) continue;
    seen.add(edge.id);
    edges.push(edge);
  }

  // Java: imports by qualified name, plus same-package use.
  for (const edge of javaEdges(selected, idForPath)) {
    if (seen.has(edge.id)) continue;
    seen.add(edge.id);
    edges.push(edge);
  }

  // MATLAB/Python scripts: add function calls, data files read/written, and layer names.
  const layer = analyzeScriptFiles(selected, idForPath);
  const allNodes = [
    ...nodes.map((n) => {
      const patch = layer.patches.get(n.data.filePath);
      return patch ? { ...n, data: { ...n.data, ...patch } } : n;
    }),
    ...layer.dataNodes,
  ];
  const allEdges = [...edges, ...layer.edges.filter((e) => !seen.has(e.id))];

  return {
    id: `import-${slugify(name)}-${Date.now().toString(36)}`,
    name,
    description: `${allNodes.length} components and ${allEdges.length} dependencies mapped heuristically.`,
    nodes: layer.kindLabels ? layoutByKind(allNodes, SCRIPT_LAYER_ORDER) : layoutByKind(allNodes),
    edges: allEdges,
    commits: [],
    scenarios: [],
    kindLabels: layer.kindLabels,
    warnings: [...warnings, ...layer.warnings],
  };
}

import { nodeById } from "@/lib/graph";
import type { ArchitectureGraph, ArchNode, DiffItem, NodeKind, ScaffoldFile, ScaffoldResult } from "@/lib/types";

function words(label: string): string[] {
  return label.replace(/([a-z])([A-Z])/g, "$1 $2").split(/[^A-Za-z0-9]+/).filter(Boolean);
}
export const pascalCase = (label: string) => words(label).map((w) => w[0]!.toUpperCase() + w.slice(1).toLowerCase()).join("");
export const camelCase = (label: string) => {
  const p = pascalCase(label);
  return p ? p[0]!.toLowerCase() + p.slice(1) : "component";
};
export const kebabCase = (label: string) => words(label).map((w) => w.toLowerCase()).join("-");

/** Conventional file location for a new component of the given kind (Next.js App Router layout). */
export function suggestFilePath(label: string, kind: NodeKind): string {
  switch (kind) {
    case "frontend":
      return `src/components/${pascalCase(label)}.tsx`;
    case "api":
      return `src/app/api/${kebabCase(label)}/route.ts`;
    case "logic":
      return `src/server/services/${camelCase(label)}.ts`;
    case "data":
      return `src/server/db/${kebabCase(label)}.ts`;
  }
}

/** The identifier other files import to use this component. */
export function primaryExport(label: string, kind: NodeKind): string {
  switch (kind) {
    case "frontend":
      return pascalCase(label);
    case "api":
      return "POST";
    case "logic":
      return `${camelCase(label)}Service`;
    case "data":
      return `${camelCase(label)}Repo`;
  }
}

function importSpecifier(filePath: string): string {
  return `@/${filePath.replace(/^src\//, "").replace(/\.(tsx?|jsx?)$/, "")}`;
}

function importLine(dep: ArchNode): string | null {
  if (dep.data.kind === "api") return null; // routes are reached over HTTP, not imported
  const name = primaryExport(dep.data.label, dep.data.kind);
  const clause = dep.data.kind === "frontend" ? name : `{ ${name} }`;
  return `import ${clause} from "${importSpecifier(dep.data.filePath)}";`;
}

function apiCall(dep: ArchNode): string {
  const route = dep.data.filePath.match(/app(\/api\/.+)\/route\.[jt]s$/)?.[1] ?? `/api/${kebabCase(dep.data.label)}`;
  return `fetch("${route}", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(payload) })`;
}

function templateFor(node: ArchNode, deps: ArchNode[]): string {
  const { label, kind } = node.data;
  const imports = deps.map(importLine).filter((l): l is string => l !== null);
  const header = imports.length ? `${imports.join("\n")}\n\n` : "";
  const firstLogic = deps.find((d) => d.data.kind === "logic" || d.data.kind === "data");
  const firstApi = deps.find((d) => d.data.kind === "api");

  switch (kind) {
    case "frontend": {
      const action = firstApi
        ? `    const response = await ${apiCall(firstApi).replace("payload", "{}")};\n    if (!response.ok) throw new Error(\`${label} failed: \${response.status}\`);`
        : `    await Promise.resolve();`;
      return `"use client";

${header}import { useState } from "react";

export default function ${pascalCase(label)}() {
  const [isPending, setIsPending] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleClick() {
    setIsPending(true);
    setError(null);
    try {
${action}
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setIsPending(false);
    }
  }

  return (
    <div>
      <button type="button" onClick={handleClick} disabled={isPending}>
        {isPending ? "Working…" : "${label}"}
      </button>
      {error && <p role="alert">{error}</p>}
    </div>
  );
}
`;
    }
    case "api": {
      const call = firstLogic ? `await ${primaryExport(firstLogic.data.label, firstLogic.data.kind)}.execute(body)` : "body";
      return `import { NextResponse } from "next/server";
${header}export async function POST(request: Request) {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "invalid JSON body" }, { status: 400 });
  }

  const result = ${call};
  return NextResponse.json(result, { status: 200 });
}
`;
    }
    case "logic": {
      const call = firstLogic ? `return ${primaryExport(firstLogic.data.label, firstLogic.data.kind)}.execute(input);` : "return { ok: true, input };";
      return `${header}export const ${primaryExport(label, kind)} = {
  async execute(input: unknown) {
    ${call}
  },
};
`;
    }
    case "data":
      return `${header}import { Pool } from "pg";

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

export const ${primaryExport(label, kind)} = {
  async execute(input: unknown) {
    const { rows } = await pool.query("SELECT $1::jsonb AS payload", [JSON.stringify(input)]);
    return rows[0];
  },
};
`;
  }
}

/** Insert an import after the last import, plus a JSX usage before the outermost closing tag when wiring UI into UI. */
function wireIntoExisting(source: ArchNode, target: ArchNode): DiffItem {
  const lines = source.data.code.split("\n");
  const line = importLine(target);
  const lastImport = lines.reduce((acc, l, i) => (/^\s*import\b/.test(l) ? i : acc), -1);
  if (line) lines.splice(lastImport + 1, 0, line);

  let usage = "imported";
  if (target.data.kind === "frontend" && /\.(tsx|jsx)$/.test(source.data.filePath)) {
    const closing = lines.reduce((acc, l, i) => (/^\s*<\/\w+>\s*$/.test(l) ? i : acc), -1);
    if (closing > 0) {
      const indent = (lines[closing]!.match(/^\s*/)?.[0] ?? "") + "  ";
      lines.splice(closing, 0, `${indent}<${pascalCase(target.data.label)} />`);
      usage = "rendered";
    }
  } else if (target.data.kind === "api") {
    lines.push("", `export async function call${pascalCase(target.data.label)}(payload: unknown) {`, `  return ${apiCall(target)}.then((r) => r.json());`, "}");
    usage = "called via a typed fetch helper";
  }

  return {
    nodeId: source.id,
    filePath: source.data.filePath,
    before: source.data.code,
    after: lines.join("\n"),
    rationale: `Wire in new ${target.data.label} (${usage}).`,
  };
}

export function scaffoldLocally(graph: ArchitectureGraph): ScaffoldResult {
  const drafts = graph.nodes.filter((n) => n.data.isDraft);
  const draftEdges = graph.edges.filter((e) => e.isDraft);
  if (drafts.length === 0 && draftEdges.length === 0) {
    throw new Error("Add a component or draw a connection in the builder first.");
  }

  const files: ScaffoldFile[] = drafts.map((node) => {
    const deps = graph.edges
      .filter((e) => e.source === node.id)
      .map((e) => nodeById(graph.nodes, e.target))
      .filter((n): n is ArchNode => Boolean(n));
    return { nodeId: node.id, path: node.data.filePath, content: templateFor(node, deps) };
  });

  // Existing files only change when a new edge makes them depend on something.
  const diffsBySource = new Map<string, DiffItem>();
  for (const edge of draftEdges) {
    const source = nodeById(graph.nodes, edge.source);
    const target = nodeById(graph.nodes, edge.target);
    if (!source || !target || source.data.isDraft) continue;
    const existing = diffsBySource.get(source.id);
    const base = existing ? { ...source, data: { ...source.data, code: existing.after } } : source;
    const diff = wireIntoExisting(base, target);
    diffsBySource.set(source.id, {
      ...diff,
      before: source.data.code,
      rationale: existing ? `${existing.rationale} ${diff.rationale}` : diff.rationale,
    });
  }

  return {
    files,
    diffs: [...diffsBySource.values()],
    summary: `Generated ${files.length} new file(s) and ${diffsBySource.size} wiring edit(s) from templates.`,
    engine: "local",
  };
}

import JSZip from "jszip";
import type { SourceFile } from "@/lib/types";
import { isAnalyzableSource } from "@/lib/engines/heuristicGraph";

export const MAX_ARCHIVE_BYTES = 50 * 1024 * 1024;
const MAX_SOURCE_FILE_BYTES = 200 * 1024;

/**
 * Extract analyzable source files from a ZIP. GitHub archives wrap everything
 * in a single `<repo>-<sha>/` folder, which is stripped.
 */
export async function extractSourceFiles(data: ArrayBuffer | Uint8Array): Promise<{ files: SourceFile[]; skipped: number }> {
  if (data.byteLength > MAX_ARCHIVE_BYTES) {
    throw new Error(`Archive is ${(data.byteLength / 1e6).toFixed(1)} MB; the limit is ${MAX_ARCHIVE_BYTES / 1e6} MB.`);
  }
  const zip = await JSZip.loadAsync(data);
  const entries = Object.values(zip.files).filter((entry) => !entry.dir);

  const roots = new Set(entries.map((e) => e.name.split("/")[0]));
  const stripPrefix = roots.size === 1 && entries.every((e) => e.name.includes("/"));

  const files: SourceFile[] = [];
  let skipped = 0;
  for (const entry of entries) {
    const path = stripPrefix ? entry.name.slice(entry.name.indexOf("/") + 1) : entry.name;
    if (path.includes("..") || !isAnalyzableSource(path)) continue;
    const content = await entry.async("string");
    if (content.length > MAX_SOURCE_FILE_BYTES) {
      skipped++;
      continue;
    }
    files.push({ path, content });
  }
  return { files, skipped };
}

import * as z from "zod/v4";
import { RulesSchema } from "@/lib/rulesSchema";

/** Shape of an architecture graph; shared by API validation and client-side JSON import. */

const MAX_NODES = 200;
const MAX_EDGES = 1_000;
const MAX_CODE_CHARS = 60_000;

const id = z.string().min(1).max(200);
const shortText = z.string().max(500);

const NodeDataSchema = z.object({
  label: shortText,
  kind: z.enum(["frontend", "api", "logic", "data"]),
  filePath: shortText,
  description: z.string().max(2_000),
  language: z.string().max(20),
  code: z.string().max(MAX_CODE_CHARS),
  exports: z.array(shortText).max(100),
  imports: z.array(shortText).max(200),
  params: z.array(z.object({ name: shortText, type: shortText, description: shortText.optional() })).max(50),
  keywords: z.array(z.string().max(60)).max(50),
  isDraft: z.boolean().optional(),
  lineCount: z.number().int().nonnegative().optional(),
});

const NodeSchema = z.object({
  id,
  type: z.literal("component"),
  position: z.object({ x: z.number(), y: z.number() }),
  data: NodeDataSchema,
});

const EdgeSchema = z.object({
  id,
  source: id,
  target: id,
  relation: z.enum(["calls", "reads", "writes", "imports", "publishes"]),
  label: shortText.optional(),
  isDraft: z.boolean().optional(),
  typeOnly: z.boolean().optional(),
  samePackage: z.boolean().optional(),
  symbols: z.array(z.string()).optional(),
});

const CommitSchema = z.object({
  hash: z.string().max(40),
  message: z.string().max(1_000),
  author: shortText,
  date: shortText,
  phase: shortText,
  narrative: z.string().max(4_000),
  addedNodeIds: z.array(id).max(MAX_NODES),
  modifiedNodeIds: z.array(id).max(MAX_NODES),
});

const ScenarioSchema = z.object({
  id,
  title: shortText,
  triggers: z.array(z.string().max(200)).max(20),
  rootNodeId: id,
  summary: z.string().max(4_000),
  extraImpacts: z.array(z.object({ nodeId: id, reason: shortText })).max(MAX_NODES),
  diffs: z.array(z.object({ nodeId: id, after: z.string().max(MAX_CODE_CHARS), rationale: shortText })).max(MAX_NODES),
});

const MAX_DRIFT_POINTS = 200;

const DriftPointSchema = z.object({
  hash: z.string().max(64),
  message: z.string().max(500),
  author: z.string().max(200),
  date: z.string().max(40),
  components: z.number().int().min(0),
  dependencies: z.number().int().min(0),
  score: z.number().min(0).max(100),
  grade: z.string().max(2),
  cycles: z.number().int().min(0),
  violations: z.number().int().min(0),
});

export const GraphSchema = z.object({
  id,
  name: shortText,
  description: z.string().max(2_000),
  nodes: z.array(NodeSchema).max(MAX_NODES),
  edges: z.array(EdgeSchema).max(MAX_EDGES),
  commits: z.array(CommitSchema).max(500),
  scenarios: z.array(ScenarioSchema).max(50),
  rules: RulesSchema.optional(),
  kindLabels: z.record(z.enum(["frontend", "api", "logic", "data"]), z.string().max(60)).optional(),
  warnings: z.array(z.string()).optional(),
  drift: z.array(DriftPointSchema).max(MAX_DRIFT_POINTS).optional(),
});

import { nodeById } from "@/lib/graph";
import type { ArchitectureGraph, ArchNode, DependencyEdge, HealthLevel, NodeKind } from "@/lib/types";

/* ---------- Tunables (named so the scoring is explainable and testable) ---------- */

/** A component is a "hub" when at least this many others depend on it, and at least HUB_MIN_SHARE of the graph. */
export const HUB_MIN_FAN_IN = 4;
export const HUB_MIN_SHARE = 0.25;
export const LARGE_FILE_LINES = 400;
export const HUGE_FILE_LINES = 800;

const SCORE_PER_DEPENDENT = 8;
const SCORE_DEPENDENT_CAP = 40;
const SCORE_IN_CYCLE = 30;
const SCORE_PER_LINES_UNIT = 20; // one point per this many lines
const SCORE_SIZE_CAP = 20;
const SCORE_LAYERING = 15;
const SCORE_PER_DEPENDENCY = 3;
const SCORE_DEPENDENCY_CAP = 15;
const SCORE_MAX = 100;

const WATCH_FROM = 35;
const RISKY_FROM = 65;

/** Files nothing imports by design: framework entry points, scripts and config. */
const ENTRY_FILE = /(^|\/)(app\/(.*\/)?(layout|page|route|loading|error|not-found|template|default)\.[jt]sx?|(main|index|middleware|instrumentation)\.[jt]sx?|main\.go|(main|lib|build)\.rs|src\/bin\/[^/]+\.rs|[^/]*(Application|Main|App|Controller|Configuration|Config)\.java|[^/]*(Application|Main|App|Controller|Activity)\.kt|main\.kt|[^/]*_controller\.rb|config\/(application|routes|environment)\.rb|(Program|Startup)\.cs|[^/]*(Controller|Hub)\.cs|[^/]*\.(config|setup)\.[cm]?[jt]s)$/i;
const ENTRY_DIR = /(^|\/)(scripts?|bin|cli|cmd)\//i;

export function isLikelyEntryPoint(filePath: string): boolean {
  const path = filePath.split("\\").join("/");
  return ENTRY_FILE.test(path) || ENTRY_DIR.test(path);
}

export type HealthIssueKind = "cycle" | "hub" | "orphan" | "large" | "layering";
export type HealthSeverity = "high" | "medium" | "low";

export type HealthIssue = {
  id: string;
  kind: HealthIssueKind;
  severity: HealthSeverity;
  title: string;
  /** Plain-language explanation, safe to show to non-experts. */
  detail: string;
  nodeIds: string[];
};

export type NodeHealth = {
  nodeId: string;
  /** How many other components depend on this one (direct). */
  fanIn: number;
  /** How many components this one depends on (direct). */
  fanOut: number;
  lines: number;
  inCycle: boolean;
  isOrphan: boolean;
  /** 0 (calm) – 100 (fragile / expensive to change). */
  score: number;
  level: HealthLevel;
  reasons: string[];
};

export type HealthGrade = "A" | "B" | "C" | "D" | "F";

export type HealthReport = {
  nodes: Record<string, NodeHealth>;
  issues: HealthIssue[];
  /** Edge IDs that sit inside a circular dependency. */
  cycleEdgeIds: string[];
  /** 0–100 for the whole graph; higher is healthier. */
  overall: number;
  grade: HealthGrade;
  counts: { cycles: number; hubs: number; orphans: number; large: number; layering: number };
};

const SEVERITY_ORDER: Record<HealthSeverity, number> = { high: 0, medium: 1, low: 2 };

function plural(n: number, one: string, many = `${one}s`): string {
  return `${n} ${n === 1 ? one : many}`;
}

function joinNames(names: string[], max = 3): string {
  if (names.length <= max) return names.join(", ");
  return `${names.slice(0, max).join(", ")} and ${names.length - max} more`;
}

function lineCountOf(node: ArchNode): number {
  return node.data.lineCount ?? (node.data.code ? node.data.code.split("\n").length : 0);
}

/**
 * Strongly connected components (Tarjan, recursive: graphs here are capped at a few
 * hundred nodes). A component with more than one node, or a self-loop, is a cycle.
 */
export function findCycles(nodeIds: readonly string[], edges: readonly DependencyEdge[]): string[][] {
  const known = new Set(nodeIds);
  const out = new Map<string, string[]>();
  for (const e of edges) {
    if (!known.has(e.source) || !known.has(e.target)) continue;
    const list = out.get(e.source) ?? [];
    list.push(e.target);
    out.set(e.source, list);
  }

  const index = new Map<string, number>();
  const low = new Map<string, number>();
  const onStack = new Set<string>();
  const stack: string[] = [];
  const cycles: string[][] = [];
  let counter = 0;

  const visit = (v: string): void => {
    index.set(v, counter);
    low.set(v, counter);
    counter++;
    stack.push(v);
    onStack.add(v);
    for (const w of out.get(v) ?? []) {
      if (!index.has(w)) {
        visit(w);
        low.set(v, Math.min(low.get(v)!, low.get(w)!));
      } else if (onStack.has(w)) {
        low.set(v, Math.min(low.get(v)!, index.get(w)!));
      }
    }
    if (low.get(v) === index.get(v)) {
      const group: string[] = [];
      let w: string;
      do {
        w = stack.pop()!;
        onStack.delete(w);
        group.push(w);
      } while (w !== v);
      const selfLoop = group.length === 1 && (out.get(v) ?? []).includes(v);
      if (group.length > 1 || selfLoop) cycles.push(group.reverse());
    }
  };

  for (const id of nodeIds) if (!index.has(id)) visit(id);
  return cycles;
}

/** UI talking straight to the database, or the database depending on the UI/API above it. */
function layeringProblem(source: NodeKind, target: NodeKind): string | null {
  if (source === "frontend" && target === "data") return "talks directly to the data layer, skipping the API/logic in between";
  if (source === "data" && (target === "frontend" || target === "api")) return "depends on a layer above it (data should not call UI or API code)";
  return null;
}

function levelFor(score: number): HealthLevel {
  return score >= RISKY_FROM ? "risky" : score >= WATCH_FROM ? "watch" : "healthy";
}

function gradeFor(overall: number): HealthGrade {
  if (overall >= 85) return "A";
  if (overall >= 70) return "B";
  if (overall >= 55) return "C";
  if (overall >= 40) return "D";
  return "F";
}

/**
 * Structural health of an architecture graph. Pure and deterministic; draft nodes and
 * edges from the builder are ignored because they are not part of the codebase yet.
 */
export function analyzeHealth(graph: ArchitectureGraph): HealthReport {
  const nodes = graph.nodes.filter((n) => !n.data.isDraft);
  const ids = new Set(nodes.map((n) => n.id));
  const allEdges = graph.edges.filter((e) => !e.isDraft && ids.has(e.source) && ids.has(e.target) && e.source !== e.target);
  // Type-only imports are erased at runtime: they do not make a hub, a cycle or a crossed layer.
  const edges = allEdges.filter((e) => !e.typeOnly);
  // Files in one Go package or Java package use each other freely, so a loop between them is not a cycle worth
  // reporting; their links still count for fan-in, hubs and risk.
  const cycleEdges = edges.filter((e) => !e.samePackage);
  const connected = new Set(allEdges.flatMap((e) => [e.source, e.target]));
  const label = (id: string) => nodeById(graph.nodes, id)?.data.label ?? id;

  const dependents = new Map<string, Set<string>>();
  const dependencies = new Map<string, Set<string>>();
  for (const e of edges) {
    (dependents.get(e.target) ?? dependents.set(e.target, new Set()).get(e.target)!).add(e.source);
    (dependencies.get(e.source) ?? dependencies.set(e.source, new Set()).get(e.source)!).add(e.target);
  }

  const cycles = findCycles([...ids], cycleEdges);
  const inCycle = new Set(cycles.flat());
  const cycleOf = new Map<string, number>();
  cycles.forEach((group, i) => group.forEach((id) => cycleOf.set(id, i)));
  const cycleEdgeIds = cycleEdges.filter((e) => cycleOf.has(e.source) && cycleOf.get(e.source) === cycleOf.get(e.target)).map((e) => e.id);

  const issues: HealthIssue[] = [];
  const layeringNodes = new Set<string>();
  const counts = { cycles: cycles.length, hubs: 0, orphans: 0, large: 0, layering: 0 };

  cycles.forEach((group, i) => {
    issues.push({
      id: `cycle-${i}`,
      kind: "cycle",
      severity: "high",
      title: `Circular dependency (${group.length} ${group.length === 1 ? "component" : "components"})`,
      detail: `${joinNames(group.map(label), 4)} depend on each other in a loop. Changing any of them can ripple back to itself, and they cannot be understood or tested separately.`,
      nodeIds: group,
    });
  });

  for (const e of edges) {
    const problem = layeringProblem(nodeById(nodes, e.source)!.data.kind, nodeById(nodes, e.target)!.data.kind);
    if (!problem) continue;
    counts.layering++;
    layeringNodes.add(e.source);
    layeringNodes.add(e.target);
    issues.push({
      id: `layering-${e.id}`,
      kind: "layering",
      severity: "medium",
      title: "Layers are crossed",
      detail: `${label(e.source)} ${problem} (${label(e.target)}).`,
      nodeIds: [e.source, e.target],
    });
  }

  const report: Record<string, NodeHealth> = {};
  for (const node of nodes) {
    const fanIn = dependents.get(node.id)?.size ?? 0;
    const fanOut = dependencies.get(node.id)?.size ?? 0;
    const lines = lineCountOf(node);
    const isOrphan = !connected.has(node.id) && !isLikelyEntryPoint(node.data.filePath);
    const cyc = inCycle.has(node.id);
    const reasons: string[] = [];

    let score = Math.min(SCORE_DEPENDENT_CAP, fanIn * SCORE_PER_DEPENDENT) + Math.min(SCORE_DEPENDENCY_CAP, fanOut * SCORE_PER_DEPENDENCY);
    score += Math.min(SCORE_SIZE_CAP, Math.floor(lines / SCORE_PER_LINES_UNIT));
    if (cyc) score += SCORE_IN_CYCLE;
    if (layeringNodes.has(node.id)) score += SCORE_LAYERING;
    score = Math.min(SCORE_MAX, score);

    if (fanIn > 0) reasons.push(`${plural(fanIn, "component")} depend${fanIn === 1 ? "s" : ""} on it`);
    if (cyc) reasons.push("part of a circular dependency");
    if (layeringNodes.has(node.id)) reasons.push("involved in a crossed layer");
    if (lines >= LARGE_FILE_LINES) reasons.push(`large (${lines.toLocaleString()} lines)`);
    if (fanOut >= 6) reasons.push(`depends on ${fanOut} other components`);
    if (isOrphan) reasons.push("not connected to anything");

    report[node.id] = { nodeId: node.id, fanIn, fanOut, lines, inCycle: cyc, isOrphan, score, level: levelFor(score), reasons };

    const hub = fanIn >= HUB_MIN_FAN_IN && nodes.length > 1 && fanIn / (nodes.length - 1) >= HUB_MIN_SHARE;
    if (hub) {
      counts.hubs++;
      issues.push({
        id: `hub-${node.id}`,
        kind: "hub",
        severity: "medium",
        title: `${node.data.label} is a hub`,
        detail: `${plural(fanIn, "component")} depend on it (${joinNames([...dependents.get(node.id)!].map(label))}). A change here has a wide blast radius; keep its interface small and stable.`,
        nodeIds: [node.id],
      });
    }
    if (lines >= LARGE_FILE_LINES) {
      counts.large++;
      issues.push({
        id: `large-${node.id}`,
        kind: "large",
        severity: lines >= HUGE_FILE_LINES ? "medium" : "low",
        title: `${node.data.label} is large`,
        detail: `${lines.toLocaleString()} lines in one file. Big files hide several responsibilities; consider splitting it so each part can change on its own.`,
        nodeIds: [node.id],
      });
    }
    if (isOrphan && nodes.length > 1) {
      counts.orphans++;
      issues.push({
        id: `orphan-${node.id}`,
        kind: "orphan",
        severity: "low",
        title: `${node.data.label} is not connected`,
        detail: "Nothing uses it and it uses nothing in this map. It may be dead code, an entry point the map cannot see, or a link the scanner missed.",
        nodeIds: [node.id],
      });
    }
  }

  issues.sort((a, b) => SEVERITY_ORDER[a.severity] - SEVERITY_ORDER[b.severity] || a.title.localeCompare(b.title));

  const penalty = counts.cycles * 12 + counts.layering * 8 + counts.hubs * 5 + counts.large * 4 + counts.orphans * 2;
  const overall = Math.max(0, SCORE_MAX - penalty);
  return { nodes: report, issues, cycleEdgeIds, overall, grade: gradeFor(overall), counts };
}

/** Stable identity of an issue across two analyses: cycles by their members, others by their (already stable) id. */
export function healthIssueKey(issue: HealthIssue): string {
  return issue.kind === "cycle" ? `cycle:${[...issue.nodeIds].sort().join(",")}` : issue.id;
}

/** The `limit` components most expensive to change, riskiest first. */
export function riskiestNodes(report: HealthReport, limit = 5): NodeHealth[] {
  return Object.values(report.nodes)
    .filter((n) => n.score > 0)
    .sort((a, b) => b.score - a.score || a.nodeId.localeCompare(b.nodeId))
    .slice(0, limit);
}

import type { ArchNode, CodeParam, DependencyEdge, NodeData, NodeKind, SourceFile } from "@/lib/types";

/**
 * Data-flow mapping for analysis scripts (MATLAB `.m`, Python `.py`): which script calls
 * which function, and which data files each one reads or writes. Pure and deterministic.
 *
 * Limits, by design: file names built at run time (`[name '_base.csv']`) cannot be
 * resolved. Literal fragments are kept and marked as patterns; nothing is executed.
 */

export type ScriptLang = "matlab" | "python";

export function scriptLangOf(path: string): ScriptLang | null {
  if (/\.m$/i.test(path)) return "matlab";
  if (/\.py$/i.test(path)) return "python";
  return null;
}

/* ---------- Lexing: strip comments, blank string contents, collect literals ---------- */

export type LexedLine = {
  /** The line with comments removed and string contents blanked (`'abc'` → `''`). */
  text: string;
  /** String literals on this line, unquoted. */
  literals: string[];
};

const MATLAB_TRANSPOSE_PRECEDERS = /[A-Za-z0-9_)\]}.']/;

/** Lex MATLAB or Python source line by line. Handles block comments, doubled quotes and the transpose operator. */
export function lexSource(code: string, lang: ScriptLang): LexedLine[] {
  const rawLines = code.replace(/\r\n/g, "\n").split("\n");
  const out: LexedLine[] = [];
  let inBlockComment = false;
  let tripleQuote: string | null = null; // Python only

  for (const raw of rawLines) {
    if (lang === "matlab") {
      const trimmed = raw.trim();
      if (inBlockComment) {
        if (trimmed === "%}") inBlockComment = false;
        out.push({ text: "", literals: [] });
        continue;
      }
      if (trimmed === "%{") {
        inBlockComment = true;
        out.push({ text: "", literals: [] });
        continue;
      }
    }

    let text = "";
    const literals: string[] = [];
    let i = 0;

    if (tripleQuote) {
      const end = raw.indexOf(tripleQuote);
      if (end === -1) {
        out.push({ text: "", literals: [] });
        continue;
      }
      i = end + 3;
      tripleQuote = null;
    }

    while (i < raw.length) {
      const ch = raw[i]!;
      const commentStart = lang === "matlab" ? ch === "%" || raw.startsWith("...", i) : ch === "#";
      if (commentStart) break;

      const isQuote = ch === '"' || ch === "'";
      if (lang === "python" && isQuote && raw.startsWith(ch.repeat(3), i)) {
        const end = raw.indexOf(ch.repeat(3), i + 3);
        if (end === -1) {
          tripleQuote = ch.repeat(3);
          break;
        }
        text += `${ch}${ch}`;
        i = end + 3;
        continue;
      }

      const isTranspose = lang === "matlab" && ch === "'" && i > 0 && MATLAB_TRANSPOSE_PRECEDERS.test(raw[i - 1]!);
      if (isQuote && !isTranspose) {
        let j = i + 1;
        let value = "";
        for (; j < raw.length; j++) {
          const c = raw[j]!;
          if (lang === "python" && c === "\\") {
            value += raw[j + 1] ?? "";
            j++;
          } else if (c === ch) {
            if (lang === "matlab" && raw[j + 1] === ch) {
              value += ch; // doubled quote is an escaped quote in MATLAB
              j++;
            } else break;
          } else value += c;
        }
        literals.push(value);
        text += `${ch}${ch}`;
        i = j + 1;
        continue;
      }
      text += ch;
      i++;
    }
    out.push({ text, literals });
  }
  return out;
}

/* ---------- Data-file references ---------- */

const DATA_EXTENSIONS = new Set(["csv", "tsv", "mat", "xlsx", "xls", "xlsm", "txt", "dat", "json", "h5", "hdf5", "parquet", "pkl", "pickle", "npy", "npz", "xml", "psout", "nc", "feather"]);
const OUTPUT_EXTENSIONS = new Set(["png", "jpg", "jpeg", "pdf", "svg", "eps", "fig", "gif", "tif", "tiff", "emf"]);

const MATLAB_WRITE = /\b(writetable|writematrix|writecell|writetimetable|csvwrite|dlmwrite|xlswrite|save|saveas|savefig|exportgraphics|exportapp|print|imwrite|audiowrite|h5create|h5write|diary)\b/;
const PYTHON_WRITE = /\b(to_csv|to_excel|to_parquet|to_json|to_pickle|to_hdf|to_feather|savetxt|save|savez|savez_compressed|savefig|dump|dumps|write_text|write_bytes|imwrite|imsave)\b/;
const READ_CALL = /\b(read\w*|load\w*|imread|fileread|importdata|textscan|xlsread|csvread|dlmread|matfile|open)\b/;
const WRITE_MODE_LITERAL = /^(w|a|wt|at|wb|ab|w\+|a\+|wt\+|at\+)$/;

export type DataRef = { path: string; mode: "reads" | "writes"; isPattern: boolean };

function extensionOf(path: string): string {
  return /\.([A-Za-z0-9]{2,8})$/.exec(path)?.[1]?.toLowerCase() ?? "";
}

/** File names assembled at run time show up as fragments such as `_base.csv`, `%s.csv` or `*.csv`. */
function isPatternPath(path: string): boolean {
  const base = path.split(/[\\/]/).pop() ?? path;
  return /[%*?{}]/.test(base) || /^[_.\-+]/.test(base) || base.startsWith("$");
}

export function normalizeDataPath(path: string): string {
  return path.replace(/\\/g, "/").replace(/^\.\//, "").trim();
}

/** Every string literal that names a data or output file, classified as a read or a write from its line. */
export function scanDataRefs(lines: readonly LexedLine[], lang: ScriptLang): DataRef[] {
  const writeCall = lang === "matlab" ? MATLAB_WRITE : PYTHON_WRITE;
  const refs = new Map<string, DataRef>();

  for (const { text, literals } of lines) {
    if (literals.length === 0) continue;
    const opensForWriting = /\b(fopen|open)\b/.test(text) && literals.some((l) => WRITE_MODE_LITERAL.test(l));
    for (const literal of literals) {
      const ext = extensionOf(literal);
      const isData = DATA_EXTENSIONS.has(ext);
      const isOutput = OUTPUT_EXTENSIONS.has(ext);
      if (!isData && !isOutput) continue;
      if (/^(https?:|[a-z]+:\/\/)/i.test(literal)) continue; // URLs are not local files

      let mode: DataRef["mode"] = "reads";
      if (opensForWriting || writeCall.test(text)) mode = "writes";
      else if (isOutput && !READ_CALL.test(text)) mode = "writes";

      const path = normalizeDataPath(literal);
      const previous = refs.get(path);
      // A file both read and written is reported as written: the stronger claim for impact analysis.
      if (!previous || (previous.mode === "reads" && mode === "writes")) refs.set(path, { path, mode, isPattern: isPatternPath(path) });
    }
  }
  return [...refs.values()];
}

/* ---------- MATLAB structure ---------- */

const FUNCTION_DEF = /^\s*function\b\s*(?:\[[^\]]*\]\s*=\s*|[A-Za-z_]\w*\s*=\s*)?([A-Za-z_][\w.]*)\s*(?:\(([^)]*)\))?/;

export type MatlabStructure = {
  /** Names of every function defined in the file; the first is the main one for a function file. */
  functions: string[];
  /** True when the file starts with a function (callable by its file name) rather than top-level statements. */
  isFunctionFile: boolean;
  params: CodeParam[];
};

export function matlabStructure(lines: readonly LexedLine[]): MatlabStructure {
  const functions: string[] = [];
  let params: CodeParam[] = [];
  let firstStatementIsFunction: boolean | null = null;

  for (const { text } of lines) {
    const match = FUNCTION_DEF.exec(text);
    if (firstStatementIsFunction === null && text.trim() !== "") firstStatementIsFunction = Boolean(match) || /^\s*classdef\b/.test(text);
    if (!match) continue;
    if (functions.length === 0) {
      params = (match[2] ?? "")
        .split(",")
        .map((p) => p.trim())
        .filter((p) => p && p !== "varargin" && p !== "~")
        .map((name) => ({ name, type: "any" }));
    }
    functions.push(match[1]!);
  }
  return { functions, isFunctionFile: Boolean(firstStatementIsFunction), params };
}

/** Function names defined in a MATLAB file, for the export list. */
export function matlabFunctions(code: string): string[] {
  return matlabStructure(lexSource(code, "matlab")).functions;
}

const MATLAB_PLOT_CALLS = ["plot", "plot3", "figure", "subplot", "tiledlayout", "nexttile", "bar", "histogram", "scatter", "surf", "contour", "heatmap", "legend", "xlabel", "ylabel", "exportgraphics", "saveas", "axes"];
const PYTHON_PLOT_HINT = /\b(plt|matplotlib|seaborn|plotly|bokeh)\b|\.plot\(|\bsavefig\b/;
const PLOT_CALL_THRESHOLD = 2;

function isPlotting(lines: readonly LexedLine[], lang: ScriptLang): boolean {
  if (lang === "python") return lines.some((l) => PYTHON_PLOT_HINT.test(l.text));
  const seen = new Set<string>();
  const pattern = new RegExp(`(?<![\\w.])(${MATLAB_PLOT_CALLS.join("|")})\\s*\\(`, "g");
  for (const { text } of lines) for (const m of text.matchAll(pattern)) seen.add(m[1]!);
  return seen.size >= PLOT_CALL_THRESHOLD;
}

/** First comment block of a script, which people write as its description. */
export function headerComment(code: string, lang: ScriptLang): string | undefined {
  const marker = lang === "matlab" ? "%" : "#";
  const collected: string[] = [];
  for (const raw of code.replace(/\r\n/g, "\n").split("\n")) {
    const line = raw.trim();
    if (line === "") {
      if (collected.length) break;
      continue;
    }
    if (line.startsWith(marker)) {
      const text = line.replace(new RegExp(`^\\${marker}+\\s*`), "").trim();
      if (text && !/^(-{3,}|={3,}|\*{3,})$/.test(text)) collected.push(text);
      if (collected.join(" ").length > 200) break;
      continue;
    }
    if (lang === "matlab" && /^function\b/.test(line) && collected.length === 0) continue; // doc comment follows the signature
    if (lang === "python" && /^(#!|import|from)\b/.test(line) && collected.length === 0) continue;
    break;
  }
  const joined = collected.join(" ").replace(/\s+/g, " ").trim();
  return joined ? (joined.length > 220 ? `${joined.slice(0, 217)}…` : joined) : undefined;
}

/* ---------- The graph layer ---------- */

export const MAX_DATA_NODES = 40;
const SCRIPT_DOMINANT_SHARE = 0.5;

export const SCRIPT_KIND_LABELS: Partial<Record<NodeKind, string>> = {
  frontend: "Plots & outputs",
  api: "Entry scripts",
  logic: "Analysis code",
  data: "Data files",
};

export type ScriptLayer = {
  /** Changes to apply to existing file nodes, keyed by file path. */
  patches: Map<string, Partial<NodeData>>;
  dataNodes: ArchNode[];
  edges: DependencyEdge[];
  kindLabels?: Partial<Record<NodeKind, string>>;
  warnings: string[];
};

function slug(text: string): string {
  return text.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

export function dataNodeId(path: string): string {
  return `data-${slug(normalizeDataPath(path))}`;
}

function basename(path: string): string {
  return path.split("/").pop() ?? path;
}

function keywordsFor(path: string, extra: string[] = []): string[] {
  return [...new Set([...slug(basename(path).replace(/\.[^.]+$/, "")).split("-"), ...extra].filter((k) => k.length >= 2))];
}

export function analyzeScriptFiles(files: readonly SourceFile[], idForPath: ReadonlyMap<string, string>): ScriptLayer {
  const scripts = files.filter((f) => scriptLangOf(f.path));
  const layer: ScriptLayer = { patches: new Map(), dataNodes: [], edges: [], warnings: [] };
  if (scripts.length === 0) return layer;

  const lexed = new Map(scripts.map((f) => [f.path, lexSource(f.content, scriptLangOf(f.path)!)]));

  /* MATLAB: who calls whom (by file name; local functions shadow other files) */
  const matlabFiles = scripts.filter((f) => scriptLangOf(f.path) === "matlab");
  const structure = new Map(matlabFiles.map((f) => [f.path, matlabStructure(lexed.get(f.path)!)]));
  const pathByName = new Map(matlabFiles.map((f) => [basename(f.path).replace(/\.m$/i, ""), f.path]));
  const callsByPath = new Map<string, Set<string>>();
  if (pathByName.size > 0) {
    const names = [...pathByName.keys()].filter((n) => /^[A-Za-z_]\w*$/.test(n));
    const callPattern = names.length ? new RegExp(`(?<![\\w.])(${names.join("|")})(?![\\w])`, "g") : null;
    for (const f of matlabFiles) {
      const own = new Set(structure.get(f.path)!.functions);
      const called = new Set<string>();
      for (const { text } of lexed.get(f.path)!) {
        if (!callPattern || FUNCTION_DEF.test(text)) continue;
        for (const m of text.matchAll(callPattern)) {
          const target = pathByName.get(m[1]!);
          if (target && target !== f.path && !own.has(m[1]!)) called.add(m[1]!);
        }
      }
      callsByPath.set(f.path, called);
    }
  }

  const seenEdges = new Set<string>();
  const addEdge = (edge: DependencyEdge) => {
    const key = `${edge.source}->${edge.target}`;
    if (seenEdges.has(key)) return;
    seenEdges.add(key);
    layer.edges.push(edge);
  };

  const callerCount = new Map<string, number>();
  for (const [path, names] of callsByPath) {
    for (const name of names) {
      const targetPath = pathByName.get(name)!;
      callerCount.set(targetPath, (callerCount.get(targetPath) ?? 0) + 1);
      const source = idForPath.get(path)!;
      const target = idForPath.get(targetPath)!;
      addEdge({ id: `e-${source}--${target}`, source, target, relation: "calls", label: `${name}()` });
    }
  }

  /* Data files, for both languages */
  const refsByScript = new Map(scripts.map((f) => [f.path, scanDataRefs(lexed.get(f.path)!, scriptLangOf(f.path)!)]));
  const usage = new Map<string, { ref: DataRef; scripts: Set<string> }>();
  for (const [scriptPath, refs] of refsByScript) {
    for (const ref of refs) {
      const entry = usage.get(ref.path) ?? { ref, scripts: new Set<string>() };
      if (ref.mode === "writes") entry.ref = { ...entry.ref, mode: "writes" };
      entry.scripts.add(scriptPath);
      usage.set(ref.path, entry);
    }
  }

  const ranked = [...usage.values()].sort((a, b) => b.scripts.size - a.scripts.size || a.ref.path.localeCompare(b.ref.path));
  const shown = ranked.slice(0, MAX_DATA_NODES);
  const overflow = ranked.slice(MAX_DATA_NODES);

  const makeDataNode = (id: string, path: string, label: string, description: string, code: string, ext: string, keywords: string[]): ArchNode => ({
    id,
    type: "component",
    position: { x: 0, y: 0 },
    data: { label, kind: "data", filePath: path, description, language: ext || "data", code, exports: [], imports: [], params: [], keywords },
  });
  const labelFor = (names: Iterable<string>) => [...names].map((p) => basename(p)).join(", ");

  for (const { ref, scripts: users } of shown) {
    const id = dataNodeId(ref.path);
    const verb = ref.mode === "writes" ? "written" : "read";
    layer.dataNodes.push(
      makeDataNode(
        id,
        ref.path,
        basename(ref.path),
        `${ref.isPattern ? "File name pattern (built at run time)" : ref.mode === "writes" ? "Output file" : "Input data file"}, ${verb} by ${labelFor(users)}.`,
        `// ${ref.path}\n// ${verb} by: ${[...users].join(", ")}\n// File contents are not loaded; this node comes from references in the code.`,
        extensionOf(ref.path),
        keywordsFor(ref.path, ["data", "file", extensionOf(ref.path)]),
      ),
    );
    for (const scriptPath of users) {
      const source = idForPath.get(scriptPath)!;
      const mode = refsByScript.get(scriptPath)!.find((r) => r.path === ref.path)?.mode ?? "reads";
      addEdge({ id: `e-${source}--${id}`, source, target: id, relation: mode, label: mode === "writes" ? "writes" : undefined });
    }
  }
  if (overflow.length > 0) {
    const id = "data-more-files";
    const usersOfOverflow = new Set(overflow.flatMap((o) => [...o.scripts]));
    layer.dataNodes.push(
      makeDataNode(
        id,
        `(${overflow.length} more data files)`,
        `+${overflow.length} more data files`,
        `Further data files referenced by ${labelFor(usersOfOverflow)}: ${overflow.slice(0, 8).map((o) => basename(o.ref.path)).join(", ")}…`,
        overflow.map((o) => `// ${o.ref.path}`).join("\n"),
        "data",
        ["data", "files", "more"],
      ),
    );
    for (const scriptPath of usersOfOverflow) {
      const source = idForPath.get(scriptPath)!;
      addEdge({ id: `e-${source}--${id}`, source, target: id, relation: "reads" });
    }
    layer.warnings.push(`Showing the ${MAX_DATA_NODES} most-used data files; ${overflow.length} more are grouped into one node.`);
  }
  if (usage.size > 0) layer.warnings.push("Data files are shown from references in the code; their contents are never read. File names built at run time appear as patterns.");
  if ([...usage.values()].some((u) => u.ref.isPattern)) layer.warnings.push("Some names are fragments (e.g. '_base.csv'), so the real file set may be larger.");

  /* Per-file node patches: description, exports, imports, layer */
  for (const f of scripts) {
    const lang = scriptLangOf(f.path)!;
    const lines = lexed.get(f.path)!;
    const patch: Partial<NodeData> = {};
    const header = headerComment(f.content, lang);
    const calls = [...(callsByPath.get(f.path) ?? [])];
    const reads = (refsByScript.get(f.path) ?? []).filter((r) => r.mode === "reads").map((r) => basename(r.path));
    const writes = (refsByScript.get(f.path) ?? []).filter((r) => r.mode === "writes").map((r) => basename(r.path));

    let isScript = false;
    if (lang === "matlab") {
      const s = structure.get(f.path)!;
      isScript = !s.isFunctionFile;
      patch.language = "matlab";
      patch.exports = s.functions;
      patch.imports = [...calls.map((c) => `${c}()`), ...reads];
      if (s.params.length) patch.params = s.params;
    } else {
      isScript = /^\s*if\s+__name__\s*==\s*['"]__main__['"]/m.test(f.content);
      patch.imports = undefined; // keep the import list from the generic scan
    }
    if (header) patch.description = header;
    else if (reads.length || writes.length || calls.length) {
      const bits = [calls.length && `calls ${calls.slice(0, 3).join(", ")}`, reads.length && `reads ${reads.length} data file(s)`, writes.length && `writes ${writes.slice(0, 2).join(", ")}`].filter(Boolean);
      patch.description = `${isScript ? "Script" : "Function"} that ${bits.join(", ")}.`;
    }

    const hasCallers = (callerCount.get(f.path) ?? 0) > 0;
    const isEntry = isScript && !hasCallers && (calls.length > 0 || reads.length + writes.length > 0);
    if (isEntry) patch.kind = "api";
    else if (isPlotting(lines, lang)) patch.kind = "frontend";
    for (const key of Object.keys(patch) as Array<keyof NodeData>) if (patch[key] === undefined) delete patch[key];
    layer.patches.set(f.path, patch);
  }

  if (scripts.length / Math.max(1, files.length) >= SCRIPT_DOMINANT_SHARE) layer.kindLabels = SCRIPT_KIND_LABELS;
  return layer;
}

import { diffLines } from "@/lib/diff";
import { collectDependents, nodeById } from "@/lib/graph";
import type { ArchitectureGraph, ImpactAnalysisResult, NodeKind } from "@/lib/types";

/** Everything here is deterministic text built from the graph; no AI is involved. */

export const GLOSSARY: ReadonlyArray<{ term: string; meaning: string }> = [
  { term: "Component", meaning: "One part of the codebase: a file or a group of files with a single job (a page, an API route, a service, a data store)." },
  { term: "Dependency", meaning: "An arrow from A to B means A uses B. If B changes, A may stop working." },
  { term: "Blast radius", meaning: "Everything a change could affect, directly or through other components." },
  { term: "Broken (red)", meaning: "Will fail or misbehave unless it is edited for the change." },
  { term: "Impacted (amber)", meaning: "Depends on something that changes. Review it; it may need no edit at all." },
  { term: "Origin (blue)", meaning: "Where the change starts." },
  { term: "Hop", meaning: "One step along the arrows. A component 2 hops away is affected indirectly, through another component." },
  { term: "Change-risk", meaning: "0–100 score of how costly and fragile a component is to change: many dependents, tangled links, big files." },
  { term: "Circular dependency", meaning: "A uses B and B uses A (possibly through others). Such a loop is hard to change or test in isolation." },
  { term: "Hub", meaning: "A component many others depend on. A change to it has a wide blast radius." },
];

const KIND_PHRASE: Record<NodeKind, string> = {
  frontend: "a user-facing part (a screen, page or output)",
  api: "an entry point that receives requests",
  logic: "business logic that does the actual work",
  data: "a place that stores or caches information",
};

/** "Wide" means a change can reach at least this many components and this share of the graph. */
const WIDE_MIN_COMPONENTS = 3;
const WIDE_MIN_SHARE = 0.5;

export type PlainExplanation = { headline: string; bullets: string[] };

function listNames(names: string[], max = 4): string {
  if (names.length <= max) return names.join(", ");
  return `${names.slice(0, max).join(", ")} and ${names.length - max} more`;
}

function plural(n: number, one: string, many = `${one}s`): string {
  return `${n} ${n === 1 ? one : many}`;
}

/** "What is this component, and how much would changing it touch?" in everyday words. */
export function explainNode(graph: ArchitectureGraph, nodeId: string): PlainExplanation | null {
  const node = nodeById(graph.nodes, nodeId);
  if (!node) return null;
  const label = (id: string) => nodeById(graph.nodes, id)?.data.label ?? id;
  const real = graph.edges.filter((e) => !e.isDraft);

  // A `writes` edge means "produces", not "uses": a script that writes a file does not rely on it.
  const direct = [...new Set(real.filter((e) => e.target === nodeId && e.relation !== "writes").map((e) => e.source))];
  const writers = [...new Set(real.filter((e) => e.target === nodeId && e.relation === "writes").map((e) => e.source))];
  const uses = [...new Set(real.filter((e) => e.source === nodeId && e.relation !== "writes").map((e) => e.target))];
  const produces = [...new Set(real.filter((e) => e.source === nodeId && e.relation === "writes").map((e) => e.target))];
  const reach = collectDependents(nodeId, real);
  const indirect = reach.size - 1;
  const customLayer = graph.kindLabels?.[node.data.kind];

  const bullets: string[] = [];
  bullets.push(
    direct.length === 0
      ? "Nothing else in this map uses it."
      : `${plural(direct.length, "component")} use${direct.length === 1 ? "s" : ""} it directly: ${listNames(direct.map(label))}.`,
  );
  bullets.push(uses.length === 0 ? "It does not rely on anything else." : `It relies on ${listNames(uses.map(label))}.`);

  const total = Math.max(1, graph.nodes.length - 1);
  if (indirect === 0) {
    bullets.push("Changing it affects only itself, so it is safe to change on its own.");
  } else if (indirect >= WIDE_MIN_COMPONENTS && indirect / total >= WIDE_MIN_SHARE) {
    bullets.push(`A change here can ripple to ${indirect} of the other ${total} components: a wide blast radius, so plan it carefully.`);
  } else {
    bullets.push(`A change here can ripple to ${plural(indirect, "other component")}${indirect > direct.length + writers.length ? ", some of them indirectly" : ""}.`);
  }

  if (writers.length) bullets.push(`It is written by ${listNames(writers.map(label))}.`);
  if (produces.length) bullets.push(`It writes ${listNames(produces.map(label))}.`);

  const kind = customLayer ? `part of “${customLayer}”` : KIND_PHRASE[node.data.kind];
  return { headline: `${node.data.label} is ${kind}.`, bullets };
}

export type Effort = "Small" | "Medium" | "Large";

export type ImpactExplanation = {
  headline: string;
  effort: Effort;
  effortWhy: string;
  /** Suggested order of work, one sentence per step. */
  order: string[];
};

const EFFORT_SMALL_LINES = 30;
const EFFORT_MEDIUM_LINES = 150;
const EFFORT_SMALL_BROKEN = 2;
const EFFORT_MEDIUM_BROKEN = 6;

/** A rough, explainable estimate of how much work a simulated change is, and in what order to do it. */
export function explainImpact(result: ImpactAnalysisResult, graph: ArchitectureGraph): ImpactExplanation {
  const label = (id: string) => nodeById(graph.nodes, id)?.data.label ?? id;
  const broken = result.impacts.filter((i) => i.severity === "broken");
  const review = result.impacts.filter((i) => i.severity === "impacted");

  let changed = 0;
  for (const d of result.diffs) {
    const { stats } = diffLines(d.before, d.after);
    changed += stats.added + stats.removed;
  }
  const hasEdits = result.diffs.length > 0;
  const effort: Effort =
    broken.length <= EFFORT_SMALL_BROKEN && (!hasEdits || changed <= EFFORT_SMALL_LINES)
      ? "Small"
      : broken.length <= EFFORT_MEDIUM_BROKEN && (!hasEdits || changed <= EFFORT_MEDIUM_LINES)
        ? "Medium"
        : "Large";

  const mustChange = `${plural(broken.length, "file")} must change`;
  const toReview = review.length ? ` and ${plural(review.length, "other component")} should be reviewed` : "";
  const effortWhy = hasEdits
    ? `${mustChange}${toReview}; the proposed edits touch about ${changed} lines.`
    : `${mustChange}${toReview}. This estimate comes from the dependency map alone: no code edits were proposed.`;

  const parts = [
    broken.length ? `edits in ${plural(broken.length, "file")}` : null,
    review.length ? `a review of ${plural(review.length, "more component")}` : null,
  ].filter(Boolean);
  const headline = `Changing ${label(result.rootNodeId)} would need ${parts.length ? parts.join(" and ") : "no other changes"}.`;

  // Origin first, then outward: fix what you changed before the things that consume it.
  const ordered = [...result.impacts].sort((a, b) => a.depth - b.depth);
  const order = ordered
    .filter((i) => i.severity !== "impacted")
    .map((i, step) => (i.severity === "modified" ? `${step + 1}. Make the change in ${label(i.nodeId)}.` : `${step + 1}. Update ${label(i.nodeId)}: ${i.reason.replace(/\.$/, "")}.`));
  if (review.length) order.push(`${order.length + 1}. Skim ${listNames(review.map((i) => label(i.nodeId)))}; ${review.length === 1 ? "it" : "they"} may need no edit.`);

  return { headline, effort, effortWhy, order };
}

import type { ArchNode } from "@/lib/types";

export type SearchField = "name" | "path" | "export" | "keyword" | "description";

export type SearchHit = {
  nodeId: string;
  score: number;
  /** The field the best match came from, for showing "why it matched". */
  matchedOn: SearchField;
};

const SCORE = { exactName: 100, namePrefix: 40, nameWord: 80, nameContains: 60, path: 40, export: 35, keyword: 30, description: 10 } as const;
const DEFAULT_LIMIT = 8;

/** "UserDashboard" → "user dashboard", so people can search by word. */
function words(text: string): string {
  return text.replace(/([a-z0-9])([A-Z])/g, "$1 $2").replace(/[_\-./\\]+/g, " ").toLowerCase();
}

type TokenMatch = { score: number; field: SearchField };

function matchToken(node: ArchNode, token: string): TokenMatch | null {
  const { label, filePath, exports, keywords, description } = node.data;
  const name = words(label);
  const best: TokenMatch[] = [];

  if (name.split(" ").some((w) => w.startsWith(token))) best.push({ score: SCORE.nameWord, field: "name" });
  else if (name.includes(token) || label.toLowerCase().includes(token)) best.push({ score: SCORE.nameContains, field: "name" });
  if (filePath.toLowerCase().includes(token) || words(filePath).includes(token)) best.push({ score: SCORE.path, field: "path" });
  if (exports.some((e) => e.toLowerCase().includes(token))) best.push({ score: SCORE.export, field: "export" });
  if (keywords.some((k) => k.toLowerCase().startsWith(token))) best.push({ score: SCORE.keyword, field: "keyword" });
  if (description.toLowerCase().includes(token)) best.push({ score: SCORE.description, field: "description" });

  return best.length ? best.reduce((a, b) => (b.score > a.score ? b : a)) : null;
}

/**
 * Find components by name, file path, exported symbol, keyword or description.
 * Every whitespace-separated word of the query must match something (AND), so
 * "auth jwt" finds the JWT service in the auth folder. Results are best-first.
 */
export function searchNodes(nodes: readonly ArchNode[], query: string, limit = DEFAULT_LIMIT): SearchHit[] {
  const tokens = query.toLowerCase().split(/\s+/).filter(Boolean);
  if (tokens.length === 0) return [];
  const whole = tokens.join(" ");

  const hits: SearchHit[] = [];
  for (const node of nodes) {
    let score = 0;
    let matchedOn: SearchField | null = null;
    let allMatched = true;
    for (const token of tokens) {
      const m = matchToken(node, token);
      if (!m) {
        allMatched = false;
        break;
      }
      score += m.score;
      matchedOn ??= m.field;
    }
    if (!allMatched || !matchedOn) continue;

    const name = node.data.label.toLowerCase();
    if (name === whole) score += SCORE.exactName;
    else if (name.startsWith(whole)) score += SCORE.namePrefix;
    hits.push({ nodeId: node.id, score, matchedOn });
  }

  const byId = new Map(nodes.map((n) => [n.id, n.data.label]));
  return hits.sort((a, b) => b.score - a.score || (byId.get(a.nodeId) ?? "").localeCompare(byId.get(b.nodeId) ?? "")).slice(0, limit);
}

import { nodeById } from "@/lib/graph";
import type { ArchitectureGraph, ArchNode, DependencyEdge } from "@/lib/types";

/**
 * Provenance: follow data flow through the map.
 *
 * Edges point from a thing to what it depends on (`reads`, `calls`, `imports`), except
 * `writes`, which points from a producer to what it produces. So:
 *
 * - **upstream** ("where does this come from?"): from a produced file, go to the code that
 *   writes it; from code, go to what it reads and calls; repeat. A file nothing writes is a raw input.
 * - **downstream** ("what does this affect?"): from a file or function, go to the code that
 *   reads or calls it, then to everything that code writes; repeat.
 */

export type TraceMode = "upstream" | "downstream";

export type TraceRequest = { nodeId: string; mode: TraceMode };

export type TraceRole = "target" | "input" | "produced" | "code";

export type TraceStep = { nodeId: string; depth: number; role: TraceRole };

export type Trace = TraceRequest & {
  nodeIds: string[];
  edgeIds: string[];
  /** Upstream: raw inputs first, the target last. Downstream: the source first, then what it reaches. */
  steps: TraceStep[];
  /** Upstream: data nodes that no code in the map writes. */
  rawInputs: string[];
  /** Downstream: data nodes (outputs) that would be affected. */
  results: string[];
};

const isData = (node: ArchNode) => node.data.kind === "data";

export function traceProvenance(graph: ArchitectureGraph, request: TraceRequest): Trace | null {
  const root = nodeById(graph.nodes, request.nodeId);
  if (!root) return null;

  const nodes = graph.nodes.filter((n) => !n.data.isDraft);
  const byId = new Map(nodes.map((n) => [n.id, n]));
  const edges = graph.edges.filter((e) => !e.isDraft && byId.has(e.source) && byId.has(e.target));
  const outgoing = new Map<string, DependencyEdge[]>();
  const incoming = new Map<string, DependencyEdge[]>();
  for (const e of edges) {
    (outgoing.get(e.source) ?? outgoing.set(e.source, []).get(e.source)!).push(e);
    (incoming.get(e.target) ?? incoming.set(e.target, []).get(e.target)!).push(e);
  }

  const depth = new Map<string, number>([[root.id, 0]]);
  const used = new Set<string>();
  const queue = [root.id];

  const visit = (from: string, to: string, edge: DependencyEdge) => {
    used.add(edge.id);
    if (depth.has(to)) return;
    depth.set(to, depth.get(from)! + 1);
    queue.push(to);
  };

  for (let head = 0; head < queue.length; head++) {
    const id = queue[head]!;
    const node = byId.get(id)!;
    if (request.mode === "upstream") {
      if (isData(node)) for (const e of incoming.get(id) ?? []) if (e.relation === "writes") visit(id, e.source, e);
      if (!isData(node)) for (const e of outgoing.get(id) ?? []) if (e.relation !== "writes") visit(id, e.target, e);
    } else {
      for (const e of incoming.get(id) ?? []) if (e.relation !== "writes") visit(id, e.source, e);
      if (!isData(node)) for (const e of outgoing.get(id) ?? []) if (e.relation === "writes") visit(id, e.target, e);
    }
  }

  const hasWriter = (id: string) => (incoming.get(id) ?? []).some((e) => e.relation === "writes");
  const label = (id: string) => byId.get(id)!.data.label;

  const roleOf = (id: string): TraceRole => {
    if (id === root.id) return "target";
    const node = byId.get(id)!;
    if (!isData(node)) return "code";
    return hasWriter(id) ? "produced" : "input";
  };

  // Same depth: raw inputs, then code, then intermediate files, then the target, so it reads as a pipeline.
  const ROLE_RANK: Record<TraceRole, number> = { input: 0, code: 1, produced: 2, target: 3 };
  const steps: TraceStep[] = [...depth.entries()]
    .map(([nodeId, d]) => ({ nodeId, depth: d, role: roleOf(nodeId) }))
    .sort(
      (a, b) =>
        (request.mode === "upstream" ? b.depth - a.depth : a.depth - b.depth) ||
        ROLE_RANK[a.role] - ROLE_RANK[b.role] ||
        label(a.nodeId).localeCompare(label(b.nodeId)),
    );

  const others = steps.filter((s) => s.nodeId !== root.id);
  return {
    ...request,
    nodeIds: steps.map((s) => s.nodeId),
    edgeIds: [...used],
    steps,
    rawInputs: request.mode === "upstream" ? others.filter((s) => s.role === "input").map((s) => s.nodeId) : [],
    results: request.mode === "downstream" ? others.filter((s) => isData(byId.get(s.nodeId)!)).map((s) => s.nodeId) : [],
  };
}

/* ---------- Plain language ---------- */

export type TraceDescription = { headline: string; lines: string[] };

const MAX_NAMED = 6;

function names(labels: string[], max = MAX_NAMED): string {
  return labels.length <= max ? labels.join(", ") : `${labels.slice(0, max).join(", ")} and ${labels.length - max} more`;
}

function plural(n: number, one: string, many = `${one}s`): string {
  return `${n} ${n === 1 ? one : many}`;
}

/** Everyday-language summary of a trace. Deterministic; no AI. */
export function describeTrace(graph: ArchitectureGraph, trace: Trace): TraceDescription {
  const label = (id: string) => nodeById(graph.nodes, id)?.data.label ?? id;
  const root = nodeById(graph.nodes, trace.nodeId)!;
  const others = trace.steps.filter((s) => s.nodeId !== trace.nodeId);
  const edges = graph.edges.filter((e) => !e.isDraft);

  if (trace.mode === "upstream") {
    if (others.length === 0) {
      return { headline: `${root.data.label} does not come from anything else in this map.`, lines: ["It has no inputs and no producing code here; it may be a raw input itself."] };
    }
    const writers = edges.filter((e) => e.target === trace.nodeId && e.relation === "writes").map((e) => label(e.source));
    const code = others.filter((s) => s.role === "code" && !writers.includes(label(s.nodeId))).map((s) => label(s.nodeId));
    const produced = others.filter((s) => s.role === "produced").map((s) => label(s.nodeId));
    const lines: string[] = [];
    if (code.length) lines.push(`Along the way it uses ${names(code)}.`);
    if (produced.length) lines.push(`It passes through ${plural(produced.length, "intermediate file")}: ${names(produced)}.`);
    if (trace.rawInputs.length) lines.push(`It starts from ${plural(trace.rawInputs.length, "input file")}: ${names(trace.rawInputs.map(label))}.`);
    else lines.push("No raw input files were found upstream.");
    return {
      headline: writers.length ? `${root.data.label} is produced by ${names(writers)}.` : `${root.data.label} draws on ${plural(others.length, "other component")}.`,
      lines,
    };
  }

  if (others.length === 0) {
    return { headline: `Nothing else in this map uses ${root.data.label} or anything derived from it.`, lines: ["Changing it affects only itself."] };
  }
  const code = others.filter((s) => !isDataNode(graph, s.nodeId)).map((s) => label(s.nodeId));
  const lines: string[] = [];
  if (code.length) lines.push(`Code that uses it, directly or indirectly: ${names(code)}.`);
  if (trace.results.length) lines.push(`Results that would be out of date: ${names(trace.results.map(label))}.`);
  else lines.push("It produces no output files in this map.");
  return { headline: `Changing ${root.data.label} can affect ${plural(others.length, "other component")}.`, lines };
}

function isDataNode(graph: ArchitectureGraph, id: string): boolean {
  return nodeById(graph.nodes, id)?.data.kind === "data";
}

import { findCycles } from "@/lib/engines/health";
import { nodeById } from "@/lib/graph";
import type { ArchitectureGraph, ArchNode, ArchRule, RuleViolation } from "@/lib/types";

/** Compile a glob (`**` any depth, `*` within a segment, `?` one character) to an anchored RegExp. */
export function globToRegExp(glob: string): RegExp {
  let source = "";
  for (let i = 0; i < glob.length; i++) {
    const ch = glob[i]!;
    if (ch === "*") {
      if (glob[i + 1] === "*") {
        source += ".*";
        i++;
        if (glob[i + 1] === "/") i++; // `**/` also matches zero directories
      } else source += "[^/]*";
    } else if (ch === "?") source += "[^/]";
    else source += ch.replace(/[.+^${}()|[\]\\]/g, "\\$&");
  }
  return new RegExp(`^${source}$`, "i");
}

function normalizePath(path: string): string {
  return path.replace(/\\/g, "/").replace(/^\.\//, "");
}

/** Does `node` match one selector? See `ArchRule` for the grammar. */
function matchesOne(node: ArchNode, alternative: string): boolean {
  const text = alternative.trim();
  if (text === "*" || text === "any") return true;
  const colon = text.indexOf(":");
  const key = colon > 0 ? text.slice(0, colon).toLowerCase() : "";
  const value = colon > 0 ? text.slice(colon + 1).trim() : text;
  const path = normalizePath(node.data.filePath);

  switch (key) {
    case "kind":
      return node.data.kind === value.toLowerCase();
    case "id":
      return node.id === value;
    case "path":
      return globToRegExp(normalizePath(value)).test(path);
    case "label":
      return globToRegExp(value).test(node.data.label);
    default:
      // A bare word is a friendly shorthand: a label or a path.
      return globToRegExp(value).test(node.data.label) || globToRegExp(normalizePath(value)).test(path);
  }
}

export function matchesSelector(node: ArchNode, selector: string): boolean {
  return selector.split("|").some((alt) => matchesOne(node, alt));
}

function lineCountOf(node: ArchNode): number {
  return node.data.lineCount ?? (node.data.code ? node.data.code.split("\n").length : 0);
}

/**
 * Check a graph against rules. Pure; builder drafts are ignored. `graph.rules` is used
 * unless `rules` is passed (the CLI loads them from `.codearchitect.json`).
 */
export function evaluateRules(graph: ArchitectureGraph, rules: readonly ArchRule[] = graph.rules ?? []): RuleViolation[] {
  const nodes = graph.nodes.filter((n) => !n.data.isDraft);
  const ids = new Set(nodes.map((n) => n.id));
  const edges = graph.edges.filter((e) => !e.isDraft && ids.has(e.source) && ids.has(e.target));
  const label = (id: string) => nodeById(nodes, id)?.data.label ?? id;
  const violations: RuleViolation[] = [];

  for (const rule of rules) {
    const severity = rule.severity ?? "error";

    if (rule.type === "forbid") {
      for (const edge of edges) {
        const from = nodeById(nodes, edge.source)!;
        const to = nodeById(nodes, edge.target)!;
        if (!matchesSelector(from, rule.from) || !matchesSelector(to, rule.to)) continue;
        violations.push({
          ruleId: rule.id, ruleType: rule.type,
          severity,
          message: `${rule.message ?? "Forbidden dependency"}: ${label(edge.source)} → ${label(edge.target)}`,
          nodeIds: [edge.source, edge.target],
          edgeIds: [edge.id],
        });
      }
    } else if (rule.type === "no-cycles") {
      for (const group of findCycles([...ids], edges)) {
        const inGroup = new Set(group);
        violations.push({
          ruleId: rule.id, ruleType: rule.type,
          severity,
          message: `${rule.message ?? "Circular dependency"}: ${group.map(label).join(" ↔ ")}`,
          nodeIds: group,
          edgeIds: edges.filter((e) => inGroup.has(e.source) && inGroup.has(e.target)).map((e) => e.id),
        });
      }
    } else if (rule.type === "max-dependents") {
      for (const node of nodes) {
        if (rule.selector && !matchesSelector(node, rule.selector)) continue;
        const dependents = new Set(edges.filter((e) => e.target === node.id).map((e) => e.source));
        if (dependents.size > rule.limit) {
          violations.push({
            ruleId: rule.id, ruleType: rule.type,
            severity,
            message: `${rule.message ?? "Too many dependents"}: ${node.data.label} has ${dependents.size} (limit ${rule.limit})`,
            nodeIds: [node.id],
            edgeIds: [],
          });
        }
      }
    } else {
      for (const node of nodes) {
        if (rule.selector && !matchesSelector(node, rule.selector)) continue;
        const lines = lineCountOf(node);
        if (lines > rule.limit) {
          violations.push({
            ruleId: rule.id, ruleType: rule.type,
            severity,
            message: `${rule.message ?? "File too large"}: ${node.data.label} has ${lines.toLocaleString()} lines (limit ${rule.limit.toLocaleString()})`,
            nodeIds: [node.id],
            edgeIds: [],
          });
        }
      }
    }
  }
  return violations;
}

/** Stable identity of a violation, so a PR check can tell new ones from old ones. */
export function violationKey(v: RuleViolation): string {
  return `${v.ruleId}|${[...v.edgeIds, ...v.nodeIds].sort().join(",")}`;
}

import * as z from "zod/v4";

const MAX_RULES = 50;
const MAX_SELECTOR_CHARS = 300;
const MAX_MESSAGE_CHARS = 300;

const id = z.string().min(1).max(80).regex(/^[A-Za-z0-9._-]+$/, "use letters, digits, . _ - only");
const selector = z.string().min(1).max(MAX_SELECTOR_CHARS);
const message = z.string().max(MAX_MESSAGE_CHARS).optional();
const severity = z.enum(["error", "warn"]).optional();

export const RuleSchema = z.discriminatedUnion("type", [
  z.object({ id, type: z.literal("forbid"), from: selector, to: selector, message, severity }),
  z.object({ id, type: z.literal("no-cycles"), message, severity }),
  z.object({ id, type: z.literal("max-dependents"), limit: z.number().int().nonnegative(), selector: selector.optional(), message, severity }),
  z.object({ id, type: z.literal("max-lines"), limit: z.number().int().positive(), selector: selector.optional(), message, severity }),
]);

export const RulesSchema = z
  .array(RuleSchema)
  .max(MAX_RULES)
  .refine((rules) => new Set(rules.map((r) => r.id)).size === rules.length, "rule ids must be unique");

/** Parse rules from JSON text with a message a person can act on. */
export function parseRulesJson(text: string): { ok: true; rules: z.infer<typeof RulesSchema> } | { ok: false; error: string } {
  let json: unknown;
  try {
    json = JSON.parse(text);
  } catch (error) {
    return { ok: false, error: `Not valid JSON: ${error instanceof Error ? error.message : "parse error"}` };
  }
  const candidate = Array.isArray(json) ? json : (json as { rules?: unknown } | null)?.rules;
  const parsed = RulesSchema.safeParse(candidate);
  if (parsed.success) return { ok: true, rules: parsed.data };
  const issue = parsed.error.issues[0];
  const [first, ...rest] = issue?.path ?? [];
  const where = first === undefined ? "rules" : `rule ${typeof first === "number" ? first + 1 : String(first)} → ${rest.map(String).join(".") || "(rule)"}`;
  return { ok: false, error: `${where}: ${issue?.message ?? "invalid"}` };
}

