import "server-only";
import { NextResponse } from "next/server";
import type * as z from "zod/v4";
import { describeAiError, getAiStatus } from "@/lib/server/ai";

export type ApiSuccess<T> = { ok: true; data: T; warning?: string };
export type ApiFailure = { ok: false; error: string };

export function fail(error: string, status: number): NextResponse<ApiFailure> {
  return NextResponse.json({ ok: false, error }, { status });
}

export async function parseBody<Schema extends z.ZodType>(
  request: Request,
  schema: Schema,
): Promise<{ data: z.infer<Schema> } | { error: NextResponse<ApiFailure> }> {
  let json: unknown;
  try {
    json = await request.json();
  } catch {
    return { error: fail("Request body must be valid JSON.", 400) };
  }
  const parsed = schema.safeParse(json);
  if (!parsed.success) {
    const issue = parsed.error.issues[0];
    return { error: fail(`Invalid request: ${issue?.path.join(".") || "body"} — ${issue?.message ?? "invalid"}`, 400) };
  }
  return { data: parsed.data };
}

/**
 * Prefer the configured AI provider; on any failure (or a broken configuration)
 * fall back to the deterministic engine and surface why, so the UI never dead-ends.
 */
export async function runWithFallback<T>(
  withAi: () => Promise<T>,
  locally: () => T | Promise<T>,
): Promise<NextResponse<ApiSuccess<T> | ApiFailure>> {
  let warning: string | undefined;
  const status = getAiStatus();
  if (status.state === "misconfigured") {
    warning = `AI provider misconfigured: ${status.error} Showing the local engine's result instead.`;
  } else if (status.state === "enabled") {
    try {
      return NextResponse.json({ ok: true, data: await withAi() });
    } catch (error) {
      warning = `${describeAiError(error)} Showing the local engine's result instead.`;
      console.error(`[codearchitect] ${status.label} call failed:`, error);
    }
  }
  try {
    return NextResponse.json({ ok: true, data: await locally(), warning });
  } catch (error) {
    return fail(error instanceof Error ? error.message : "Analysis failed.", 422);
  }
}

import "server-only";
import { collectDependents, layoutByKind, nodeById } from "@/lib/graph";
import { computeRiskScore } from "@/lib/engines/localImpact";
import { selectGraphFiles, truncateCode } from "@/lib/engines/heuristicGraph";
import { getGenerator } from "@/lib/server/ai";
import { describeProvider as describeGenerator } from "@/lib/server/ai/config";
import { AiImpactSchema, AiIngestSchema, AiScaffoldSchema, AiStorySchema } from "@/lib/server/schemas";
import type {
  ArchitectureGraph,
  ArchNode,
  DependencyEdge,
  ImpactAnalysisResult,
  NodeImpact,
  ScaffoldResult,
  SourceFile,
  StoryNarrative,
} from "@/lib/types";

const RISK_SCORE_MAX = 100;
const TRUNCATION_MARKER = "\n// … truncated to fit the model's context window";

/**
 * Cap each node's code so the whole graph fits the provider's input budget (small
 * local models have small windows). Returns the IDs whose code was cut, so callers
 * can refuse model-written "after" files that were based on partial code.
 */
function codeWithinBudget(graph: ArchitectureGraph, budgetChars: number): { code: Map<string, string>; truncated: Set<string> } {
  const total = graph.nodes.reduce((sum, n) => sum + n.data.code.length, 0);
  const perNode = total <= budgetChars ? Infinity : Math.floor(budgetChars / Math.max(1, graph.nodes.length));
  const code = new Map<string, string>();
  const truncated = new Set<string>();
  for (const n of graph.nodes) {
    if (n.data.code.length <= perNode) {
      code.set(n.id, n.data.code);
    } else {
      code.set(n.id, n.data.code.slice(0, perNode) + TRUNCATION_MARKER);
      truncated.add(n.id);
    }
  }
  return { code, truncated };
}

function serializeGraph(graph: ArchitectureGraph, code: ReadonlyMap<string, string> | null): string {
  const nodes = graph.nodes.map((n) => {
    const head = `<component id="${n.id}" kind="${n.data.kind}" path="${n.data.filePath}"${n.data.isDraft ? ' draft="true"' : ""}>\n` +
      `label: ${n.data.label}\ndescription: ${n.data.description}\nexports: ${n.data.exports.join(", ") || "-"}`;
    return code ? `${head}\n<code>\n${code.get(n.id) ?? ""}\n</code>\n</component>` : `${head}\n</component>`;
  });
  const edges = graph.edges.map((e) => `${e.source} -> ${e.target} (${e.relation}${e.label ? `: ${e.label}` : ""})${e.isDraft ? " [new]" : ""}`);
  return `<architecture name="${graph.name}">\n${nodes.join("\n")}\n<dependencies note="source depends on target">\n${edges.join("\n")}\n</dependencies>\n</architecture>`;
}

const SHARED_RULES =
  "Component IDs in your answer must be copied exactly from the input. Code you write must be complete files, not fragments, and must match the conventions already used in the codebase. Do not invent components that are not in the input.";

export async function analyzeImpactWithAi(
  graph: ArchitectureGraph,
  prompt: string,
  selectedNodeId: string | null,
): Promise<ImpactAnalysisResult> {
  const generator = getGenerator();
  const { code, truncated } = codeWithinBudget(graph, generator.config.maxInputChars);
  const result = await generator.generate({
    schema: AiImpactSchema,
    schemaName: "impact_analysis",
    effort: "high",
    system: `You are a principal engineer performing refactoring impact analysis on a dependency graph. Identify the component where the requested change originates, every component that must change or will break as a consequence (including non-obvious couplings such as serialized payloads, cache contents and token claims), and write the concrete updated code for each affected file. Severity: "modified" = origin, "broken" = will fail to compile or misbehave without edits, "impacted" = needs review or a smaller edit. ${SHARED_RULES}`,
    prompt: `${serializeGraph(graph, code)}\n\n<selected_component>${selectedNodeId ?? "none"}</selected_component>\n<change_request>${prompt}</change_request>`,
  });

  const rootNodeId = nodeById(graph.nodes, result.rootNodeId) ? result.rootNodeId : selectedNodeId;
  if (!rootNodeId) throw new Error(`${generator.config.model} did not identify a valid origin component.`);

  const depths = collectDependents(rootNodeId, graph.edges);
  const seen = new Set<string>();
  const impacts: NodeImpact[] = result.impacts
    .filter((i) => nodeById(graph.nodes, i.nodeId) && !seen.has(i.nodeId) && seen.add(i.nodeId))
    .map((i) => ({ ...i, severity: i.nodeId === rootNodeId ? "modified" : i.severity, depth: depths.get(i.nodeId) ?? 1 }));
  if (!seen.has(rootNodeId)) impacts.unshift({ nodeId: rootNodeId, severity: "modified", depth: 0, reason: "Origin of the change." });
  impacts.sort((a, b) => a.depth - b.depth);

  return {
    prompt,
    rootNodeId,
    summary: result.summary,
    riskScore: Number.isFinite(result.riskScore)
      ? Math.max(0, Math.min(RISK_SCORE_MAX, Math.round(result.riskScore)))
      : computeRiskScore(impacts, graph.nodes.length),
    impacts,
    // An "after" written from truncated code would silently delete the unseen remainder.
    diffs: result.diffs.flatMap((d) => {
      const node = nodeById(graph.nodes, d.nodeId);
      return node && !truncated.has(d.nodeId)
        ? [{ nodeId: d.nodeId, filePath: node.data.filePath, before: node.data.code, after: d.after, rationale: d.rationale }]
        : [];
    }),
    engine: "ai",
    engineLabel: describeGenerator(generator.config),
  };
}

export async function narrateStoryWithAi(graph: ArchitectureGraph): Promise<StoryNarrative> {
  if (graph.commits.length === 0) throw new Error("This repository has no commit history to narrate.");
  const label = (id: string) => nodeById(graph.nodes, id)?.data.label ?? id;
  const history = graph.commits
    .map((c) => `<commit hash="${c.hash}" date="${c.date}" author="${c.author}">\nmessage: ${c.message}\nadded: ${c.addedNodeIds.map(label).join(", ") || "-"}\nmodified: ${c.modifiedNodeIds.map(label).join(", ") || "-"}\n</commit>`)
    .join("\n");

  const generator = getGenerator();
  const result = await generator.generate({
    schema: AiStorySchema,
    schemaName: "story_narrative",
    effort: "medium",
    system:
      "You are a software archaeologist. Explain how this architecture evolved as a short narrative: for each commit, one titled phase that says what structurally changed and the most plausible engineering reason, and flag couplings or regressions a future maintainer should know. Ground every claim in the commit messages and component changes provided; say when a motive is inferred. Return one phase per commit, using the given hashes.",
    prompt: `${serializeGraph(graph, null)}\n\n<history order="oldest first">\n${history}\n</history>`,
  });

  const known = new Set(graph.commits.map((c) => c.hash));
  return { overview: result.overview, phases: result.phases.filter((p) => known.has(p.hash)), engine: "ai", engineLabel: describeGenerator(generator.config) };
}

export async function scaffoldWithAi(graph: ArchitectureGraph): Promise<ScaffoldResult> {
  const generator = getGenerator();
  const { code, truncated } = codeWithinBudget(graph, generator.config.maxInputChars);
  const result = await generator.generate({
    schema: AiScaffoldSchema,
    schemaName: "scaffold",
    effort: "high",
    system: `You generate production-quality scaffolding for new components drawn on an architecture diagram. Components marked draft="true" do not exist yet: write one complete file for each at its given path. Dependencies marked [new] must be wired: edit every existing (non-draft) source file of a [new] dependency so it actually uses the new target. Handle errors explicitly and keep each file focused. ${SHARED_RULES}`,
    prompt: serializeGraph(graph, code),
  });

  const drafts = new Set(graph.nodes.filter((n) => n.data.isDraft).map((n) => n.id));
  return {
    summary: result.summary,
    files: result.files.filter((f) => drafts.has(f.nodeId)),
    diffs: result.edits.flatMap((e) => {
      const node = nodeById(graph.nodes, e.nodeId);
      return node && !drafts.has(e.nodeId) && !truncated.has(e.nodeId)
        ? [{ nodeId: e.nodeId, filePath: node.data.filePath, before: node.data.code, after: e.after, rationale: e.rationale }]
        : [];
    }),
    engine: "ai",
    engineLabel: describeGenerator(generator.config),
  };
}

/** Pack as many whole files as fit the budget; report exactly what was left out. */
function packSources(files: readonly SourceFile[], budgetChars: number): { packed: SourceFile[]; omitted: number } {
  const packed: SourceFile[] = [];
  let budget = budgetChars;
  for (const file of files) {
    if (file.content.length > budget) continue;
    packed.push(file);
    budget -= file.content.length;
  }
  return { packed, omitted: files.length - packed.length };
}

export async function ingestWithAi(name: string, files: readonly SourceFile[]): Promise<ArchitectureGraph> {
  const generator = getGenerator();
  const { selected, warnings } = selectGraphFiles(files);
  const { packed, omitted } = packSources(selected, generator.config.maxInputChars);
  if (omitted > 0) {
    warnings.push(
      `${omitted} file(s) did not fit ${generator.config.model}'s input budget (${generator.config.maxInputChars.toLocaleString()} chars); raise AI_MAX_INPUT_CHARS if the model's context allows.`,
    );
  }

  const result = await generator.generate({
    schema: AiIngestSchema,
    schemaName: "architecture_graph",
    effort: "medium",
    system:
      "You map a codebase into an architecture graph of 4-25 components. A component is an architectural unit (a page, an API route, a service/controller, a datastore or cache) anchored to one primary file. Edges point from the dependent to its dependency. Prefer meaningful units over one-node-per-file; use only file paths that appear in the input.",
    prompt: packed.map((f) => `<file path="${f.path}">\n${f.content}\n</file>`).join("\n"),
  });

  const byPath = new Map(files.map((f) => [f.path, f.content]));
  const seenIds = new Set<string>();
  const nodes: ArchNode[] = result.components
    .filter((c) => byPath.has(c.filePath) && !seenIds.has(c.id) && Boolean(seenIds.add(c.id)))
    .map((c) => ({
      id: c.id,
      type: "component",
      position: { x: 0, y: 0 },
      data: {
        label: c.label,
        kind: c.kind,
        filePath: c.filePath,
        description: c.description,
        language: c.filePath.split(".").pop() ?? "text",
        code: truncateCode(byPath.get(c.filePath) ?? ""),
        exports: c.exports,
        imports: [],
        params: c.params,
        keywords: c.keywords,
      },
    }));
  const ids = new Set(nodes.map((n) => n.id));
  const edges: DependencyEdge[] = result.edges
    .filter((e) => ids.has(e.source) && ids.has(e.target) && e.source !== e.target)
    .map((e, i) => ({ id: `e-${i}-${e.source}--${e.target}`, ...e }));

  return {
    id: `import-${name.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-${Date.now().toString(36)}`,
    name,
    description: `${result.description} (mapped by ${describeGenerator(generator.config)})`,
    nodes: layoutByKind(nodes),
    edges,
    commits: [],
    scenarios: [],
    warnings,
  };
}

import "server-only";
import { AnthropicGenerator, describeAnthropicError } from "@/lib/server/ai/anthropic";
import { describeProvider, ProviderConfigError, resolveProviderConfig, type ProviderConfig } from "@/lib/server/ai/config";
import { describeOpenAIError, OpenAICompatibleGenerator } from "@/lib/server/ai/openaiCompatible";
import { ModelResponseError, type StructuredGenerator } from "@/lib/server/ai/types";

export type AiStatus =
  | { state: "enabled"; config: ProviderConfig; label: string }
  | { state: "disabled" }
  | { state: "misconfigured"; error: string };

export function getAiStatus(): AiStatus {
  try {
    const config = resolveProviderConfig(process.env);
    return config ? { state: "enabled", config, label: describeProvider(config) } : { state: "disabled" };
  } catch (error) {
    if (error instanceof ProviderConfigError) return { state: "misconfigured", error: error.message };
    throw error;
  }
}

let cached: { key: string; generator: StructuredGenerator } | null = null;

/** The generator for the current configuration, or an error explaining why there is none. */
export function getGenerator(): StructuredGenerator {
  const status = getAiStatus();
  if (status.state === "misconfigured") throw new ProviderConfigError(status.error);
  if (status.state === "disabled") throw new ProviderConfigError("No AI provider is configured.");

  const { config } = status;
  const key = JSON.stringify([config.provider, config.model, config.baseURL, config.apiKey ? "key" : "nokey"]);
  if (cached?.key !== key) {
    cached = {
      key,
      generator: config.protocol === "anthropic" ? new AnthropicGenerator(config) : new OpenAICompatibleGenerator(config),
    };
  }
  return cached.generator;
}

/** Short, user-safe description of a provider failure; never echoes keys or raw payloads. */
export function describeAiError(error: unknown): string {
  if (error instanceof ProviderConfigError || error instanceof ModelResponseError) return error.message;
  const status = getAiStatus();
  const label = status.state === "enabled" ? status.config.label : "The AI provider";
  return describeAnthropicError(error) ?? describeOpenAIError(error, label) ?? (error instanceof Error ? error.message : "Unknown error while calling the AI provider.");
}

export type { Effort, StructuredGenerator } from "@/lib/server/ai/types";

/**
 * Provider selection, as a pure function of the environment so it is testable.
 *
 * Two wire protocols cover every supported provider:
 * - "anthropic": the Anthropic Messages API (Claude).
 * - "openai-compatible": the OpenAI Chat Completions API, which OpenAI, Google Gemini,
 *   Ollama, LM Studio, OpenRouter, Groq and DeepSeek all expose.
 */

export type Protocol = "anthropic" | "openai-compatible";

export type ProviderId =
  | "anthropic"
  | "openai"
  | "gemini"
  | "ollama"
  | "lmstudio"
  | "openrouter"
  | "groq"
  | "deepseek"
  | "custom";

type Preset = {
  label: string;
  protocol: Protocol;
  defaultModel?: string;
  baseURL?: string;
  /** Env var holding this provider's key; `AI_API_KEY` always overrides it. */
  keyEnv?: string;
  /** Local servers accept any key; a placeholder keeps the SDK from refusing to start. */
  requiresKey: boolean;
  /** Uses OpenAI's newer `max_completion_tokens` / `reasoning_effort` parameters. */
  openaiReasoningParams?: boolean;
  /** Characters of source the repo-ingestion prompt may carry (context-window budget). */
  maxInputChars: number;
};

const LARGE_CONTEXT_CHARS = 600_000;
const MEDIUM_CONTEXT_CHARS = 200_000;
/** Local models often run with 8k–32k token windows; stay well inside them. */
const LOCAL_CONTEXT_CHARS = 40_000;

export const PROVIDER_PRESETS: Record<ProviderId, Preset> = {
  anthropic: { label: "Anthropic", protocol: "anthropic", defaultModel: "claude-opus-5-5", keyEnv: "ANTHROPIC_API_KEY", requiresKey: true, maxInputChars: LARGE_CONTEXT_CHARS },
  openai: { label: "OpenAI", protocol: "openai-compatible", baseURL: "https://api.openai.com/v1", keyEnv: "OPENAI_API_KEY", requiresKey: true, openaiReasoningParams: true, maxInputChars: MEDIUM_CONTEXT_CHARS },
  gemini: { label: "Google Gemini", protocol: "openai-compatible", baseURL: "https://generativelanguage.googleapis.com/v1beta/openai/", keyEnv: "GEMINI_API_KEY", requiresKey: true, maxInputChars: LARGE_CONTEXT_CHARS },
  ollama: { label: "Ollama", protocol: "openai-compatible", baseURL: "http://localhost:11434/v1", requiresKey: false, maxInputChars: LOCAL_CONTEXT_CHARS },
  lmstudio: { label: "LM Studio", protocol: "openai-compatible", baseURL: "http://localhost:1234/v1", requiresKey: false, maxInputChars: LOCAL_CONTEXT_CHARS },
  openrouter: { label: "OpenRouter", protocol: "openai-compatible", baseURL: "https://openrouter.ai/api/v1", keyEnv: "OPENROUTER_API_KEY", requiresKey: true, maxInputChars: MEDIUM_CONTEXT_CHARS },
  groq: { label: "Groq", protocol: "openai-compatible", baseURL: "https://api.groq.com/openai/v1", keyEnv: "GROQ_API_KEY", requiresKey: true, maxInputChars: MEDIUM_CONTEXT_CHARS },
  deepseek: { label: "DeepSeek", protocol: "openai-compatible", baseURL: "https://api.deepseek.com/v1", keyEnv: "DEEPSEEK_API_KEY", requiresKey: true, maxInputChars: MEDIUM_CONTEXT_CHARS },
  custom: { label: "Custom endpoint", protocol: "openai-compatible", requiresKey: false, maxInputChars: MEDIUM_CONTEXT_CHARS },
};

export type ProviderConfig = {
  provider: ProviderId;
  label: string;
  protocol: Protocol;
  model: string;
  baseURL?: string;
  apiKey?: string;
  openaiReasoningParams: boolean;
  maxInputChars: number;
};

export type Env = Readonly<Record<string, string | undefined>>;

export class ProviderConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ProviderConfigError";
  }
}

/** With no AI_PROVIDER, the first provider whose key is present wins, in this order. */
const AUTO_DETECT_ORDER: ProviderId[] = ["anthropic", "openai", "gemini", "openrouter", "groq", "deepseek"];

function isProviderId(value: string): value is ProviderId {
  return value in PROVIDER_PRESETS;
}

function nonEmpty(value: string | undefined): string | undefined {
  const trimmed = value?.trim();
  return trimmed ? trimmed : undefined;
}

/**
 * Resolve which model provider to use, or `null` for the local engine.
 *
 * - `CODEARCHITECT_ENGINE=local` always disables AI.
 * - `AI_PROVIDER` picks a provider explicitly (required for keyless local servers like Ollama).
 * - Otherwise the first provider with a key in the environment is used.
 * - `CODEARCHITECT_ENGINE=claude` (legacy) forces Anthropic even without a key env var,
 *   so an `ant auth login` profile can supply credentials.
 *
 * Throws `ProviderConfigError` for an explicit but incomplete configuration, so a typo
 * fails loudly instead of silently falling back to the local engine.
 */
export function resolveProviderConfig(env: Env): ProviderConfig | null {
  const engine = (nonEmpty(env.CODEARCHITECT_ENGINE) ?? "auto").toLowerCase();
  if (engine === "local") return null;

  const requested = nonEmpty(env.AI_PROVIDER)?.toLowerCase();
  let provider: ProviderId | undefined;
  if (requested) {
    if (!isProviderId(requested)) {
      throw new ProviderConfigError(`Unknown AI_PROVIDER "${requested}". Use one of: ${Object.keys(PROVIDER_PRESETS).join(", ")}.`);
    }
    provider = requested;
  } else if (engine === "claude") {
    provider = "anthropic";
  } else {
    provider = AUTO_DETECT_ORDER.find((id) => nonEmpty(env[PROVIDER_PRESETS[id].keyEnv ?? ""]));
  }
  if (!provider) return null;

  const preset = PROVIDER_PRESETS[provider];
  const apiKey = nonEmpty(env.AI_API_KEY) ?? (preset.keyEnv ? nonEmpty(env[preset.keyEnv]) : undefined);
  const model = nonEmpty(env.AI_MODEL) ?? preset.defaultModel;
  const baseURL = nonEmpty(env.AI_BASE_URL) ?? preset.baseURL;

  if (!model) throw new ProviderConfigError(`${preset.label} needs a model name: set AI_MODEL (e.g. AI_MODEL=llama3.1 for Ollama).`);
  if (preset.protocol === "openai-compatible" && !baseURL) {
    throw new ProviderConfigError(`${preset.label} needs AI_BASE_URL (an OpenAI-compatible endpoint, e.g. http://localhost:8000/v1).`);
  }
  // Anthropic may authenticate from an `ant` profile when forced via CODEARCHITECT_ENGINE=claude.
  const keyOptional = !preset.requiresKey || (provider === "anthropic" && engine === "claude");
  if (!apiKey && !keyOptional) {
    throw new ProviderConfigError(`${preset.label} needs an API key: set ${preset.keyEnv ?? "AI_API_KEY"} (or AI_API_KEY).`);
  }

  const maxInputChars = Number(nonEmpty(env.AI_MAX_INPUT_CHARS));
  return {
    provider,
    label: preset.label,
    protocol: preset.protocol,
    model,
    baseURL,
    apiKey,
    openaiReasoningParams: Boolean(preset.openaiReasoningParams),
    maxInputChars: Number.isFinite(maxInputChars) && maxInputChars > 0 ? maxInputChars : preset.maxInputChars,
  };
}

/** Human-readable engine label, e.g. "llama3.1 · Ollama". */
export function describeProvider(config: ProviderConfig): string {
  return `${config.model} · ${config.label}`;
}

import * as z from "zod/v4";

/**
 * Pull a JSON value out of a model reply. Models without native structured output
 * often wrap JSON in ```json fences or add a sentence before/after it.
 */
export function extractJson(text: string): unknown {
  const trimmed = text.trim();
  const fenced = /```(?:json)?\s*([\s\S]*?)```/i.exec(trimmed)?.[1];
  const candidates = [fenced, trimmed, sliceOutermost(trimmed, "{", "}"), sliceOutermost(trimmed, "[", "]")];
  for (const candidate of candidates) {
    if (!candidate) continue;
    try {
      return JSON.parse(candidate);
    } catch {
      // try the next candidate
    }
  }
  throw new SyntaxError("The model reply did not contain valid JSON.");
}

function sliceOutermost(text: string, open: string, close: string): string | undefined {
  const start = text.indexOf(open);
  const end = text.lastIndexOf(close);
  return start >= 0 && end > start ? text.slice(start, end + 1) : undefined;
}

export type ParseOutcome<T> = { ok: true; value: T } | { ok: false; error: string };

/** Parse and validate; the error string is phrased so it can be fed back to the model for a retry. */
export function parseStructured<Schema extends z.ZodType>(text: string, schema: Schema): ParseOutcome<z.infer<Schema>> {
  let json: unknown;
  try {
    json = extractJson(text);
  } catch (error) {
    return { ok: false, error: error instanceof Error ? error.message : "Invalid JSON." };
  }
  const parsed = schema.safeParse(json);
  if (parsed.success) return { ok: true, value: parsed.data };
  const issues = parsed.error.issues
    .slice(0, 5)
    .map((issue) => `${issue.path.join(".") || "(root)"}: ${issue.message}`)
    .join("; ");
  return { ok: false, error: `JSON did not match the schema — ${issues}` };
}

/** JSON Schema for prompts and `response_format`, generated from the same Zod schema used to validate. */
export function jsonSchemaFor(schema: z.ZodType): Record<string, unknown> {
  return z.toJSONSchema(schema) as Record<string, unknown>;
}

import Anthropic from "@anthropic-ai/sdk";
import { betaZodOutputFormat } from "@anthropic-ai/sdk/helpers/beta/zod";
import type * as z from "zod/v4";
import type { ProviderConfig } from "@/lib/server/ai/config";
import { MAX_OUTPUT_TOKENS, ModelResponseError, type GenerateOptions, type StructuredGenerator } from "@/lib/server/ai/types";

/** Re-run a policy decline on Anthropic's recommended fallback model, server-side. */
const FALLBACK_BETA = "server-side-fallback-2026-07-01";

export class AnthropicGenerator implements StructuredGenerator {
  private readonly client: Anthropic;

  constructor(readonly config: ProviderConfig) {
    // Without an explicit key the SDK resolves ANTHROPIC_AUTH_TOKEN or an `ant auth login` profile.
    this.client = config.apiKey ? new Anthropic({ apiKey: config.apiKey }) : new Anthropic();
  }

  async generate<Schema extends z.ZodType>(options: GenerateOptions<Schema>): Promise<z.infer<Schema>> {
    const response = await this.client.beta.messages.parse({
      model: this.config.model,
      max_tokens: MAX_OUTPUT_TOKENS,
      betas: [FALLBACK_BETA],
      fallbacks: "default",
      system: options.system,
      output_config: { effort: options.effort, format: betaZodOutputFormat(options.schema) },
      messages: [{ role: "user", content: options.prompt }],
    });

    if (response.stop_reason === "refusal") {
      throw new ModelResponseError(`The model declined this request (category: ${response.stop_details?.category ?? "unspecified"}).`);
    }
    if (response.stop_reason === "max_tokens") {
      throw new ModelResponseError("The answer exceeded the output limit; try a smaller scope.");
    }
    if (!response.parsed_output) {
      throw new ModelResponseError("The model returned output that did not match the expected schema.");
    }
    return response.parsed_output as z.infer<Schema>;
  }
}

export function describeAnthropicError(error: unknown): string | null {
  if (error instanceof Anthropic.AuthenticationError) return "Anthropic rejected the configured credentials.";
  if (error instanceof Anthropic.RateLimitError) return "Anthropic rate limit reached; retry shortly.";
  if (error instanceof Anthropic.BadRequestError) return `Anthropic rejected the request: ${error.message}`;
  if (error instanceof Anthropic.APIConnectionError) return "Could not reach the Anthropic API.";
  if (error instanceof Anthropic.APIError) return `Anthropic API error (${error.status ?? "unknown"}).`;
  return null;
}

import OpenAI from "openai";
import type { ChatCompletionCreateParamsNonStreaming, ChatCompletionMessageParam } from "openai/resources/chat/completions";
import type * as z from "zod/v4";
import type { ProviderConfig } from "@/lib/server/ai/config";
import { jsonSchemaFor, parseStructured } from "@/lib/server/ai/json";
import { MAX_OUTPUT_TOKENS, ModelResponseError, type Effort, type GenerateOptions, type StructuredGenerator } from "@/lib/server/ai/types";

/** Local servers ignore the key, but the SDK refuses to start without one. */
const PLACEHOLDER_API_KEY = "not-needed";
/** One corrective round-trip when the reply is not valid JSON for the schema. */
const MAX_REPAIR_ATTEMPTS = 1;

/**
 * Structured-output support varies by server, so degrade step by step:
 * strict JSON Schema → generic JSON mode → plain text. The schema is always
 * in the system prompt too, and every reply is validated with Zod regardless.
 */
type FormatMode = "json_schema" | "json_object" | "none";
const FORMAT_MODES: FormatMode[] = ["json_schema", "json_object", "none"];

function reasoningEffort(effort: Effort): "low" | "medium" | "high" {
  return effort === "xhigh" || effort === "max" ? "high" : effort;
}

export class OpenAICompatibleGenerator implements StructuredGenerator {
  private readonly client: OpenAI;
  /** Remember the best format a server accepted so later calls skip known failures. */
  private formatIndex = 0;

  constructor(readonly config: ProviderConfig) {
    this.client = new OpenAI({ apiKey: config.apiKey ?? PLACEHOLDER_API_KEY, baseURL: config.baseURL });
  }

  async generate<Schema extends z.ZodType>(options: GenerateOptions<Schema>): Promise<z.infer<Schema>> {
    const schemaJson = jsonSchemaFor(options.schema);
    const messages: ChatCompletionMessageParam[] = [
      {
        role: "system",
        content: `${options.system}\n\nRespond with a single JSON object only — no prose, no code fences — matching this JSON Schema:\n${JSON.stringify(schemaJson)}`,
      },
      { role: "user", content: options.prompt },
    ];

    for (let attempt = 0; ; attempt++) {
      const text = await this.complete(messages, options, schemaJson);
      const outcome = parseStructured(text, options.schema);
      if (outcome.ok) return outcome.value;
      if (attempt >= MAX_REPAIR_ATTEMPTS) {
        throw new ModelResponseError(`${this.config.model} did not return valid structured output: ${outcome.error}`);
      }
      messages.push({ role: "assistant", content: text }, { role: "user", content: `${outcome.error}. Reply again with only the corrected JSON object.` });
    }
  }

  private async complete(messages: ChatCompletionMessageParam[], options: GenerateOptions<z.ZodType>, schemaJson: Record<string, unknown>): Promise<string> {
    for (; this.formatIndex < FORMAT_MODES.length; this.formatIndex++) {
      const mode = FORMAT_MODES[this.formatIndex]!;
      try {
        const response = await this.client.chat.completions.create(this.buildRequest(messages, options, schemaJson, mode));
        const choice = response.choices[0];
        if (!choice) throw new ModelResponseError("The model returned no choices.");
        if (choice.finish_reason === "length") throw new ModelResponseError("The answer exceeded the output limit; try a smaller scope.");
        if (choice.finish_reason === "content_filter") throw new ModelResponseError("The provider's content filter blocked the answer.");
        const content = choice.message.content;
        if (!content) throw new ModelResponseError(choice.message.refusal ? `The model declined: ${choice.message.refusal}` : "The model returned an empty answer.");
        return content;
      } catch (error) {
        // A 400/422 on a structured-output request usually means "format not supported": try the next mode.
        const unsupportedFormat = error instanceof OpenAI.APIError && (error.status === 400 || error.status === 422) && mode !== "none";
        if (!unsupportedFormat) throw error;
      }
    }
    throw new ModelResponseError("The endpoint rejected every request format.");
  }

  private buildRequest(
    messages: ChatCompletionMessageParam[],
    options: GenerateOptions<z.ZodType>,
    schemaJson: Record<string, unknown>,
    mode: FormatMode,
  ): ChatCompletionCreateParamsNonStreaming {
    const request: ChatCompletionCreateParamsNonStreaming = { model: this.config.model, messages };
    if (this.config.openaiReasoningParams) {
      request.max_completion_tokens = MAX_OUTPUT_TOKENS;
      request.reasoning_effort = reasoningEffort(options.effort);
    } else {
      request.max_tokens = MAX_OUTPUT_TOKENS;
    }
    if (mode === "json_schema") {
      request.response_format = { type: "json_schema", json_schema: { name: options.schemaName, schema: schemaJson, strict: false } };
    } else if (mode === "json_object") {
      request.response_format = { type: "json_object" };
    }
    return request;
  }
}

export function describeOpenAIError(error: unknown, label: string): string | null {
  if (error instanceof OpenAI.AuthenticationError) return `${label} rejected the configured API key.`;
  if (error instanceof OpenAI.RateLimitError) return `${label} rate limit reached; retry shortly.`;
  if (error instanceof OpenAI.NotFoundError) return `${label} does not know that model — check AI_MODEL.`;
  if (error instanceof OpenAI.APIConnectionError) return `Could not reach ${label}${label === "Ollama" || label === "LM Studio" ? " — is it running?" : "."}`;
  if (error instanceof OpenAI.APIError) return `${label} API error (${error.status ?? "unknown"}).`;
  return null;
}

import "server-only";
import { MAX_ARCHIVE_BYTES } from "@/lib/engines/zip";

/** Only github.com repository URLs are accepted; the fetch host is fixed (no SSRF via user URLs). */
const GITHUB_REPO_URL = /^https:\/\/github\.com\/([A-Za-z0-9-]{1,39})\/([A-Za-z0-9._-]{1,100}?)(?:\.git)?(?:\/tree\/([A-Za-z0-9._\/-]{1,200}))?\/?$/;
const FETCH_TIMEOUT_MS = 30_000;

export type GithubRepoRef = { owner: string; repo: string; ref?: string };

export function parseGithubUrl(url: string): GithubRepoRef {
  const match = GITHUB_REPO_URL.exec(url.trim());
  if (!match) throw new Error("Expected a public repository URL like https://github.com/owner/repo (optionally /tree/<branch>).");
  return { owner: match[1]!, repo: match[2]!, ref: match[3] };
}

export async function downloadRepoArchive({ owner, repo, ref }: GithubRepoRef): Promise<ArrayBuffer> {
  const path = `/repos/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}/zipball${ref ? `/${ref.split("/").map(encodeURIComponent).join("/")}` : ""}`;
  const headers: Record<string, string> = { "User-Agent": "codearchitect-ai", Accept: "application/vnd.github+json" };
  if (process.env.GITHUB_TOKEN) headers.Authorization = `Bearer ${process.env.GITHUB_TOKEN}`;

  const response = await fetch(`https://api.github.com${path}`, { headers, redirect: "follow", signal: AbortSignal.timeout(FETCH_TIMEOUT_MS) });
  if (response.status === 404) throw new Error(`Repository ${owner}/${repo} not found or not public.`);
  if (response.status === 403 || response.status === 429) throw new Error("GitHub rate limit reached; set GITHUB_TOKEN or try later.");
  if (!response.ok) throw new Error(`GitHub returned ${response.status} for ${owner}/${repo}.`);

  const declared = Number(response.headers.get("content-length") ?? 0);
  if (declared > MAX_ARCHIVE_BYTES) throw new Error(`Repository archive exceeds ${MAX_ARCHIVE_BYTES / 1e6} MB.`);
  const buffer = await response.arrayBuffer();
  if (buffer.byteLength > MAX_ARCHIVE_BYTES) throw new Error(`Repository archive exceeds ${MAX_ARCHIVE_BYTES / 1e6} MB.`);
  return buffer;
}

